                riscv::CSR_HPM_COUNTER_31 :
        if (G6LCCfg.RVZihpm) begin
          csr_rdata = perf_data_i;
        end else begin
          read_access_exception = 1'b1;
        end

        riscv::CSR_HPM_COUNTER_3H,
                riscv::CSR_HPM_COUNTER_4H,
                riscv::CSR_HPM_COUNTER_5H,
                riscv::CSR_HPM_COUNTER_6H,
                riscv::CSR_HPM_COUNTER_7H,
                riscv::CSR_HPM_COUNTER_8H,
                riscv::CSR_HPM_COUNTER_9H,
                riscv::CSR_HPM_COUNTER_10H,
                riscv::CSR_HPM_COUNTER_11H,
                riscv::CSR_HPM_COUNTER_12H,
                riscv::CSR_HPM_COUNTER_13H,
                riscv::CSR_HPM_COUNTER_14H,
                riscv::CSR_HPM_COUNTER_15H,
                riscv::CSR_HPM_COUNTER_16H,
                riscv::CSR_HPM_COUNTER_17H,
                riscv::CSR_HPM_COUNTER_18H,
                riscv::CSR_HPM_COUNTER_19H,
                riscv::CSR_HPM_COUNTER_20H,
                riscv::CSR_HPM_COUNTER_21H,
                riscv::CSR_HPM_COUNTER_22H,
                riscv::CSR_HPM_COUNTER_23H,
                riscv::CSR_HPM_COUNTER_24H,
                riscv::CSR_HPM_COUNTER_25H,
                riscv::CSR_HPM_COUNTER_26H,
                riscv::CSR_HPM_COUNTER_27H,
                riscv::CSR_HPM_COUNTER_28H,
                riscv::CSR_HPM_COUNTER_29H,
                riscv::CSR_HPM_COUNTER_30H,
                riscv::CSR_HPM_COUNTER_31H :
        if (G6LCCfg.RVZihpm) begin
          if (G6LCCfg.IS_XLEN32) csr_rdata = perf_data_i;
          else read_access_exception = 1'b1;
        end else begin
          read_access_exception = 1'b1;
        end

        // custom (non RISC-V) cache control
        riscv::CSR_DCACHE: csr_rdata = dcache_q;
        riscv::CSR_ICACHE: csr_rdata = icache_q;
        // custom (non RISC-V) accelerator memory consistency mode
        riscv::CSR_ACC_CONS: begin
          if (G6LCCfg.EnableAccelerator) begin
            csr_rdata = acc_cons_q;
          end else begin
            read_access_exception = 1'b1;
          end
        end
        // Xg6lcai AI matrix CSRs (gated on AiCfg.MatrixEn)
        12'h801: begin  // aicfg
          if (G6LCCfg.AiCfg.MatrixEn) csr_rdata = aicfg_q;
          else read_access_exception = 1'b1;
        end
        12'h802: begin  // aistatus
          if (G6LCCfg.AiCfg.MatrixEn) csr_rdata = aistatus_q;
          else read_access_exception = 1'b1;
        end
        12'h803: begin  // aiscale
          if (G6LCCfg.AiCfg.MatrixEn) csr_rdata = aiscale_q;
          else read_access_exception = 1'b1;
        end
        12'h804: begin  // aizp
          if (G6LCCfg.AiCfg.MatrixEn) csr_rdata = aizp_q;
          else read_access_exception = 1'b1;
        end
        12'h5C0: begin  // aiqbase
          if (G6LCCfg.AiCfg.MatrixEn && G6LCCfg.AiCfg.Queues != 0) csr_rdata = aiqbase_q;
          else read_access_exception = 1'b1;
        end
        12'h5C1: begin  // aiqctl
          if (G6LCCfg.AiCfg.MatrixEn && G6LCCfg.AiCfg.Queues != 0) csr_rdata = aiqctl_q;
          else read_access_exception = 1'b1;
        end
        12'h5C2: begin  // aiqhead
          if (G6LCCfg.AiCfg.MatrixEn && G6LCCfg.AiCfg.Queues != 0) csr_rdata = aiqhead_q;
          else read_access_exception = 1'b1;
        end
        12'h7C8: begin  // aiperm
          if (G6LCCfg.AiCfg.MatrixEn) csr_rdata = aiperm_q;
          else read_access_exception = 1'b1;
        end
        // PMPs
        riscv::CSR_PMPCFG0,
                riscv::CSR_PMPCFG1,
                riscv::CSR_PMPCFG2,
                riscv::CSR_PMPCFG3,
                riscv::CSR_PMPCFG4,
                riscv::CSR_PMPCFG5,
                riscv::CSR_PMPCFG6,
                riscv::CSR_PMPCFG7,
                riscv::CSR_PMPCFG8,
                riscv::CSR_PMPCFG9,
                riscv::CSR_PMPCFG10,
                riscv::CSR_PMPCFG11,
                riscv::CSR_PMPCFG12,
                riscv::CSR_PMPCFG13,
                riscv::CSR_PMPCFG14,
                riscv::CSR_PMPCFG15: begin
          // index is calculated using PMPCFG0 as the offset
          pmpcfg_index = 4'(csr_addr.address[11:0] - riscv::CSR_PMPCFG0);

          // if index is not even and XLEN==64, raise exception
          if (G6LCCfg.IS_XLEN64 && pmpcfg_index[0] == 1'b1) read_access_exception = 1'b1;
          else begin
            // Force even index on XLEN64 in the slice (odd already trapped). Do
            // not re-assign the comb local — that inferred a latch on `index`.
            csr_rdata = pmpcfg_q[(G6LCCfg.IS_XLEN64 ? {pmpcfg_index[3:1], 1'b0}
                                                    : pmpcfg_index)*4+:G6LCCfg.XLEN/8];
          end
        end
        // PMPADDR
        riscv::CSR_PMPADDR0,
                riscv::CSR_PMPADDR1,
                riscv::CSR_PMPADDR2,
                riscv::CSR_PMPADDR3,
                riscv::CSR_PMPADDR4,
                riscv::CSR_PMPADDR5,
                riscv::CSR_PMPADDR6,
                riscv::CSR_PMPADDR7,
                riscv::CSR_PMPADDR8,
                riscv::CSR_PMPADDR9,
                riscv::CSR_PMPADDR10,
                riscv::CSR_PMPADDR11,
                riscv::CSR_PMPADDR12,
                riscv::CSR_PMPADDR13,
                riscv::CSR_PMPADDR14,
                riscv::CSR_PMPADDR15,
                riscv::CSR_PMPADDR16,
                riscv::CSR_PMPADDR17,
                riscv::CSR_PMPADDR18,
                riscv::CSR_PMPADDR19,
                riscv::CSR_PMPADDR20,
                riscv::CSR_PMPADDR21,
                riscv::CSR_PMPADDR22,
                riscv::CSR_PMPADDR23,
                riscv::CSR_PMPADDR24,
                riscv::CSR_PMPADDR25,
                riscv::CSR_PMPADDR26,
                riscv::CSR_PMPADDR27,
                riscv::CSR_PMPADDR28,
                riscv::CSR_PMPADDR29,
                riscv::CSR_PMPADDR30,
                riscv::CSR_PMPADDR31,
                riscv::CSR_PMPADDR32,
                riscv::CSR_PMPADDR33,
                riscv::CSR_PMPADDR34,
                riscv::CSR_PMPADDR35,
                riscv::CSR_PMPADDR36,
                riscv::CSR_PMPADDR37,
                riscv::CSR_PMPADDR38,
                riscv::CSR_PMPADDR39,
                riscv::CSR_PMPADDR40,
                riscv::CSR_PMPADDR41,
                riscv::CSR_PMPADDR42,
                riscv::CSR_PMPADDR43,
                riscv::CSR_PMPADDR44,
                riscv::CSR_PMPADDR45,
                riscv::CSR_PMPADDR46,
                riscv::CSR_PMPADDR47,
                riscv::CSR_PMPADDR48,
                riscv::CSR_PMPADDR49,
                riscv::CSR_PMPADDR50,
                riscv::CSR_PMPADDR51,
                riscv::CSR_PMPADDR52,
                riscv::CSR_PMPADDR53,
                riscv::CSR_PMPADDR54,
                riscv::CSR_PMPADDR55,
                riscv::CSR_PMPADDR56,
                riscv::CSR_PMPADDR57,
                riscv::CSR_PMPADDR58,
                riscv::CSR_PMPADDR59,
                riscv::CSR_PMPADDR60,
                riscv::CSR_PMPADDR61,
                riscv::CSR_PMPADDR62,
                riscv::CSR_PMPADDR63: begin
          // index is calculated using PMPADDR0 as the offset
          pmpaddr_index = csr_addr.address[11:0] - riscv::CSR_PMPADDR0;
          // Important: we only support granularity 8 bytes (G=1)
          // -> last bit of pmpaddr must be set 0/1 based on the mode:
          // NA4, NAPOT: 1
          // TOR, OFF:   0
          if (pmpcfg_q[pmpaddr_index].addr_mode[1] == 1'b1)
            csr_rdata = G6LCCfg.XLEN'({pmpaddr_q[pmpaddr_index][G6LCCfg.PLEN-3:1], 1'b1});
          else csr_rdata = G6LCCfg.XLEN'({pmpaddr_q[pmpaddr_index][G6LCCfg.PLEN-3:1], 1'b0});
        end
        default: read_access_exception = 1'b1;
      endcase
    end
  end
  // ---------------------------
  // CSR Write and update logic
  // ---------------------------
  // hyp8: module-scope `mask` removed (per-block automatic in csr_wr_*)

  // hyp8: phase-A writer outputs (x_w = hold + CSR write, per bank)
  logic [G6LCCfg.XLEN-1:0] acc_cons_w;
  logic [G6LCCfg.XLEN-1:0] aicfg_w;
  logic [G6LCCfg.XLEN-1:0] aiperm_w;
  logic [G6LCCfg.XLEN-1:0] aiqbase_w;
  logic [G6LCCfg.XLEN-1:0] aiqctl_w;
  logic [G6LCCfg.XLEN-1:0] aiqhead_w;
  logic [G6LCCfg.XLEN-1:0] aiscale_w;
  logic [G6LCCfg.XLEN-1:0] aistatus_w;
  logic [G6LCCfg.XLEN-1:0] aizp_w;
  logic [63:0] cycle_w;
  logic [G6LCCfg.XLEN-1:0] dcache_w;
  riscv::dcsr_t dcsr_w;
  logic [G6LCCfg.XLEN-1:0] dpc_w;
  logic [G6LCCfg.XLEN-1:0] dscratch0_w;
  logic [G6LCCfg.XLEN-1:0] dscratch1_w;
  riscv::fcsr_t fcsr_w;
  logic fiom_w;
  logic hcbcfe_w;
  riscv::cbie_t hcbie_w;
  logic hcbze_w;
  logic [G6LCCfg.XLEN-1:0] hcounteren_w;
  logic [G6LCCfg.XLEN-1:0] hedeleg_w;
  hgatp_t hgatp_w;
  logic [G6LCCfg.XLEN-1:0] hideleg_w;
  riscv::hstatus_rv_t hstatus_w;
  logic hstce_w;
  logic [63:0] htimedelta_w;
  logic [G6LCCfg.XLEN-1:0] htinst_w;
  logic [G6LCCfg.XLEN-1:0] htval_w;
  logic [G6LCCfg.XLEN-1:0] icache_w;
  logic [63:0] instret_w;
  jvt_t jvt_w;
  logic [G6LCCfg.XLEN-1:0] mcause_w;
  logic mcbcfe_w;
  riscv::cbie_t mcbie_w;
  logic mcbze_w;
  logic [G6LCCfg.XLEN-1:0] mcounteren_w;
  logic [MHPMCounterNum+3-1:0] mcountinhibit_w;
  logic [G6LCCfg.XLEN-1:0] medeleg_w;
  logic [G6LCCfg.XLEN-1:0] mepc_w;
  logic [G6LCCfg.XLEN-1:0] mideleg_w;
  logic [G6LCCfg.XLEN-1:0] mie_w;
  logic [G6LCCfg.XLEN-1:0] mip_w;
  logic mpbmte_w;
  logic [G6LCCfg.XLEN-1:0] mscratch_w;
  riscv::mstatus_rv_t mstatus_w;
  logic mstce_w;
  logic [G6LCCfg.XLEN-1:0] mtinst_w;
  logic [G6LCCfg.XLEN-1:0] mtval2_w;
  logic [G6LCCfg.XLEN-1:0] mtval_w;
  logic [G6LCCfg.XLEN-1:0] mtvec_w;
  logic [63:0][G6LCCfg.PLEN-3:0] pmpaddr_w;
  riscv::pmpcfg_t [63:0] pmpcfg_w;
  satp_t satp_w;
  logic [G6LCCfg.XLEN-1:0] scause_w;
  logic scbcfe_w;
  riscv::cbie_t scbie_w;
  logic scbze_w;
  logic [G6LCCfg.XLEN-1:0] scontext_w;
  logic [G6LCCfg.XLEN-1:0] scounteren_w;
  logic [G6LCCfg.XLEN-1:0] sepc_w;
  logic [G6LCCfg.XLEN-1:0] sscratch_w;
  logic [63:0] stimecmp_w;
  logic [G6LCCfg.XLEN-1:0] stval_w;
  logic [G6LCCfg.XLEN-1:0] stvec_w;
  satp_t vsatp_w;
  logic [G6LCCfg.XLEN-1:0] vscause_w;
  logic [G6LCCfg.XLEN-1:0] vsepc_w;
  logic [G6LCCfg.XLEN-1:0] vsscratch_w;
  riscv::mstatus_rv_t vsstatus_w;
  logic [63:0] vstimecmp_w;
  logic [G6LCCfg.XLEN-1:0] vstval_w;
  logic [G6LCCfg.XLEN-1:0] vstvec_w;
  logic uae_w, vuae_w, flush_req_w, dfsc_w;
  logic bk_wr_fp_uae, bk_wr_fp_vuae, bk_wr_fp_flush, bk_wr_fp_dfsc;
  logic bk_wr_dbg_uae, bk_wr_dbg_vuae, bk_wr_dbg_flush, bk_wr_dbg_dfsc;
  logic bk_wr_trig_uae, bk_wr_trig_vuae, bk_wr_trig_flush, bk_wr_trig_dfsc;
  logic bk_wr_vs_uae, bk_wr_vs_vuae, bk_wr_vs_flush, bk_wr_vs_dfsc;
  logic bk_wr_ip_uae, bk_wr_ip_vuae, bk_wr_ip_flush, bk_wr_ip_dfsc;
  logic bk_wr_s_uae, bk_wr_s_vuae, bk_wr_s_flush, bk_wr_s_dfsc;
  logic bk_wr_stc_uae, bk_wr_stc_vuae, bk_wr_stc_flush, bk_wr_stc_dfsc;
  logic bk_wr_mstat_uae, bk_wr_mstat_vuae, bk_wr_mstat_flush, bk_wr_mstat_dfsc;
  logic bk_wr_envcfg_uae, bk_wr_envcfg_vuae, bk_wr_envcfg_flush, bk_wr_envcfg_dfsc;
  logic bk_wr_h_uae, bk_wr_h_vuae, bk_wr_h_flush, bk_wr_h_dfsc;
  logic bk_wr_m_uae, bk_wr_m_vuae, bk_wr_m_flush, bk_wr_m_dfsc;
  logic bk_wr_ctr_uae, bk_wr_ctr_vuae, bk_wr_ctr_flush, bk_wr_ctr_dfsc;
  logic bk_wr_pmp_uae, bk_wr_pmp_vuae, bk_wr_pmp_flush, bk_wr_pmp_dfsc;
  logic bk_wr_acc_uae, bk_wr_acc_vuae, bk_wr_acc_flush, bk_wr_acc_dfsc;
  logic bk_wr_dflt_uae, bk_wr_dflt_vuae, bk_wr_dflt_flush, bk_wr_dflt_dfsc;
  // --------------------------------------------------------------------------
  // hyp8: C1 write phase A -- per-domain writer blocks (csr_wr_*) producing *_w =
  // hold + this cycle's CSR write.  Arms are verbatim from the original monolithic
  // csr_update (rank-0 independent-LHS split); shared sideband bits are bank-local
  // bk_* and OR-merged below (at most one case arm fires per write).  Phase B
  // (csr_update) applies the trap-entry / debug / xRET / interrupt overrides in
  // the original order on top of *_w.  The original block is kept verbatim under
  // translate_off as csr_update_ref with per-signal equality assertions.
  // --------------------------------------------------------------------------

  always_comb begin : csr_wr_fp
      fcsr_w = fcsr_q;
      bk_wr_fp_uae   = 1'b0;
      bk_wr_fp_vuae  = 1'b0;
      bk_wr_fp_flush = 1'b0;
      bk_wr_fp_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_FFLAGS: begin
          if (fp_live) begin
            bk_wr_fp_dfsc = 1'b1;
            fcsr_w.fflags = csr_wdata[4:0];
            // this instruction has side-effects
            bk_wr_fp_flush = 1'b1;
          end else begin
            bk_wr_fp_uae = 1'b1;
          end
        end
        riscv::CSR_FRM: begin
          if (fp_live) begin
            bk_wr_fp_dfsc = 1'b1;
            fcsr_w.frm    = csr_wdata[2:0];
            // this instruction has side-effects
            bk_wr_fp_flush = 1'b1;
          end else begin
            bk_wr_fp_uae = 1'b1;
          end
        end
        riscv::CSR_FCSR: begin
          if (fp_live) begin
            bk_wr_fp_dfsc = 1'b1;
            fcsr_w[7:0] = csr_wdata[7:0];  // ignore writes to reserved space
            // this instruction has side-effects
            bk_wr_fp_flush = 1'b1;
          end else begin
            bk_wr_fp_uae = 1'b1;
          end
        end
        riscv::CSR_FTRAN: begin
          if (fp_live) begin
            bk_wr_fp_dfsc = 1'b1;
            fcsr_w.fprec = csr_wdata[6:0];  // ignore writes to reserved space
            // this instruction has side-effects
            bk_wr_fp_flush = 1'b1;
          end else begin
            bk_wr_fp_uae = 1'b1;
          end
        end
        // debug CSR
          default: ;
        endcase
      end
  end

  always_comb begin : csr_wr_dbg
      if (G6LCCfg.DebugEn) begin
        dcsr_w      = dcsr_q;
        dpc_w       = dpc_q;
        dscratch0_w = dscratch0_q;
        dscratch1_w = dscratch1_q;
      end
      bk_wr_dbg_uae   = 1'b0;
      bk_wr_dbg_vuae  = 1'b0;
      bk_wr_dbg_flush = 1'b0;
      bk_wr_dbg_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_DCSR: begin
          if (G6LCCfg.DebugEn) begin
            dcsr_w           = csr_wdata[31:0];
            // debug is implemented
            dcsr_w.xdebugver = 4'h4;
            // currently not supported
            dcsr_w.nmip      = 1'b0;
            dcsr_w.stopcount = 1'b0;
            dcsr_w.stoptime  = 1'b0;
          end else begin
            bk_wr_dbg_uae = 1'b1;
          end
        end
        riscv::CSR_DPC:
        if (G6LCCfg.DebugEn) dpc_w = csr_wdata;
        else bk_wr_dbg_uae = 1'b1;
        riscv::CSR_DSCRATCH0:
        if (G6LCCfg.DebugEn) dscratch0_w = csr_wdata;
        else bk_wr_dbg_uae = 1'b1;
        riscv::CSR_DSCRATCH1:
        if (G6LCCfg.DebugEn) dscratch1_w = csr_wdata;
        else bk_wr_dbg_uae = 1'b1;
          default: ;
        endcase
      end
  end

  always_comb begin : csr_wr_trig
      tdata1_to_tm = '0;
      tdata2_to_tm = '0;
      tdata3_to_tm = '0;
      tselect_to_tm = '0;
      tselect_we = 1'b0;
      tdata1_we  = 1'b0;
      tdata2_we  = 1'b0;
      tdata3_we  = 1'b0;
      bk_wr_trig_uae   = 1'b0;
      bk_wr_trig_vuae  = 1'b0;
      bk_wr_trig_flush = 1'b0;
      bk_wr_trig_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_TSELECT: begin
          if (G6LCCfg.SDTRIG) begin
            tselect_to_tm = csr_wdata;
            tselect_we    = csr_we;
          end else begin
            bk_wr_trig_uae = 1'b1;
          end
        end
        riscv::CSR_TDATA1: begin
          if (G6LCCfg.SDTRIG) begin
            tdata1_to_tm = csr_wdata;
            tdata1_we    = csr_we;
            bk_wr_trig_flush = flush_from_tm;
          end else begin
            bk_wr_trig_uae = 1'b1;
          end
        end
        riscv::CSR_TDATA2: begin
          if (G6LCCfg.SDTRIG) begin
            tdata2_to_tm = csr_wdata;
            tdata2_we    = csr_we;
          end else begin
            bk_wr_trig_uae = 1'b1;
          end
        end
        riscv::CSR_TDATA3: begin
          if (G6LCCfg.SDTRIG) begin
            tdata3_to_tm = csr_wdata;
            tdata3_we    = csr_we;
          end else begin
            bk_wr_trig_uae = 1'b1;
          end
        end
          default: ;
        endcase
      end
  end

  always_comb begin : csr_wr_vs
    automatic logic [G6LCCfg.XLEN-1:0] mask;
      if (G6LCCfg.RVH) begin
        vsstatus_w  = vsstatus_q;
        vstvec_w    = vstvec_q;
        vsscratch_w = vsscratch_q;
        vsepc_w     = vsepc_q;
        vscause_w   = vscause_q;
        vstval_w    = vstval_q;
        vsatp_w     = vsatp_q;
      end
      bk_wr_vs_uae   = 1'b0;
      bk_wr_vs_vuae  = 1'b0;
      bk_wr_vs_flush = 1'b0;
      bk_wr_vs_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_VSSTATUS: begin
          if (G6LCCfg.RVH) begin
            mask = g6lc_core_pkg::SMODE_STATUS_WRITE_MASK[G6LCCfg.XLEN-1:0];
            vsstatus_w = (vsstatus_q & ~{{64-G6LCCfg.XLEN{1'b0}}, mask}) | {{64-G6LCCfg.XLEN{1'b0}}, (csr_wdata & mask)};
            // XS read-only summary (AI-E3); forced Off here, re-driven from ais below.
            vsstatus_w.xs = riscv::Off;
            if (!G6LCCfg.FpPresent) begin
              vsstatus_w.fs = riscv::Off;
            end
            // this instruction has side-effects
            bk_wr_vs_flush = 1'b1;
          end else begin
            bk_wr_vs_uae = 1'b1;
          end
        end
        riscv::CSR_VSTVEC: begin
          if (G6LCCfg.RVH) begin
            vstvec_w = {csr_wdata[G6LCCfg.XLEN-1:2], 1'b0, csr_wdata[0]};
          end else begin
            bk_wr_vs_uae = 1'b1;
          end
        end
        riscv::CSR_VSSCRATCH:
        if (G6LCCfg.RVH) vsscratch_w = csr_wdata;
        else bk_wr_vs_uae = 1'b1;
        riscv::CSR_VSEPC:
        if (G6LCCfg.RVH) vsepc_w = {csr_wdata[G6LCCfg.XLEN-1:1], 1'b0};
        else bk_wr_vs_uae = 1'b1;
        riscv::CSR_VSCAUSE:
        if (G6LCCfg.RVH) vscause_w = csr_wdata;
        else bk_wr_vs_uae = 1'b1;
        riscv::CSR_VSTVAL:
        if (G6LCCfg.RVH) vstval_w = csr_wdata;
        else bk_wr_vs_uae = 1'b1;
        // virtual supervisor address translation and protection
        riscv::CSR_VSATP: begin
          if (G6LCCfg.RVH) begin
            if (priv_lvl_o == riscv::PRIV_LVL_S && hstatus_q.vtvm && v_q) begin
              bk_wr_vs_vuae = 1'b1;
            end else if (satp_mode_ok) begin
              vsatp_w = satp_next;
            end
            // changing the mode can have side-effects on address translation (e.g.: other instructions), re-fetch
            // the next instruction by executing a flush
            bk_wr_vs_flush = 1'b1;
          end else begin
            bk_wr_vs_uae = 1'b1;
          end
        end
        // sstatus is a subset of mstatus - mask it accordingly
          default: ;
        endcase
      end
  end

  always_comb begin : csr_wr_ip
    automatic logic [G6LCCfg.XLEN-1:0] mask;
      mip_w = mip_q;
      mie_w = mie_q;
      bk_wr_ip_uae   = 1'b0;
      bk_wr_ip_vuae  = 1'b0;
      bk_wr_ip_flush = 1'b0;
      bk_wr_ip_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_VSIE:
        if (G6LCCfg.RVH) mie_w = (mie_q & ~hideleg_q) | ((csr_wdata << 1) & hideleg_q);
        else bk_wr_ip_uae = 1'b1;
        riscv::CSR_VSIP: begin
          if (G6LCCfg.RVH) begin
            // only the virtual supervisor software interrupt is write-able, iff delegated
            mask  = G6LCCfg.XLEN'(riscv::MIP_VSSIP) & hideleg_q;
            mip_w = (mip_q & ~mask) | ((csr_wdata << 1) & mask);
          end else begin
            bk_wr_ip_uae = 1'b1;
          end
        end
        riscv::CSR_SIE: begin
          if (G6LCCfg.RVS) begin
            mask  = (G6LCCfg.RVH) ? mideleg_q & ~HS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0] : mideleg_q;
            // the mideleg makes sure only delegate-able register (and therefore also only implemented registers) are written
            mie_w = (mie_q & ~mask) | (csr_wdata & mask);
          end else begin
            bk_wr_ip_uae = 1'b1;
          end
        end

        riscv::CSR_SIP: begin
          if (G6LCCfg.RVS) begin
            // only the supervisor software interrupt is write-able, iff delegated
            mask  = G6LCCfg.XLEN'(riscv::MIP_SSIP) & mideleg_q;
            mip_w = (mip_q & ~mask) | (csr_wdata & mask);
          end else begin
            bk_wr_ip_uae = 1'b1;
          end
        end

        riscv::CSR_HIE: begin
          if (G6LCCfg.RVH) begin
            mask  = HS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0];
            mie_w = (mie_q & ~mask) | (csr_wdata & mask);
          end else begin
            bk_wr_ip_uae = 1'b1;
          end
        end
        riscv::CSR_HIP: begin
          if (G6LCCfg.RVH) begin
            mask  = G6LCCfg.XLEN'(riscv::MIP_VSSIP);
            mip_w = (mip_q & ~mask) | (csr_wdata & mask);
          end else begin
            bk_wr_ip_uae = 1'b1;
          end
        end
        riscv::CSR_HVIP: begin
          if (G6LCCfg.RVH) begin
            // hvip_mask is the VS inject bits. VSTIP drops out while Sstc×H
            // hardwires it from the guest timer. The mask is not built inside
            // this arm: a second procedural write of `mask` was one 26 FO4 node.
            mip_w = (mip_q & ~hvip_mask) | (csr_wdata & hvip_mask);
          end else begin
            bk_wr_ip_uae = 1'b1;
          end
        end
        riscv::CSR_MIE: begin
          if (G6LCCfg.RVH) begin
            mask = HS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0]
                    | G6LCCfg.XLEN'(riscv::MIP_SSIP)
                    | G6LCCfg.XLEN'(riscv::MIP_STIP)
                    | G6LCCfg.XLEN'(riscv::MIP_SEIP)
                    | G6LCCfg.XLEN'(riscv::MIP_MSIP)
                    | G6LCCfg.XLEN'(riscv::MIP_MTIP)
                    | G6LCCfg.XLEN'(riscv::MIP_MEIP);
          end else begin
            if (G6LCCfg.RVS) begin
              mask = G6LCCfg.XLEN'(riscv::MIP_SSIP)
                      | G6LCCfg.XLEN'(riscv::MIP_STIP)
                      | G6LCCfg.XLEN'(riscv::MIP_SEIP)
                      | G6LCCfg.XLEN'(riscv::MIP_MSIP)
                      | G6LCCfg.XLEN'(riscv::MIP_MTIP)
                      | G6LCCfg.XLEN'(riscv::MIP_MEIP);
            end else begin
              if (G6LCCfg.SoftwareInterruptEn) begin
                mask = G6LCCfg.XLEN'(riscv::MIP_MSIP)  // same shift as MSIE
                | G6LCCfg.XLEN'(riscv::MIP_MTIP)  // same shift as MTIE
                | G6LCCfg.XLEN'(riscv::MIP_MEIP);  // same shift as MEIE
              end else begin
                mask = G6LCCfg.XLEN'(riscv::MIP_MTIP)  // same shift as MTIE
                | G6LCCfg.XLEN'(riscv::MIP_MEIP);  // same shift as MEIE
              end
            end
          end
          // Sscofpmf: LCOFIE is always M-mode-writable when the extension is on.
          if (G6LCCfg.SscofpmfEn) mask = mask | G6LCCfg.XLEN'(riscv::MIP_LCOFIP);
          mie_w = (mie_q & ~mask) | (csr_wdata & mask); // we only support supervisor and M-mode interrupts
        end

        riscv::CSR_MIP: begin
          // hyp8 RVH is 0 and RVS is 1. The other arms do not fold.
          mask = G6LCCfg.XLEN'(riscv::MIP_SSIP)
                  | G6LCCfg.XLEN'(riscv::MIP_STIP)
                  | G6LCCfg.XLEN'(riscv::MIP_SEIP);
          mip_w = (mip_q & ~mask) | (csr_wdata & mask);
        end
          default: ;
        endcase
      end
  end

  always_comb begin : csr_wr_s
      if (G6LCCfg.RVZCMT) jvt_w = jvt_q;
      // hyp8: scontext_w keeps the original no-hold (write-only window) behavior
      if (G6LCCfg.RVS) begin
        sepc_w       = sepc_q;
        scause_w     = scause_q;
        stvec_w      = stvec_q;
        scounteren_w = scounteren_q;
        sscratch_w   = sscratch_q;
        stval_w      = stval_q;
        satp_w       = satp_q;
      end
      if (G6LCCfg.RVS) satp = satp_q;
      bk_wr_s_uae   = 1'b0;
      bk_wr_s_vuae  = 1'b0;
      bk_wr_s_flush = 1'b0;
      bk_wr_s_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_JVT: begin
          if (G6LCCfg.RVZCMT) begin
            jvt_w.base = csr_wdata[G6LCCfg.XLEN-1:6];
            jvt_w.mode = 6'b000000;
          end else begin
            bk_wr_s_uae = 1'b1;
          end
        end
        // Trigger module CSRs
        riscv::CSR_SCONTEXT: begin
          if (G6LCCfg.SDTRIG) begin
            scontext_w = {{G6LCCfg.XLEN - 32{1'b0}}, csr_wdata[31:0]};
          end else begin
            bk_wr_s_uae = 1'b1;
          end
        end
        // virtual supervisor registers
        riscv::CSR_STVEC:
        if (G6LCCfg.RVS) stvec_w = {csr_wdata[G6LCCfg.XLEN-1:2], 1'b0, csr_wdata[0]};
        else bk_wr_s_uae = 1'b1;
        riscv::CSR_SCOUNTEREN:
        if (G6LCCfg.RVS) scounteren_w = {{G6LCCfg.XLEN - 32{1'b0}}, csr_wdata[31:0]};
        else bk_wr_s_uae = 1'b1;
        riscv::CSR_SSCRATCH:
        if (G6LCCfg.RVS) sscratch_w = csr_wdata;
        else bk_wr_s_uae = 1'b1;
        riscv::CSR_SEPC:
        if (G6LCCfg.RVS) sepc_w = {csr_wdata[G6LCCfg.XLEN-1:1], 1'b0};
        else bk_wr_s_uae = 1'b1;
        riscv::CSR_SCAUSE:
        if (G6LCCfg.RVS) scause_w = csr_wdata;
        else bk_wr_s_uae = 1'b1;
        riscv::CSR_STVAL:
        if (G6LCCfg.RVS && G6LCCfg.TvalEn) stval_w = csr_wdata;
        else bk_wr_s_uae = 1'b1;
        // Sstc: writing stimecmp re-arms the supervisor timer. Writing it also
        // implicitly clears the pending STIP, because STIP is a pure function of
        // (time >= stimecmp) once STCE is set — no explicit clear is needed.
        // V=1: stimecmp is an alias of vstimecmp; STCE fail → virtual-instruction.
        riscv::CSR_SATP: begin
          if (G6LCCfg.RVS) begin
            // intercept SATP writes if in S-Mode and TVM is enabled
            if (priv_lvl_o == riscv::PRIV_LVL_S && mstatus_q.tvm) bk_wr_s_uae = 1'b1;
            else if (satp_mode_ok) satp_w = satp_next;
            // changing the mode can have side-effects on address translation (e.g.: other instructions), re-fetch
            // the next instruction by executing a flush
            bk_wr_s_flush = 1'b1;
          end else begin
            bk_wr_s_uae = 1'b1;
          end
        end
          default: ;
        endcase
      end
  end

  always_comb begin : csr_wr_stc
      if (G6LCCfg.SstcEn) begin
        stimecmp_w = stimecmp_q;
      end else begin
        stimecmp_w = '0;
      end
      if (G6LCCfg.SstcEn && G6LCCfg.RVH) begin
        vstimecmp_w = vstimecmp_q;
      end else begin
        vstimecmp_w = '0;
      end
      bk_wr_stc_uae   = 1'b0;
      bk_wr_stc_vuae  = 1'b0;
      bk_wr_stc_flush = 1'b0;
      bk_wr_stc_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_STIMECMP: begin
          if (G6LCCfg.SstcEn && G6LCCfg.RVS) begin
            // hyp8 RVH is 0, so this is never the vstimecmp alias.
            // Machine mode is 2'b11. The cast keeps the compare at 2 bits.
            if (2'(priv_lvl_o) != 2'b11 && !mstce_q) begin
              bk_wr_stc_uae = 1'b1;
            end else begin
              stimecmp_w[G6LCCfg.XLEN-1:0] = csr_wdata;
            end
          end else begin
            bk_wr_stc_uae = 1'b1;
          end
        end
        // XLEN64 and RVH off: these writes are illegal. The old privilege
        // nest stayed in the cone because G6LCCfg.RVH does not fold.
        riscv::CSR_STIMECMPH,
        riscv::CSR_VSTIMECMP,
        riscv::CSR_VSTIMECMPH: bk_wr_stc_uae = 1'b1;
        // supervisor address translation and protection
          default: ;
        endcase
      end
  end

  always_comb begin : csr_wr_mstat
      mstatus_w = mstatus_q;
      bk_wr_mstat_uae   = 1'b0;
      bk_wr_mstat_vuae  = 1'b0;
      bk_wr_mstat_flush = 1'b0;
      bk_wr_mstat_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_SSTATUS: begin
          if (G6LCCfg.RVS) begin
            // hyp8 XLEN is 64, so the write mask is the whole 64-bit
            // constant. A part-select bound of G6LCCfg.XLEN-1 does not fold.
            mstatus_w = (mstatus_q & ~g6lc_core_pkg::SMODE_STATUS_WRITE_MASK)
                      | (csr_wdata & g6lc_core_pkg::SMODE_STATUS_WRITE_MASK);
            // hardwire to zero if floating point extension is not present
            if (!G6LCCfg.FpPresent) begin
              mstatus_w.fs = riscv::Off;
            end
            // hardwire to zero if vector extension is not present
            if (!G6LCCfg.RVV) begin
              mstatus_w.vs = riscv::Off;
            end
            // If h-extension is not enabled, priv level HS is reserved
            if (!G6LCCfg.RVH) begin
              if (mstatus_w.mpp == riscv::PRIV_LVL_HS) begin
                mstatus_w.mpp = mstatus_q.mpp;
              end
            end
            // this instruction has side-effects
            bk_wr_mstat_flush = 1'b1;
          end else begin
            bk_wr_mstat_uae = 1'b1;
          end
        end
        // even machine mode interrupts can be visible and set-able to supervisor
        // if the corresponding bit in mideleg is set
        riscv::CSR_MSTATUS: begin
          mstatus_w    = {{64 - G6LCCfg.XLEN{1'b0}}, csr_wdata};
          // XS is read-only (AI-E3 / isa-encoding.md §5). Forced Off unless the
          // AI plane is present; when present it is overwritten below from ais.
          mstatus_w.xs = riscv::Off;
          if (!G6LCCfg.FpPresent) begin
            mstatus_w.fs = riscv::Off;
          end
          if (!G6LCCfg.RVV) begin
            mstatus_w.vs = riscv::Off;
          end
          if (!G6LCCfg.RVS) begin
            mstatus_w.sie  = 1'b0;
            mstatus_w.spie = 1'b0;
            mstatus_w.spp  = 1'b0;
            mstatus_w.sum  = 1'b0;
            mstatus_w.mxr  = 1'b0;
            mstatus_w.tvm  = 1'b0;
            mstatus_w.tsr  = 1'b0;
          end
          if (!G6LCCfg.RVU) begin
            mstatus_w.tw   = 1'b0;
            mstatus_w.mprv = 1'b0;
          end
          if ((!G6LCCfg.RVH & mstatus_w.mpp == riscv::PRIV_LVL_HS) |
              (!G6LCCfg.RVS & mstatus_w.mpp == riscv::PRIV_LVL_S) |
              (!G6LCCfg.RVU & mstatus_w.mpp == riscv::PRIV_LVL_U)) begin
            mstatus_w.mpp = mstatus_q.mpp;
          end
          mstatus_w.wpri3 = 9'b0;
          mstatus_w.wpri1 = 1'b0;
          mstatus_w.wpri2 = 1'b0;
          mstatus_w.wpri0 = 1'b0;
          // Mirror MBE
          mstatus_w.sbe   = mstatus_w.mbe;
          mstatus_w.ube   = mstatus_w.mbe;
          // this register has side-effects on other registers, flush the pipeline
          bk_wr_mstat_flush         = 1'b1;
        end
        riscv::CSR_MSTATUSH: begin
          if (G6LCCfg.IS_XLEN32) begin
            mstatus_w.mbe = ((csr_wdata & riscv::MSTATUSH_MBE) != 0);
            // Mirror MBE
            mstatus_w.sbe = mstatus_w.mbe;
            mstatus_w.ube = mstatus_w.mbe;
            // this register has side-effects on other registers, flush the pipeline
            bk_wr_mstat_flush       = 1'b1;
          end else begin
            bk_wr_mstat_uae = 1'b1;
          end
        end
        // MISA is WARL (Write Any Value, Reads Legal Value)
          default: ;
        endcase
      end
  end

  always_comb begin : csr_wr_envcfg
      fiom_w   = fiom_q;
      mcbie_w  = mcbie_q;
      scbie_w  = scbie_q;
      hcbie_w  = hcbie_q;
      mcbcfe_w = mcbcfe_q;
      scbcfe_w = scbcfe_q;
      hcbcfe_w = hcbcfe_q;
      mcbze_w  = mcbze_q;
      scbze_w  = scbze_q;
      hcbze_w  = hcbze_q;
      mpbmte_w = mpbmte_q;
      if (G6LCCfg.SstcEn) begin
        mstce_w = mstce_q;
      end else begin
        mstce_w = 1'b0;
      end
      if (G6LCCfg.SstcEn && G6LCCfg.RVH) begin
        hstce_w = hstce_q;
      end else begin
        hstce_w = 1'b0;
      end
      bk_wr_envcfg_uae   = 1'b0;
      bk_wr_envcfg_vuae  = 1'b0;
      bk_wr_envcfg_flush = 1'b0;
      bk_wr_envcfg_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_SENVCFG: begin
          if (G6LCCfg.RVS) begin
            fiom_w = csr_wdata[0];
            if (G6LCCfg.RVZiCbom) begin
              unique case (csr_wdata[5:4])
                2'b00:   scbie_w = riscv::CBIE_ILLEGAL;
                2'b01:   scbie_w = riscv::CBIE_FLUSH;
                2'b11:   scbie_w = riscv::CBIE_INVAL;
                default: scbie_w = riscv::CBIE_RSVD;
              endcase
              scbcfe_w = csr_wdata[6];
            end
            if (G6LCCfg.RVZiCboz) scbze_w = csr_wdata[7];
          end else begin
            bk_wr_envcfg_uae = 1'b1;
          end
        end
        //hypervisor mode registers
        riscv::CSR_HENVCFG: begin
          if (G6LCCfg.RVH) begin
            fiom_w = csr_wdata[0];
            if (G6LCCfg.RVZiCbom) begin
              unique case (csr_wdata[5:4])
                2'b00:   hcbie_w = riscv::CBIE_ILLEGAL;
                2'b01:   hcbie_w = riscv::CBIE_FLUSH;
                2'b11:   hcbie_w = riscv::CBIE_INVAL;
                default: hcbie_w = riscv::CBIE_RSVD;
              endcase
              hcbcfe_w = csr_wdata[6];
            end
            if (G6LCCfg.RVZiCboz) hcbze_w = csr_wdata[7];
            // henvcfg.STCE — enable VS Sstc (requires menvcfg.STCE as well)
            if (G6LCCfg.SstcEn && G6LCCfg.IS_XLEN64) hstce_w = csr_wdata[G6LCCfg.XLEN-1];
          end else begin
            bk_wr_envcfg_uae = 1'b1;
          end
        end
        riscv::CSR_HENVCFGH: begin
          if (G6LCCfg.RVH && G6LCCfg.IS_XLEN32) begin
            if (G6LCCfg.SstcEn) hstce_w = csr_wdata[31];
          end else bk_wr_envcfg_uae = 1'b1;
        end
        // U9.1: htimedelta write (HS/M). VS access is blocked by CSR privilege decode.
        riscv::CSR_MENVCFG: begin
          if (G6LCCfg.RVU) begin
            fiom_w = csr_wdata[0];
          end
          if (G6LCCfg.RVZiCbom) begin
            unique case (csr_wdata[5:4])
              2'b00:   mcbie_w = riscv::CBIE_ILLEGAL;
              2'b01:   mcbie_w = riscv::CBIE_FLUSH;
              2'b11:   mcbie_w = riscv::CBIE_INVAL;
              default: mcbie_w = riscv::CBIE_RSVD;
            endcase
            mcbcfe_w = csr_wdata[6];
          end
          if (G6LCCfg.RVZiCboz) begin
            mcbze_w = csr_wdata[7];
          end
          if (G6LCCfg.SvpbmtEn && G6LCCfg.IS_XLEN64) begin
            mpbmte_w = csr_wdata[62];
          end
          // menvcfg.STCE (bit 63) is only present on RV64; RV32 uses menvcfgh.
          if (G6LCCfg.SstcEn && G6LCCfg.IS_XLEN64) begin
            mstce_w = csr_wdata[G6LCCfg.XLEN-1];
          end
        end
        riscv::CSR_MENVCFGH: begin
          if (!G6LCCfg.RVU || !G6LCCfg.IS_XLEN32) bk_wr_envcfg_uae = 1'b1;
          // menvcfgh.STCE is menvcfg bit 63 on RV32.
          else if (G6LCCfg.SstcEn) mstce_w = csr_wdata[31];
        end
          default: ;
        endcase
      end
  end

  always_comb begin : csr_wr_h
    automatic logic [G6LCCfg.XLEN-1:0] mask;
      if (G6LCCfg.RVH) begin
        hstatus_w    = hstatus_q;
        hedeleg_w    = hedeleg_q;
        hideleg_w    = hideleg_q;
        hcounteren_w = hcounteren_q;
        htinst_w     = htinst_q;
        htval_w      = htval_q;
        hgatp_w      = hgatp_q;
      end
      if (G6LCCfg.RVH) htimedelta_w = htimedelta_q;
      else htimedelta_w = '0;
      if (G6LCCfg.RVH) hgatp = hgatp_q;
      bk_wr_h_uae   = 1'b0;
      bk_wr_h_vuae  = 1'b0;
      bk_wr_h_flush = 1'b0;
      bk_wr_h_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_HSTATUS: begin
          if (G6LCCfg.RVH) begin
            mask = g6lc_core_pkg::HSTATUS_WRITE_MASK[G6LCCfg.XLEN-1:0];
            hstatus_w = (hstatus_q & ~{{64-G6LCCfg.XLEN{1'b0}}, mask}) | {{64-G6LCCfg.XLEN{1'b0}}, (csr_wdata & mask)};
            // this instruction has side-effects
            bk_wr_h_flush = 1'b1;
          end else begin
            bk_wr_h_uae = 1'b1;
          end
        end
        riscv::CSR_HEDELEG: begin
          if (G6LCCfg.RVH) begin
            mask = (1 << riscv::INSTR_ADDR_MISALIGNED) |
               (1 << riscv::INSTR_ACCESS_FAULT) |
               (1 << riscv::ILLEGAL_INSTR) |
               (1 << riscv::BREAKPOINT) |
               (1 << riscv::LD_ADDR_MISALIGNED) |
               (1 << riscv::LD_ACCESS_FAULT) |
               (1 << riscv::ST_ADDR_MISALIGNED) |
               (1 << riscv::ST_ACCESS_FAULT) |
               (1 << riscv::ENV_CALL_UMODE) |
               (1 << riscv::INSTR_PAGE_FAULT) |
               (1 << riscv::LOAD_PAGE_FAULT) |
               (1 << riscv::STORE_PAGE_FAULT);
            hedeleg_w = (hedeleg_q & ~mask) | (csr_wdata & mask);
          end else begin
            bk_wr_h_uae = 1'b1;
          end
        end
        riscv::CSR_HIDELEG: begin
          if (G6LCCfg.RVH) begin
            hideleg_w = (hideleg_q & ~VS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0]) | (csr_wdata & VS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0]);
          end else begin
            bk_wr_h_uae = 1'b1;
          end
        end
        riscv::CSR_HCOUNTEREN: begin
          if (G6LCCfg.RVH) begin
            hcounteren_w = {{G6LCCfg.XLEN - 32{1'b0}}, csr_wdata[31:0]};
          end else begin
            bk_wr_h_uae = 1'b1;
          end
        end
        // hyp8 RVH is 0. The hypervisor write arms do not fold and the
        // HGATP next-value was on the register-file cone. These CSRs
        // raise an illegal write.
        riscv::CSR_HTVAL, riscv::CSR_HTINST, riscv::CSR_HGEIE, riscv::CSR_HGATP,
        riscv::CSR_HTIMEDELTA, riscv::CSR_HTIMEDELTAH:
          bk_wr_h_uae = 1'b1;
          default: ;
        endcase
      end
  end

  always_comb begin : csr_wr_m
    automatic logic [G6LCCfg.XLEN-1:0] mask;
      mcountinhibit_w = mcountinhibit_q;
      if (mtvec_rst_load_q) begin
        mtvec_w = {{G6LCCfg.XLEN - G6LCCfg.VLEN{1'b0}}, boot_addr_i} + 'h40;
      end else begin
        mtvec_w = mtvec_q;
      end
      if (G6LCCfg.RVS) begin
        medeleg_w = medeleg_q;
        mideleg_w = mideleg_q;
      end
      mepc_w       = mepc_q;
      mcause_w     = mcause_q;
      mcounteren_w = mcounteren_q;
      mscratch_w   = mscratch_q;
      if (G6LCCfg.TvalEn) mtval_w = mtval_q;
      if (G6LCCfg.RVH) begin
        mtinst_w  = mtinst_q;
        mtval2_w  = mtval2_q;
      end
      bk_wr_m_uae   = 1'b0;
      bk_wr_m_vuae  = 1'b0;
      bk_wr_m_flush = 1'b0;
      bk_wr_m_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_MISA: ;
        // machine exception delegation register
        // 0 - 15 exceptions supported
        riscv::CSR_MEDELEG: begin
          if (G6LCCfg.RVS) begin
            mask = (1 << riscv::INSTR_ADDR_MISALIGNED) |
                             (1 << riscv::INSTR_ACCESS_FAULT) |
                             (1 << riscv::ILLEGAL_INSTR) |
                             (1 << riscv::BREAKPOINT) |
                             (1 << riscv::LD_ADDR_MISALIGNED) |
                             (1 << riscv::LD_ACCESS_FAULT) |
                             (1 << riscv::ST_ADDR_MISALIGNED) |
                             (1 << riscv::ST_ACCESS_FAULT) |
                             (1 << riscv::ENV_CALL_UMODE) |
                             ((G6LCCfg.RVH ? 1 : 0) << riscv::ENV_CALL_VSMODE) |
                             (1 << riscv::INSTR_PAGE_FAULT) |
                             (1 << riscv::LOAD_PAGE_FAULT) |
                             (1 << riscv::STORE_PAGE_FAULT) |
                             ((G6LCCfg.RVH ? 1 : 0)  << riscv::INSTR_GUEST_PAGE_FAULT) |
                             ((G6LCCfg.RVH ? 1 : 0)  << riscv::LOAD_GUEST_PAGE_FAULT) |
                             ((G6LCCfg.RVH ? 1 : 0)  << riscv::VIRTUAL_INSTRUCTION) |
                             ((G6LCCfg.RVH ? 1 : 0)  << riscv::STORE_GUEST_PAGE_FAULT);
            medeleg_w = (medeleg_q & ~mask) | (csr_wdata & mask);
          end else begin
            bk_wr_m_uae = 1'b1;
          end
        end
        // machine interrupt delegation register
        // we do not support user interrupt delegation
        riscv::CSR_MIDELEG: begin
          if (G6LCCfg.RVS) begin
            mask = G6LCCfg.XLEN'(riscv::MIP_SSIP)
                    | G6LCCfg.XLEN'(riscv::MIP_STIP)
                    | G6LCCfg.XLEN'(riscv::MIP_SEIP);
            // Sscofpmf: LCOFI is delegable to S-mode.
            if (G6LCCfg.SscofpmfEn) mask = mask | G6LCCfg.XLEN'(riscv::MIP_LCOFIP);
            if (G6LCCfg.RVH) begin
              mideleg_w = (mideleg_q & ~mask) | (csr_wdata & mask) | HS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0];
            end else begin
              mideleg_w = (mideleg_q & ~mask) | (csr_wdata & mask);
            end
          end else begin
            bk_wr_m_uae = 1'b1;
          end
        end
        // mask the register so that unsupported interrupts can never be set
        riscv::CSR_MTVEC: begin
          logic DirVecOnly;
          DirVecOnly = G6LCCfg.DirectVecOnly ? 1'b0 : csr_wdata[0];
          mtvec_w = {csr_wdata[G6LCCfg.XLEN-1:2], 1'b0, DirVecOnly};
          // we are in vector mode, this implementation requires the additional
          // alignment constraint of 64 * 4 bytes
          if (DirVecOnly) mtvec_w = {csr_wdata[G6LCCfg.XLEN-1:8], 7'b0, DirVecOnly};
        end
        riscv::CSR_MCOUNTEREN: begin
          if (G6LCCfg.RVU) mcounteren_w = {{G6LCCfg.XLEN - 32{1'b0}}, csr_wdata[31:0]};
          else bk_wr_m_uae = 1'b1;
        end

        riscv::CSR_MSCRATCH: mscratch_w = csr_wdata;
        riscv::CSR_MEPC: mepc_w = {csr_wdata[G6LCCfg.XLEN-1:1], 1'b0};
        riscv::CSR_MCAUSE: mcause_w = csr_wdata;
        riscv::CSR_MTVAL: begin
          if (G6LCCfg.TvalEn) mtval_w = csr_wdata;
        end
        riscv::CSR_MTINST:
        if (G6LCCfg.RVH) mtinst_w = {{G6LCCfg.XLEN - 32{1'b0}}, csr_wdata[31:0]};
        else bk_wr_m_uae = 1'b1;
        riscv::CSR_MTVAL2:
        if (G6LCCfg.RVH) mtval2_w = csr_wdata;
        else bk_wr_m_uae = 1'b1;
        riscv::CSR_MCOUNTINHIBIT:
        if (G6LCCfg.PerfCounterEn)
          mcountinhibit_w = {csr_wdata[MHPMCounterNum+2:2], 1'b0, csr_wdata[0]};
        else mcountinhibit_w = '0;
        // performance counters
          default: ;
        endcase
      end
  end

