  always_comb begin : csr_wr_pmp
      pmpcfg_w  = pmpcfg_q;
      pmpaddr_w = pmpaddr_q;
      bk_wr_pmp_uae   = 1'b0;
      bk_wr_pmp_vuae  = 1'b0;
      bk_wr_pmp_flush = 1'b0;
      bk_wr_pmp_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_PMPCFG0,
                riscv::CSR_PMPCFG1,
                riscv::CSR_PMPCFG2,
                riscv::CSR_PMPCFG3,
                riscv::CSR_PMPCFG4,
                riscv::CSR_PMPCFG5,
                riscv::CSR_PMPCFG6,
                riscv::CSR_PMPCFG7,
                riscv::CSR_PMPCFG8,
                riscv::CSR_PMPCFG9,
                riscv::CSR_PMPCFG10,
                riscv::CSR_PMPCFG11,
                riscv::CSR_PMPCFG12,
                riscv::CSR_PMPCFG13,
                riscv::CSR_PMPCFG14,
                riscv::CSR_PMPCFG15: begin
          // index is calculated using PMPCFG0 as the offset
          automatic logic [11:0] index = csr_addr.address[11:0] - riscv::CSR_PMPCFG0;

          // if index is not even and XLEN==64, raise exception
          if (G6LCCfg.IS_XLEN64 && index[0] == 1'b1) bk_wr_pmp_uae = 1'b1;
          else begin
            for (int i = 0; i < G6LCCfg.XLEN / 8; i++) begin
              if (!pmpcfg_q[index*4+i].locked) pmpcfg_w[index*4+i] = csr_wdata[i*8+:8];
            end
          end
        end
        riscv::CSR_PMPADDR0,
                riscv::CSR_PMPADDR1,
                riscv::CSR_PMPADDR2,
                riscv::CSR_PMPADDR3,
                riscv::CSR_PMPADDR4,
                riscv::CSR_PMPADDR5,
                riscv::CSR_PMPADDR6,
                riscv::CSR_PMPADDR7,
                riscv::CSR_PMPADDR8,
                riscv::CSR_PMPADDR9,
                riscv::CSR_PMPADDR10,
                riscv::CSR_PMPADDR11,
                riscv::CSR_PMPADDR12,
                riscv::CSR_PMPADDR13,
                riscv::CSR_PMPADDR14,
                riscv::CSR_PMPADDR15,
                riscv::CSR_PMPADDR16,
                riscv::CSR_PMPADDR17,
                riscv::CSR_PMPADDR18,
                riscv::CSR_PMPADDR19,
                riscv::CSR_PMPADDR20,
                riscv::CSR_PMPADDR21,
                riscv::CSR_PMPADDR22,
                riscv::CSR_PMPADDR23,
                riscv::CSR_PMPADDR24,
                riscv::CSR_PMPADDR25,
                riscv::CSR_PMPADDR26,
                riscv::CSR_PMPADDR27,
                riscv::CSR_PMPADDR28,
                riscv::CSR_PMPADDR29,
                riscv::CSR_PMPADDR30,
                riscv::CSR_PMPADDR31,
                riscv::CSR_PMPADDR32,
                riscv::CSR_PMPADDR33,
                riscv::CSR_PMPADDR34,
                riscv::CSR_PMPADDR35,
                riscv::CSR_PMPADDR36,
                riscv::CSR_PMPADDR37,
                riscv::CSR_PMPADDR38,
                riscv::CSR_PMPADDR39,
                riscv::CSR_PMPADDR40,
                riscv::CSR_PMPADDR41,
                riscv::CSR_PMPADDR42,
                riscv::CSR_PMPADDR43,
                riscv::CSR_PMPADDR44,
                riscv::CSR_PMPADDR45,
                riscv::CSR_PMPADDR46,
                riscv::CSR_PMPADDR47,
                riscv::CSR_PMPADDR48,
                riscv::CSR_PMPADDR49,
                riscv::CSR_PMPADDR50,
                riscv::CSR_PMPADDR51,
                riscv::CSR_PMPADDR52,
                riscv::CSR_PMPADDR53,
                riscv::CSR_PMPADDR54,
                riscv::CSR_PMPADDR55,
                riscv::CSR_PMPADDR56,
                riscv::CSR_PMPADDR57,
                riscv::CSR_PMPADDR58,
                riscv::CSR_PMPADDR59,
                riscv::CSR_PMPADDR60,
                riscv::CSR_PMPADDR61,
                riscv::CSR_PMPADDR62,
                riscv::CSR_PMPADDR63: begin
          // index is calculated using PMPADDR0 as the offset
          automatic logic [11:0] index = csr_addr.address[11:0] - riscv::CSR_PMPADDR0;
          // check if the entry or the entry above is locked
          if (!pmpcfg_q[index].locked && !(pmpcfg_q[index+1].locked && pmpcfg_q[index+1].addr_mode == riscv::TOR)) begin
            pmpaddr_w[index] = csr_wdata[G6LCCfg.PLEN-3:0];
          end
        end
          default: ;
        endcase
      end
  end

  always_comb begin : csr_wr_acc
      dcache_w   = dcache_q;
      icache_w   = icache_q;
      acc_cons_w = acc_cons_q;
      aicfg_w    = aicfg_q;
      aistatus_w = aistatus_q;
      aiscale_w  = aiscale_q;
      aizp_w     = aizp_q;
      aiqbase_w  = aiqbase_q;
      aiqctl_w   = aiqctl_q;
      aiqhead_w  = aiqhead_q;
      aiperm_w   = aiperm_q;
      bk_wr_acc_uae   = 1'b0;
      bk_wr_acc_vuae  = 1'b0;
      bk_wr_acc_flush = 1'b0;
      bk_wr_acc_dfsc  = 1'b0;
      if (csr_we) begin
        unique case (conv_csr_addr.address)
        riscv::CSR_DCACHE: dcache_w = {{G6LCCfg.XLEN - 1{1'b0}}, csr_wdata[0]};  // enable bit
        riscv::CSR_ICACHE: icache_w = {{G6LCCfg.XLEN - 1{1'b0}}, csr_wdata[0]};  // enable bit
        riscv::CSR_ACC_CONS: begin
          if (G6LCCfg.EnableAccelerator) begin
            acc_cons_w = {{G6LCCfg.XLEN - 1{1'b0}}, csr_wdata[0]};  // enable bit
          end else begin
            bk_wr_acc_uae = 1'b1;
          end
        end
        // Xg6lcai AI matrix CSRs
        12'h801: begin  // aicfg
          if (G6LCCfg.AiCfg.MatrixEn) begin
            aicfg_w = csr_wdata;
            // version field is read-only on grant path; keep contract version
            aicfg_w[19:16] = 4'd1;
            // Downgrade unsupported ew/sp24 (isa-encoding.md §3.1)
            if (!G6LCCfg.AiCfg.Int4En) aicfg_w[21:20] = 2'b00;
            if (!G6LCCfg.AiCfg.Sparse24En) aicfg_w[22] = 1'b0;
          end else bk_wr_acc_uae = 1'b1;
        end
        12'h802: begin  // aistatus — software may write ais[7:6] for lazy enable
          if (G6LCCfg.AiCfg.MatrixEn) begin
            // Preserve hardware-owned busy/error unless software clears ais to Off
            aistatus_w = aistatus_q;
            aistatus_w[7:6] = csr_wdata[7:6];  // ais
            aistatus_w[15:8] = csr_wdata[15:8];  // last error (SW clear)
            // If ais forced Off, drop dirty
            if (csr_wdata[7:6] == 2'b00) begin
              aistatus_w[1] = 1'b0;
            end
          end else bk_wr_acc_uae = 1'b1;
        end
        12'h803: begin  // aiscale
          if (G6LCCfg.AiCfg.MatrixEn) aiscale_w = csr_wdata;
          else bk_wr_acc_uae = 1'b1;
        end
        12'h804: begin  // aizp
          if (G6LCCfg.AiCfg.MatrixEn) aizp_w = csr_wdata;
          else bk_wr_acc_uae = 1'b1;
        end
        12'h5C0: begin  // aiqbase
          if (G6LCCfg.AiCfg.MatrixEn && G6LCCfg.AiCfg.Queues != 0) aiqbase_w = csr_wdata;
          else bk_wr_acc_uae = 1'b1;
        end
        12'h5C1: begin  // aiqctl
          if (G6LCCfg.AiCfg.MatrixEn && G6LCCfg.AiCfg.Queues != 0) aiqctl_w = csr_wdata;
          else bk_wr_acc_uae = 1'b1;
        end
        12'h5C2: begin  // aiqhead
          if (G6LCCfg.AiCfg.MatrixEn && G6LCCfg.AiCfg.Queues != 0) aiqhead_w = csr_wdata;
          else bk_wr_acc_uae = 1'b1;
        end
        12'h7C8: begin  // aiperm
          if (G6LCCfg.AiCfg.MatrixEn) begin
            if (!aiperm_q[3]) begin  // lock bit sticky once set
              aiperm_w = {{G6LCCfg.XLEN - 4{1'b0}}, csr_wdata[3:0]};
            end
          end else bk_wr_acc_uae = 1'b1;
        end
        // PMP locked logic
        // 1. refuse to update any locked entry
        // 2. also refuse to update the entry below a locked TOR entry
        // Note that writes to pmpcfg below a locked TOR entry are valid
          default: ;
        endcase
      end
  end

