          riscv::CSR_TDATA3: ;
          riscv::CSR_SCONTEXT: ;
          riscv::CSR_VSSTATUS: ;
          riscv::CSR_VSIE: ;
          riscv::CSR_VSIP: ;
          riscv::CSR_VSTVEC: ;
          riscv::CSR_VSSCRATCH: ;
          riscv::CSR_VSEPC: ;
          riscv::CSR_VSCAUSE: ;
          riscv::CSR_VSTVAL: ;
          riscv::CSR_VSATP: ;
          riscv::CSR_SSTATUS: ;
