          riscv::CSR_PMPADDR63: ;
          default: bk_wr_dflt_uae = 1'b1;
        endcase
      end
  end

  // Write-path sideband merge. A left-associated 15-input OR was one
  // 14 FO4 node on the trap update. A balanced tree is the same OR.
  logic [3:0][14:0] sb_bits;
  assign sb_bits[0] = {bk_wr_dflt_uae, bk_wr_acc_uae, bk_wr_pmp_uae, bk_wr_ctr_uae,
                       bk_wr_m_uae, bk_wr_h_uae, bk_wr_envcfg_uae, bk_wr_mstat_uae,
                       bk_wr_stc_uae, bk_wr_s_uae, bk_wr_ip_uae, bk_wr_vs_uae,
                       bk_wr_trig_uae, bk_wr_dbg_uae, bk_wr_fp_uae};
  assign sb_bits[1] = {bk_wr_dflt_vuae, bk_wr_acc_vuae, bk_wr_pmp_vuae, bk_wr_ctr_vuae,
                       bk_wr_m_vuae, bk_wr_h_vuae, bk_wr_envcfg_vuae, bk_wr_mstat_vuae,
                       bk_wr_stc_vuae, bk_wr_s_vuae, bk_wr_ip_vuae, bk_wr_vs_vuae,
                       bk_wr_trig_vuae, bk_wr_dbg_vuae, bk_wr_fp_vuae};
  assign sb_bits[2] = {bk_wr_dflt_flush, bk_wr_acc_flush, bk_wr_pmp_flush, bk_wr_ctr_flush,
                       bk_wr_m_flush, bk_wr_h_flush, bk_wr_envcfg_flush, bk_wr_mstat_flush,
                       bk_wr_stc_flush, bk_wr_s_flush, bk_wr_ip_flush, bk_wr_vs_flush,
                       bk_wr_trig_flush, bk_wr_dbg_flush, bk_wr_fp_flush};
  assign sb_bits[3] = {bk_wr_dflt_dfsc, bk_wr_acc_dfsc, bk_wr_pmp_dfsc, bk_wr_ctr_dfsc,
                       bk_wr_m_dfsc, bk_wr_h_dfsc, bk_wr_envcfg_dfsc, bk_wr_mstat_dfsc,
                       bk_wr_stc_dfsc, bk_wr_s_dfsc, bk_wr_ip_dfsc, bk_wr_vs_dfsc,
                       bk_wr_trig_dfsc, bk_wr_dbg_dfsc, bk_wr_fp_dfsc};
  logic [3:0][15:0] sb_l0;
  logic [3:0][7:0]  sb_l1;
  logic [3:0][3:0]  sb_l2;
  logic [3:0][1:0]  sb_l3;
  for (genvar s = 0; s < 4; s++) begin : gen_sb_or
    assign sb_l0[s] = {1'b0, sb_bits[s]};
    for (genvar i = 0; i < 8; i++) begin : gen_l1
      assign sb_l1[s][i] = sb_l0[s][2*i] | sb_l0[s][2*i+1];
    end
    for (genvar i = 0; i < 4; i++) begin : gen_l2
      assign sb_l2[s][i] = sb_l1[s][2*i] | sb_l1[s][2*i+1];
    end
    for (genvar i = 0; i < 2; i++) begin : gen_l3
      assign sb_l3[s][i] = sb_l2[s][2*i] | sb_l2[s][2*i+1];
    end
  end
  assign uae_w      = sb_l3[0][0] | sb_l3[0][1];
  assign vuae_w     = sb_l3[1][0] | sb_l3[1][1];
  assign flush_req_w = sb_l3[2][0] | sb_l3[2][1];
  assign dfsc_w     = sb_l3[3][0] | sb_l3[3][1];

  // Trap delegation. The cause index is a mux, not a guard on the
  // epc/cause writes that follow.
  logic cause_msb_w;
  logic [$clog2(G6LCCfg.XLEN)-1:0] cause_lo_w;
  logic take_ex_w, deleg_s_w, deleg_vs_w;
  logic [G6LCCfg.XLEN-1:0] vscause_vs_w;
  assign cause_msb_w = ex_i.cause[G6LCCfg.XLEN-1];
  assign cause_lo_w  = ex_i.cause[$clog2(G6LCCfg.XLEN)-1:0];
  assign take_ex_w   = (G6LCCfg.DebugEn && !debug_mode_q && ex_i.cause != riscv::DEBUG_REQUEST && ex_i.valid)
                    || (!G6LCCfg.DebugEn && ex_i.valid)
                    || (!G6LCCfg.DebugEn && G6LCCfg.SDTRIG && break_from_trigger);
  assign deleg_s_w   = G6LCCfg.RVS && ((cause_msb_w && mideleg_q[cause_lo_w]) || (!cause_msb_w && medeleg_q[cause_lo_w]));
  assign deleg_vs_w  = G6LCCfg.RVH && ((cause_msb_w && hideleg_q[cause_lo_w]) || (!cause_msb_w && hedeleg_q[cause_lo_w]));
  assign vscause_vs_w = cause_msb_w ? {ex_i.cause[G6LCCfg.XLEN-1:2], 2'b01} : ex_i.cause;

  // Zero-tval cause tests. An `inside` list is a priority chain and it sat on
  // the trap-target mux. Each cause compare is its own net; the trap arm only
  // muxes. mtval keeps the GPLEN bit the original expression used.
  logic cz_ill, cz_brk, cz_dbg, cz_eu, cz_es, cz_em;
  logic cz_iaf, cz_iam, cz_ipf, cz_igpf, cz_vi;
  logic cz_xmsb, cz_gmsb;
  logic cz_ebase, cz_ecall, cz_fetch, cz_fetch_h;
  logic tval_zero_vs, tval_zero_s, tval_zero_m, tval_zero_ht, tval_zero_mt;
  assign cz_ill  = ex_i.cause == riscv::ILLEGAL_INSTR;
  assign cz_brk  = ex_i.cause == riscv::BREAKPOINT;
  assign cz_dbg  = ex_i.cause == riscv::DEBUG_REQUEST;
  assign cz_eu   = ex_i.cause == riscv::ENV_CALL_UMODE;
  assign cz_es   = ex_i.cause == riscv::ENV_CALL_SMODE;
  assign cz_em   = ex_i.cause == riscv::ENV_CALL_MMODE;
  assign cz_iaf  = ex_i.cause == riscv::INSTR_ACCESS_FAULT;
  assign cz_iam  = ex_i.cause == riscv::INSTR_ADDR_MISALIGNED;
  assign cz_ipf  = ex_i.cause == riscv::INSTR_PAGE_FAULT;
  assign cz_igpf = ex_i.cause == riscv::INSTR_GUEST_PAGE_FAULT;
  assign cz_vi   = ex_i.cause == riscv::VIRTUAL_INSTRUCTION;
  assign cz_xmsb = ex_i.cause[G6LCCfg.XLEN-1];
  assign cz_gmsb = ex_i.cause[G6LCCfg.GPLEN-1];
  assign cz_ebase   = cz_ill | cz_brk;
  assign cz_ecall   = cz_eu | cz_es | cz_em;
  assign cz_fetch   = cz_iaf | cz_ipf | cz_igpf;
  assign cz_fetch_h = cz_fetch | cz_vi | cz_iam;
  assign tval_zero_vs = g6lc_core_pkg::ZERO_TVAL && (cz_ebase | cz_eu | cz_xmsb);
  assign tval_zero_s  = g6lc_core_pkg::ZERO_TVAL && (cz_ebase | cz_ecall | cz_xmsb);
  assign tval_zero_m  = g6lc_core_pkg::ZERO_TVAL && (cz_ebase | cz_ecall | cz_gmsb);
  assign tval_zero_ht = g6lc_core_pkg::ZERO_TVAL && (cz_ebase | cz_ecall | cz_fetch | cz_vi | cz_xmsb);
  assign tval_zero_mt = g6lc_core_pkg::ZERO_TVAL && (cz_ebase | cz_ecall | cz_fetch_h | cz_xmsb);

  always_comb begin : csr_update
    // hyp8: phase B -- holds through the per-bank writers (*_w), then the
    // original post-write overrides verbatim, in the original order.
    acc_cons_d = acc_cons_w;
    aicfg_d = aicfg_w;
    aiperm_d = aiperm_w;
    aiqbase_d = aiqbase_w;
    aiqctl_d = aiqctl_w;
    aiqhead_d = aiqhead_w;
    aiscale_d = aiscale_w;
    aistatus_d = aistatus_w;
    aizp_d = aizp_w;
    cycle_d = cycle_w;
    dcache_d = dcache_w;
    dcsr_d = dcsr_w;
    dpc_d = dpc_w;
    dscratch0_d = dscratch0_w;
    dscratch1_d = dscratch1_w;
    fcsr_d = fcsr_w;
    fiom_d = fiom_w;
    hcbcfe_d = hcbcfe_w;
    hcbie_d = hcbie_w;
    hcbze_d = hcbze_w;
    hcounteren_d = hcounteren_w;
    hedeleg_d = hedeleg_w;
    hgatp_d = hgatp_w;
    hideleg_d = hideleg_w;
    hstatus_d = hstatus_w;
    hstce_d = hstce_w;
    htimedelta_d = htimedelta_w;
    htinst_d = htinst_w;
    htval_d = htval_w;
    icache_d = icache_w;
    instret_d = instret_w;
    jvt_d = jvt_w;
    mcause_d = mcause_w;
    mcbcfe_d = mcbcfe_w;
    mcbie_d = mcbie_w;
    mcbze_d = mcbze_w;
    mcounteren_d = mcounteren_w;
    mcountinhibit_d = mcountinhibit_w;
    medeleg_d = medeleg_w;
    mepc_d = mepc_w;
    mideleg_d = mideleg_w;
    mie_d = mie_w;
    mip_d = mip_w;
    mpbmte_d = mpbmte_w;
    mscratch_d = mscratch_w;
    mstatus_d = mstatus_w;
    mstce_d = mstce_w;
    mtinst_d = mtinst_w;
    mtval2_d = mtval2_w;
    mtval_d = mtval_w;
    mtvec_d = mtvec_w;
    pmpaddr_d = pmpaddr_w;
    pmpcfg_d = pmpcfg_w;
    satp_d = satp_w;
    scause_d = scause_w;
    scbcfe_d = scbcfe_w;
    scbie_d = scbie_w;
    scbze_d = scbze_w;
    scontext_d = scontext_w;
    scounteren_d = scounteren_w;
    sepc_d = sepc_w;
    sscratch_d = sscratch_w;
    stimecmp_d = stimecmp_w;
    stval_d = stval_w;
    stvec_d = stvec_w;
    vsatp_d = vsatp_w;
    vscause_d = vscause_w;
    vsepc_d = vsepc_w;
    vsscratch_d = vsscratch_w;
    vsstatus_d = vsstatus_w;
    vstimecmp_d = vstimecmp_w;
    vstval_d = vstval_w;
    vstvec_d = vstvec_w;
    // untouched state holds (verbatim from the original defaults)
    priv_lvl_d   = priv_lvl_q;
    v_d          = v_q;
    debug_mode_d = debug_mode_q;
    en_ld_st_translation_d = en_ld_st_translation_q;
    if (G6LCCfg.RVH) begin
      hgeie_d = hgeie_q;
      en_ld_st_g_translation_d = en_ld_st_g_translation_q;
    end
    eret_o         = 1'b0;
    set_debug_pc_o = 1'b0;
    // merged write-path sidebands
    flush_req                       = flush_req_w;
    update_access_exception         = uae_w;
    virtual_update_access_exception = vuae_w;
    dirty_fp_state_csr              = dfsc_w;

    if (G6LCCfg.IS_XLEN64) begin
      if (G6LCCfg.RVS) mstatus_d.sxl = riscv::XLEN_64;
      else mstatus_d.sxl = riscv::XLEN_NA;
      if (G6LCCfg.RVU) mstatus_d.uxl = riscv::XLEN_64;
      else mstatus_d.uxl = riscv::XLEN_NA;
    end
    if (!G6LCCfg.RVU) begin
      mstatus_d.mpp = riscv::PRIV_LVL_M;
    end

    if (G6LCCfg.RVH) begin
      hstatus_d.vsxl = riscv::XLEN_64;
      vsstatus_d.uxl = riscv::XLEN_64;
    end
    // mark the floating point extension register as dirty
    if (G6LCCfg.FpPresent && (dirty_fp_state_csr || dirty_fp_state_i)) begin
      mstatus_d.fs = riscv::Dirty;
    end
    // mark the vector extension register as dirty
    if (G6LCCfg.RVV && dirty_v_state_i) begin
      mstatus_d.vs = riscv::Dirty;
    end
    // AI coprocessor → CSR writeback (setcfg grant + dirty)
    if (G6LCCfg.AiCfg.MatrixEn) begin
      if (ai_setcfg_we_i) begin
        aicfg_d = ai_setcfg_wdata_i;
        aicfg_d[19:16] = 4'd1;  // version RO
        if (!G6LCCfg.AiCfg.Int4En) aicfg_d[21:20] = 2'b00;
        if (!G6LCCfg.AiCfg.Sparse24En) aicfg_d[22] = 1'b0;
        aistatus_d[7:6] = 2'b11;  // Dirty
      end
      if (dirty_ai_state_i) begin
        aistatus_d[7:6] = 2'b11;  // Dirty
        aistatus_d[1]   = 1'b1;   // acc dirty sticky
      end
    end
    // AI-X: mstatus.xs is a read-only summary of aistatus.ais when the AI plane
    // is present; otherwise forced Off (spec-required hardwire). Writes to xs
    // are ignored (see mstatus/vsstatus write arms above).
    if (G6LCCfg.AiCfg.MatrixEn) begin
      mstatus_d.xs = riscv::xs_t'(aistatus_d[7:6]);
      if (G6LCCfg.RVH) begin
        vsstatus_d.xs = riscv::xs_t'(aistatus_d[7:6]);
      end
    end else begin
      mstatus_d.xs = riscv::Off;
      if (G6LCCfg.RVH) begin
        vsstatus_d.xs = riscv::Off;
      end
    end

    // hardwired extension registers
    if (G6LCCfg.RVS || G6LCCfg.RVF || G6LCCfg.AiCfg.MatrixEn) begin
      mstatus_d.sd = (mstatus_d.xs == riscv::Dirty) | (mstatus_d.fs == riscv::Dirty);
    end else begin
      mstatus_d.sd = 1'b0;
    end

    // reserve PMPCFG bits 5 and 6 (hardwire to 0)
    for (int i = 0; i < G6LCCfg.NrPMPEntries; i++) pmpcfg_d[i].reserved = 2'b0;

    // write the floating point status register
    if (G6LCCfg.FpPresent && csr_write_fflags_i) begin
      fcsr_d.fflags = csr_wdata_i[4:0] | fcsr_q.fflags;
    end

    // ----------------------------
    // Accelerator FP imprecise exceptions
    // ----------------------------

    // Update fflags as soon as a FP exception occurs in the accelerator
    // The exception is imprecise, and the fcsr.fflags update always happens immediately
    if (G6LCCfg.EnableAccelerator) begin
      fcsr_d.fflags |= acc_fflags_ex_valid_i ? acc_fflags_ex_i : 5'b0;
    end

    // ---------------------
    // External Interrupts
    // ---------------------
    // Machine Mode External Interrupt Pending
    mip_d[riscv::IRQ_M_EXT] = irq_i[0];
    // Machine software interrupt
    mip_d[riscv::IRQ_M_SOFT] = G6LCCfg.SoftwareInterruptEn && ipi_i;
    // Timer interrupt pending, coming from platform timer
    mip_d[riscv::IRQ_M_TIMER] = time_irq_i;
    // Sstc: with menvcfg.STCE set, STIP is no longer software-writable — it is a
    // pure function of (time >= stimecmp). This assignment sits after the CSR
    // write logic on purpose, so it overrides any write through mip/sip and
    // makes the bit effectively read-only, as the extension requires.
    if (G6LCCfg.SstcEn && mstce_q) begin
      mip_d[riscv::IRQ_S_TIMER] = stimecmp_hit_q;
    end
    // U9.0 Sstc + H: VSTIP is hardwired from (time >= vstimecmp) when both
    // menvcfg.STCE and henvcfg.STCE are set (Sstc for VS-mode).
    if (G6LCCfg.SstcEn && G6LCCfg.RVH && mstce_q && hstce_q) begin
      mip_d[riscv::IRQ_VS_TIMER] = vstimecmp_hit_q;
    end
    // Sscofpmf: LCOFIP tracks the OR of mhpmeventN.OF bits (cleared by writing OF=0).
    if (G6LCCfg.SscofpmfEn) begin
      mip_d[riscv::IRQ_LCOF] = lcofi_i;
    end

    // -----------------------
    // Manage Exception Stack
    // -----------------------
    // update exception CSRs
    // we got an exception update cause, pc and stval register
    trap_to_priv_lvl = riscv::PRIV_LVL_M;
    trap_to_v = 1'b0;
    // Delegation selects are outside the trap nest. A variable index
    // in the if guard was billed on every CSR write inside the nest.
    // Exception is taken and we are not in debug mode
    // exceptions in debug mode don't update any fields
    if (take_ex_w) begin
      // do not flush, flush is reserved for CSR writes with side effects
      flush_req = 1'b0;
      // figure out where to trap to
      // a m-mode trap might be delegated if we are taking it in S mode
      // first figure out if this was an exception or an interrupt e.g.: look at bit (XLEN-1)
      // the cause register can only be $clog2(G6LCCfg.XLEN) bits long (as we only support XLEN exceptions)
      if (deleg_s_w) begin
        // traps never transition from a more-privileged mode to a less privileged mode
        // so if we are already in M mode, stay there
        // Machine mode is 2'b11. The package enum has no width in the timer.
        trap_to_priv_lvl = (2'(priv_lvl_o) == 2'b11) ? riscv::PRIV_LVL_M : riscv::PRIV_LVL_S;
        if (deleg_vs_w) trap_to_v = v_q;
      end

      // trap to supervisor mode. hyp8 RVH is 0, so this is never a VS trap.
      // The struct-field if did not fold, and the VS arm was a 10.5 FO4
      // guard on the same-cycle cause/epc update.
      // Supervisor mode is 2'b01.
      if (G6LCCfg.RVS && trap_to_priv_lvl == 2'b01) begin
          // update sstatus
          mstatus_d.sie = 1'b0;
          mstatus_d.spie = mstatus_q.sie;
          // this can either be user or supervisor mode
          mstatus_d.spp = priv_lvl_q[0];
          // set cause
          scause_d = ex_i.cause;
          // set epc
          sepc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{pc_i[G6LCCfg.VLEN-1]}}, pc_i};
          // set mtval or stval
          stval_d        = tval_zero_s ? '0 : ex_i.tval;
          if (G6LCCfg.RVH) begin
            htinst_d       = tval_zero_ht ? '0 : {{G6LCCfg.XLEN - 32 {1'b0}}, ex_i.tinst};
            hstatus_d.spvp = v_q ? priv_lvl_q[0] : hstatus_d.spvp;
            htval_d = {{G6LCCfg.XLEN - G6LCCfg.GPLEN + 2{1'b0}}, ex_i.tval2[G6LCCfg.GPLEN-1:2]};
            hstatus_d.gva = ex_i.gva;
            hstatus_d.spv = v_q;
          end
        // trap to machine mode
      end else begin
        // update mstatus
        mstatus_d.mie = 1'b0;
        mstatus_d.mpie = mstatus_q.mie;
        // save the previous privilege mode
        mstatus_d.mpp = priv_lvl_q;
        mcause_d = (break_from_trigger) ? G6LCCfg.XLEN'(32'h00000003) : ex_i.cause;
        // set epc
        mepc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{pc_i[G6LCCfg.VLEN-1]}}, pc_i};
        // set mtval or stval
        if (G6LCCfg.TvalEn) begin
          mtval_d        = tval_zero_m ? '0 : ex_i.tval;
        end else begin
          mtval_d = '0;
        end

        if (G6LCCfg.RVH) begin
          // save previous virtualization mode
          mstatus_d.mpv = v_q;
          mtinst_d       = tval_zero_mt ? '0 : {{G6LCCfg.XLEN - 32 {1'b0}}, ex_i.tinst};
          mtval2_d = {{G6LCCfg.XLEN - G6LCCfg.GPLEN + 2{1'b0}}, ex_i.tval2[G6LCCfg.GPLEN-1:2]};
          mstatus_d.gva = ex_i.gva;
        end
      end

      priv_lvl_d = trap_to_priv_lvl;
      if (G6LCCfg.RVH) begin
        v_d = trap_to_v;
      end
    end

    // ------------------------------
    // Debug
    // ------------------------------
    // Explains why Debug Mode was entered.
    // When there are multiple reasons to enter Debug Mode in a single cycle, hardware should set cause to the cause with the highest priority.
    // 1: An ebreak instruction was executed. (priority 3)
    // 2: The Trigger Module caused a breakpoint exception. (priority 4)
    // 3: The debugger requested entry to Debug Mode. (priority 2)
    // 4: The hart single stepped because step was set. (priority 1)
    // we are currently not in debug mode and could potentially enter
    if (G6LCCfg.DebugEn && !debug_mode_q) begin
      dcsr_d.prv = priv_lvl_o;
      // save virtualization mode bit
      dcsr_d.v   = (!G6LCCfg.RVH) ? 1'b0 : v_q;

      // trigger module fired
      if (G6LCCfg.SDTRIG && debug_from_trigger) begin
        dcsr_d.prv = priv_lvl_o;
        dcsr_d.v = (!G6LCCfg.RVH) ? 1'b0 : v_q;
        dpc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{pc_i[G6LCCfg.VLEN-1]}}, pc_i};
        debug_mode_d = 1'b1;
        set_debug_pc_o = 1'b1;
        dcsr_d.cause = g6lc_core_pkg::CauseTrigger;
      end

      // caused by a breakpoint
      // cz_brk is the same cause compare, outside this process so the
      // dcsr write is not also the 64-bit match.
      if (ex_i.valid && cz_brk) begin
        dcsr_d.prv = priv_lvl_o;
        // save virtualization mode bit
        dcsr_d.v   = (!G6LCCfg.RVH) ? 1'b0 : v_q;
        // check that we actually want to enter debug depending on the privilege level we are currently in
        unique case (priv_lvl_o)
          riscv::PRIV_LVL_M: begin
            debug_mode_d   = dcsr_q.ebreakm;
            set_debug_pc_o = dcsr_q.ebreakm;
          end
          riscv::PRIV_LVL_S: begin
            if (G6LCCfg.RVS) begin
              debug_mode_d   = (G6LCCfg.RVH && v_q) ? dcsr_q.ebreakvs : dcsr_q.ebreaks;
              set_debug_pc_o = (G6LCCfg.RVH && v_q) ? dcsr_q.ebreakvs : dcsr_q.ebreaks;
            end
          end
          riscv::PRIV_LVL_U: begin
            if (G6LCCfg.RVU) begin
              debug_mode_d   = (G6LCCfg.RVH && v_q) ? dcsr_q.ebreakvu : dcsr_q.ebreaku;
              set_debug_pc_o = (G6LCCfg.RVH && v_q) ? dcsr_q.ebreakvu : dcsr_q.ebreaku;
            end
          end
          default: ;
        endcase
        // save PC of next this instruction e.g.: the next one to be executed
        dpc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{pc_i[G6LCCfg.VLEN-1]}}, pc_i};
        dcsr_d.cause = g6lc_core_pkg::CauseBreakpoint;
      end

      // we've got a debug request
      if (ex_i.valid && cz_dbg) begin
        dcsr_d.prv = priv_lvl_o;
        dcsr_d.v = (!G6LCCfg.RVH) ? 1'b0 : v_q;
        // save the PC
        dpc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{pc_i[G6LCCfg.VLEN-1]}}, pc_i};
        // enter debug mode
        debug_mode_d = 1'b1;
        // jump to the base address
        set_debug_pc_o = 1'b1;
        // save the cause as external debug request
        dcsr_d.cause = g6lc_core_pkg::CauseRequest;
      end

      // single step enable and we just retired an instruction
      if (dcsr_q.step && commit_ack_i[0]) begin
        dcsr_d.prv = priv_lvl_o;
        dcsr_d.v   = (!G6LCCfg.RVH) ? 1'b0 : v_q;
        // valid CTRL flow change
        if (commit_instr_i.fu == CTRL_FLOW) begin
          // we saved the correct target address during execute
          dpc_d = {
            {G6LCCfg.XLEN - G6LCCfg.VLEN{commit_instr_i.bp.predict_address[G6LCCfg.VLEN-1]}},
            commit_instr_i.bp.predict_address
          };
          // exception valid
        end else if (ex_i.valid) begin
          dpc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{1'b0}}, trap_vector_base_o};
          // return from environment
        end else if (eret_o) begin
          dpc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{1'b0}}, epc_o};
          // consecutive PC
        end else begin
          dpc_d = {
            {G6LCCfg.XLEN - G6LCCfg.VLEN{commit_instr_i.pc[G6LCCfg.VLEN-1]}},
            commit_instr_i.pc + (commit_instr_i.is_compressed ? 'h2 : 'h4)
          };
        end
        debug_mode_d   = 1'b1;
        set_debug_pc_o = 1'b1;
        dcsr_d.cause   = g6lc_core_pkg::CauseSingleStep;
      end
    end
    // go in halt-state again when we encounter an exception
    if (G6LCCfg.DebugEn && debug_mode_q && ex_i.valid && cz_brk) begin
      set_debug_pc_o = 1'b1;
    end

    // ------------------------------
    // MPRV - Modify Privilege Level
    // ------------------------------
    // Set the address translation at which the load and stores should occur
    // we can use the previous values since changing the address translation will always involve a pipeline flush
    if (G6LCCfg.RVH) begin
      if (mprv && (mstatus_q.mpv == 1'b0) && (config_pkg::vm_mode_t'(satp_q.mode) == G6LCCfg.MODE_SV) && (mstatus_q.mpp != riscv::PRIV_LVL_M)) begin
        en_ld_st_translation_d = 1'b1;
      end else if (mprv && (mstatus_q.mpv == 1'b1)) begin
        if (config_pkg::vm_mode_t'(vsatp_q.mode) == G6LCCfg.MODE_SV) begin
          en_ld_st_translation_d = 1'b1;
        end else begin
          en_ld_st_translation_d = 1'b0;
        end
      end else begin  // otherwise we go with the regular settings
        en_ld_st_translation_d = en_translation_o;
      end

      if (mprv && (mstatus_q.mpv == 1'b1)) begin
        if (config_pkg::vm_mode_t'(hgatp_q.mode) == G6LCCfg.MODE_SV) begin
          en_ld_st_g_translation_d = 1'b1;
        end else begin
          en_ld_st_g_translation_d = 1'b0;
        end
      end else begin
        en_ld_st_g_translation_d = en_g_translation_o;
      end

      if (csr_hs_ld_st_inst_i) ld_st_priv_lvl_o = riscv::priv_lvl_t'(hstatus_q.spvp);
      else ld_st_priv_lvl_o = (mprv) ? mstatus_q.mpp : priv_lvl_o;

      ld_st_v_o = ((mprv ? mstatus_q.mpv : v_q) || (csr_hs_ld_st_inst_i));

      en_ld_st_translation_o = (en_ld_st_translation_q && !csr_hs_ld_st_inst_i) || (config_pkg::vm_mode_t'(vsatp_q.mode) == G6LCCfg.MODE_SV && csr_hs_ld_st_inst_i);

      en_ld_st_g_translation_o = (en_ld_st_g_translation_q && !csr_hs_ld_st_inst_i) || (csr_hs_ld_st_inst_i && config_pkg::vm_mode_t'(hgatp_q.mode) == G6LCCfg.MODE_SV && csr_hs_ld_st_inst_i);
    end else begin
      if (G6LCCfg.MmuPresent && mprv && G6LCCfg.RVS && config_pkg::vm_mode_t'(satp_q.mode) == G6LCCfg.MODE_SV && (mstatus_q.mpp != riscv::PRIV_LVL_M))
        en_ld_st_translation_d = 1'b1;
      else  // otherwise we go with the regular settings
        en_ld_st_translation_d = en_translation_o;

      if (G6LCCfg.RVU) begin
        ld_st_priv_lvl_o = (mprv) ? mstatus_q.mpp : priv_lvl_o;
      end else begin
        ld_st_priv_lvl_o = priv_lvl_o;
      end
      en_ld_st_translation_o = en_ld_st_translation_q;
      ld_st_v_o = 1'b0;
      en_ld_st_g_translation_o = 1'b0;
    end
    // ------------------------------
    // Return from Environment
    // ------------------------------
    // When executing an xRET instruction, supposing xPP holds the value y, xIE is set to xPIE; the privilege
    // mode is changed to y; xPIE is set to 1; and xPP is set to U
    if (mret) begin
      // return from exception, IF doesn't care from where we are returning
      eret_o        = 1'b1;
      // return to the previous privilege level and restore all enable flags
      // get the previous machine interrupt enable flag
      mstatus_d.mie = mstatus_q.mpie;
      // restore the previous privilege level
      priv_lvl_d    = mstatus_q.mpp;
      mstatus_d.mpp = riscv::PRIV_LVL_M;
      if (G6LCCfg.RVU) begin
        // set mpp to user mode
        mstatus_d.mpp = riscv::PRIV_LVL_U;
      end
      // set mpie to 1
      mstatus_d.mpie = 1'b1;
      if (G6LCCfg.RVH) begin
        // set virtualization mode
        v_d           = mstatus_q.mpv;
        //set mstatus mpv to false
        mstatus_d.mpv = 1'b0;
        if (mstatus_q.mpp != riscv::PRIV_LVL_M) mstatus_d.mprv = 1'b0;
      end
    end

    if (G6LCCfg.RVS && sret && ((G6LCCfg.RVH && !v_q) || !G6LCCfg.RVH)) begin
      // return from exception, IF doesn't care from where we are returning
      eret_o         = 1'b1;
      // return the previous supervisor interrupt enable flag
      mstatus_d.sie  = mstatus_q.spie;
      // restore the previous privilege level
      priv_lvl_d     = riscv::priv_lvl_t'({1'b0, mstatus_q.spp});
      // set spp to user mode
      mstatus_d.spp  = 1'b0;
      // set spie to 1
      mstatus_d.spie = 1'b1;
      if (G6LCCfg.RVH) begin
        // set virtualization mode
        v_d            = hstatus_q.spv;
        //set hstatus spv to false
        hstatus_d.spv  = 1'b0;
        mstatus_d.mprv = 1'b0;
      end
    end

    if (G6LCCfg.RVH) begin
      if (sret && v_q) begin
        // return from exception, IF doesn't care from where we are returning
        eret_o          = 1'b1;
        // return the previous supervisor interrupt enable flag
        vsstatus_d.sie  = vsstatus_q.spie;
        // restore the previous privilege level
        priv_lvl_d      = riscv::priv_lvl_t'({1'b0, vsstatus_q.spp});
        // set spp to user mode
        vsstatus_d.spp  = 1'b0;
        // set spie to 1
        vsstatus_d.spie = 1'b1;
      end
    end

    // return from debug mode
    if (G6LCCfg.DebugEn) begin
      if (dret) begin
        // return from exception, IF doesn't care from where we are returning
        eret_o     = 1'b1;
        // restore the previous privilege level
        priv_lvl_d = riscv::priv_lvl_t'(dcsr_q.prv);
        if (G6LCCfg.RVH) begin
          // restore the previous virtualization mode
          v_d = dcsr_q.v;
        end
        // actually return from debug mode
        debug_mode_d = 1'b0;
      end
    end
  end

  //pragma translate_off
  // hyp8: verbatim pre-split csr_update as the equivalence reference; every
  // rf_* output must equal the split implementation's signal cycle-by-cycle.
  // hyp8: reference-cone signals (translate_off)
  logic [G6LCCfg.XLEN-1:0] rf_acc_cons_d;
  logic [G6LCCfg.XLEN-1:0] rf_aicfg_d;
  logic [G6LCCfg.XLEN-1:0] rf_aiperm_d;
  logic [G6LCCfg.XLEN-1:0] rf_aiqbase_d;
  logic [G6LCCfg.XLEN-1:0] rf_aiqctl_d;
  logic [G6LCCfg.XLEN-1:0] rf_aiqhead_d;
  logic [G6LCCfg.XLEN-1:0] rf_aiscale_d;
  logic [G6LCCfg.XLEN-1:0] rf_aistatus_d;
  logic [G6LCCfg.XLEN-1:0] rf_aizp_d;
  logic [63:0] rf_cycle_d;
  logic [G6LCCfg.XLEN-1:0] rf_dcache_d;
  riscv::dcsr_t rf_dcsr_d;
  logic rf_debug_mode_d;
  logic rf_dirty_fp_state_csr;
  logic [G6LCCfg.XLEN-1:0] rf_dpc_d;
  logic [G6LCCfg.XLEN-1:0] rf_dscratch0_d;
  logic [G6LCCfg.XLEN-1:0] rf_dscratch1_d;
  logic rf_en_ld_st_g_translation_d;
  logic rf_en_ld_st_g_translation_o;
  logic rf_en_ld_st_translation_d;
  logic rf_en_ld_st_translation_o;
  logic rf_eret_o;
  riscv::fcsr_t rf_fcsr_d;
  logic rf_fiom_d;
  logic rf_flush_req;
  logic rf_hcbcfe_d;
  riscv::cbie_t rf_hcbie_d;
  logic rf_hcbze_d;
  logic [G6LCCfg.XLEN-1:0] rf_hcounteren_d;
  logic [G6LCCfg.XLEN-1:0] rf_hedeleg_d;
  hgatp_t rf_hgatp_d;
  logic [G6LCCfg.XLEN-1:0] rf_hgeie_d;
  logic [G6LCCfg.XLEN-1:0] rf_hideleg_d;
  riscv::hstatus_rv_t rf_hstatus_d;
  logic rf_hstce_d;
  logic [63:0] rf_htimedelta_d;
  logic [G6LCCfg.XLEN-1:0] rf_htinst_d;
  logic [G6LCCfg.XLEN-1:0] rf_htval_d;
  logic [G6LCCfg.XLEN-1:0] rf_icache_d;
  logic [63:0] rf_instret_d;
  jvt_t rf_jvt_d;
  riscv::priv_lvl_t rf_ld_st_priv_lvl_o;
  logic rf_ld_st_v_o;
  logic [G6LCCfg.XLEN-1:0] rf_mcause_d;
  logic rf_mcbcfe_d;
  riscv::cbie_t rf_mcbie_d;
  logic rf_mcbze_d;
  logic [G6LCCfg.XLEN-1:0] rf_mcounteren_d;
  logic [MHPMCounterNum+3-1:0] rf_mcountinhibit_d;
  logic [G6LCCfg.XLEN-1:0] rf_medeleg_d;
  logic [G6LCCfg.XLEN-1:0] rf_mepc_d;
  logic [G6LCCfg.XLEN-1:0] rf_mideleg_d;
  logic [G6LCCfg.XLEN-1:0] rf_mie_d;
  logic [G6LCCfg.XLEN-1:0] rf_mip_d;
  logic rf_mpbmte_d;
  logic [G6LCCfg.XLEN-1:0] rf_mscratch_d;
  riscv::mstatus_rv_t rf_mstatus_d;
  logic rf_mstce_d;
  logic [G6LCCfg.XLEN-1:0] rf_mtinst_d;
  logic [G6LCCfg.XLEN-1:0] rf_mtval2_d;
  logic [G6LCCfg.XLEN-1:0] rf_mtval_d;
  logic [G6LCCfg.XLEN-1:0] rf_mtvec_d;
  logic [G6LCCfg.XLEN-1:0] rf_perf_data_o;
  logic rf_perf_we_o;
  logic [63:0][G6LCCfg.PLEN-3:0] rf_pmpaddr_d;
  riscv::pmpcfg_t [63:0] rf_pmpcfg_d;
  riscv::priv_lvl_t rf_priv_lvl_d;
  riscv::priv_lvl_t rf_priv_lvl_o;
  // priv_lvl_o is a continuous-assign output, not an always_comb product —
  // the reference cone needs the same expression on its mirror.
  assign rf_priv_lvl_o = (G6LCCfg.DebugEn && debug_mode_q)
                       ? riscv::PRIV_LVL_M : priv_lvl_q;
  satp_t rf_satp_d;
  logic [G6LCCfg.XLEN-1:0] rf_scause_d;
  logic rf_scbcfe_d;
  riscv::cbie_t rf_scbie_d;
  logic rf_scbze_d;
  logic [G6LCCfg.XLEN-1:0] rf_scontext_d;
  logic [G6LCCfg.XLEN-1:0] rf_scounteren_d;
  logic [G6LCCfg.XLEN-1:0] rf_sepc_d;
  logic rf_set_debug_pc_o;
  logic [G6LCCfg.XLEN-1:0] rf_sscratch_d;
  logic [63:0] rf_stimecmp_d;
  logic [G6LCCfg.XLEN-1:0] rf_stval_d;
  logic [G6LCCfg.XLEN-1:0] rf_stvec_d;
  logic [G6LCCfg.XLEN-1:0] rf_tdata1_to_tm;
  logic rf_tdata1_we;
  logic [G6LCCfg.XLEN-1:0] rf_tdata2_to_tm;
  logic rf_tdata2_we;
  logic [G6LCCfg.XLEN-1:0] rf_tdata3_to_tm;
  logic rf_tdata3_we;
  riscv::priv_lvl_t rf_trap_to_priv_lvl;
  logic rf_trap_to_v;
  logic [G6LCCfg.XLEN-1:0] rf_tselect_to_tm;
  logic rf_tselect_we;
  logic rf_update_access_exception;
  logic rf_v_d;
  logic rf_virtual_update_access_exception;
  satp_t rf_vsatp_d;
  logic [G6LCCfg.XLEN-1:0] rf_vscause_d;
  logic [G6LCCfg.XLEN-1:0] rf_vsepc_d;
  logic [G6LCCfg.XLEN-1:0] rf_vsscratch_d;
  riscv::mstatus_rv_t rf_vsstatus_d;
  logic [63:0] rf_vstimecmp_d;
  logic [G6LCCfg.XLEN-1:0] rf_vstval_d;
  logic [G6LCCfg.XLEN-1:0] rf_vstvec_d;

  always_comb begin : csr_update_ref
    automatic satp_t satp;
    automatic satp_t vsatp;
    automatic hgatp_t hgatp;
    automatic logic [63:0] instret;
    automatic logic [G6LCCfg.XLEN-1:0] rf_mask;

    if (G6LCCfg.RVS) begin
      satp = satp_q;
    end
    if (G6LCCfg.RVH) begin
      hgatp = hgatp_q;
      vsatp = vsatp_q;
    end
    instret         = instret_q;

    rf_mcountinhibit_d = mcountinhibit_q;

    // --------------------
    // Counters (hyp8: value path split into csr_counters --
    // low-half increment + registered carry)
    // --------------------
    rf_cycle_d         = cycle_incr;
    rf_instret_d       = instret_incr;

    rf_eret_o                          = 1'b0;
    rf_flush_req                         = 1'b0;
    rf_update_access_exception         = 1'b0;
    rf_virtual_update_access_exception = 1'b0;

    rf_set_debug_pc_o                  = 1'b0;

    rf_perf_we_o                       = 1'b0;
    rf_perf_data_o                     = 'b0;
    if (G6LCCfg.RVZCMT) begin
      rf_jvt_d = jvt_q;
    end
    rf_fcsr_d       = fcsr_q;

    rf_priv_lvl_d   = priv_lvl_q;
    rf_v_d          = v_q;
    rf_debug_mode_d = debug_mode_q;

    if (G6LCCfg.DebugEn) begin
      rf_dcsr_d      = dcsr_q;
      rf_dpc_d       = dpc_q;
      rf_dscratch0_d = dscratch0_q;
      rf_dscratch1_d = dscratch1_q;
    end
    rf_mstatus_d = mstatus_q;
    if (G6LCCfg.RVH) begin
      rf_hstatus_d  = hstatus_q;
      rf_vsstatus_d = vsstatus_q;
    end

    // check whether we come out of reset
    // this is a workaround. some tools have issues
    // having boot_addr_i in the asynchronous
    // reset assignment to rf_mtvec_d, even though
    // boot_addr_i will be assigned a constant
    // on the top-level.
    if (mtvec_rst_load_q) begin
      rf_mtvec_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{1'b0}}, boot_addr_i} + 'h40;
    end else begin
      rf_mtvec_d = mtvec_q;
    end

    if (G6LCCfg.RVS) begin
      rf_medeleg_d = medeleg_q;
      rf_mideleg_d = mideleg_q;
    end
    rf_mip_d        = mip_q;
    rf_mie_d        = mie_q;
    rf_mepc_d       = mepc_q;
    rf_mcause_d     = mcause_q;
    rf_mcounteren_d = mcounteren_q;
    rf_mscratch_d   = mscratch_q;
    if (G6LCCfg.TvalEn) rf_mtval_d = mtval_q;
    if (G6LCCfg.RVH) begin
      rf_mtinst_d = mtinst_q;
      rf_mtval2_d = mtval2_q;
    end

    rf_fiom_d     = fiom_q;
    rf_dcache_d   = dcache_q;
    rf_icache_d   = icache_q;
    rf_acc_cons_d = acc_cons_q;
    // AI CSR defaults (hold)
    rf_aicfg_d    = aicfg_q;
    rf_aistatus_d = aistatus_q;
    rf_aiscale_d  = aiscale_q;
    rf_aizp_d     = aizp_q;
    rf_aiqbase_d  = aiqbase_q;
    rf_aiqctl_d   = aiqctl_q;
    rf_aiqhead_d  = aiqhead_q;
    rf_aiperm_d   = aiperm_q;

    if (G6LCCfg.SstcEn) begin
      rf_stimecmp_d = stimecmp_q;
      rf_mstce_d    = mstce_q;
    end else begin
      rf_stimecmp_d = '0;
      rf_mstce_d    = 1'b0;
    end
    // U9.0 Sstc + H defaults (vstimecmp / henvcfg.STCE)
    if (G6LCCfg.SstcEn && G6LCCfg.RVH) begin
      rf_vstimecmp_d = vstimecmp_q;
      rf_hstce_d     = hstce_q;
    end else begin
      rf_vstimecmp_d = '0;
      rf_hstce_d     = 1'b0;
    end
    // U9.1: htimedelta lives under RVH (guest time virtualization), not only Sstc
    if (G6LCCfg.RVH) rf_htimedelta_d = htimedelta_q;
    else rf_htimedelta_d = '0;

    if (G6LCCfg.RVH) begin
      rf_vstvec_d                 = vstvec_q;
      rf_vsscratch_d              = vsscratch_q;
      rf_vsepc_d                  = vsepc_q;
      rf_vscause_d                = vscause_q;
      rf_vstval_d                 = vstval_q;
      rf_vsatp_d                  = vsatp_q;
      rf_hgatp_d                  = hgatp_q;
      rf_hedeleg_d                = hedeleg_q;
      rf_hideleg_d                = hideleg_q;
      rf_hgeie_d                  = hgeie_q;
      rf_hcounteren_d             = hcounteren_q;
      rf_htinst_d                 = htinst_q;
      rf_htval_d                  = htval_q;
      rf_en_ld_st_g_translation_d = en_ld_st_g_translation_q;
    end

    if (G6LCCfg.RVS) begin
      rf_sepc_d       = sepc_q;
      rf_scause_d     = scause_q;
      rf_stvec_d      = stvec_q;
      rf_scounteren_d = scounteren_q;
      rf_sscratch_d   = sscratch_q;
      rf_stval_d      = stval_q;
      rf_satp_d       = satp_q;
    end

    rf_en_ld_st_translation_d = en_ld_st_translation_q;
    rf_dirty_fp_state_csr     = 1'b0;

    rf_pmpcfg_d               = pmpcfg_q;
    rf_pmpaddr_d              = pmpaddr_q;

    rf_mcbie_d                = mcbie_q;
    rf_scbie_d                = scbie_q;
    rf_hcbie_d                = hcbie_q;

    rf_mcbcfe_d               = mcbcfe_q;
    rf_scbcfe_d               = scbcfe_q;
    rf_hcbcfe_d               = hcbcfe_q;

    rf_mcbze_d                = mcbze_q;
    rf_scbze_d                = scbze_q;
    rf_hcbze_d                = hcbze_q;
    rf_mpbmte_d               = mpbmte_q;

    // trigger module defaults
    rf_tdata1_to_tm           = '0;
    rf_tdata2_to_tm           = '0;
    rf_tdata3_to_tm           = '0;
    rf_tselect_to_tm          = '0;
    rf_tselect_we             = 1'b0;
    rf_tdata1_we              = 1'b0;
    rf_tdata2_we              = 1'b0;
    rf_tdata3_we              = 1'b0;

    // check for correct access rights and that we are writing
    if (csr_we) begin
      unique case (conv_csr_addr.address)
        // Floating-Point
        riscv::CSR_FFLAGS: begin
          if (fp_live) begin
            rf_dirty_fp_state_csr = 1'b1;
            rf_fcsr_d.fflags = csr_wdata[4:0];
            // this instruction has side-effects
            rf_flush_req = 1'b1;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_FRM: begin
          if (fp_live) begin
            rf_dirty_fp_state_csr = 1'b1;
            rf_fcsr_d.frm    = csr_wdata[2:0];
            // this instruction has side-effects
            rf_flush_req = 1'b1;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_FCSR: begin
          if (fp_live) begin
            rf_dirty_fp_state_csr = 1'b1;
            rf_fcsr_d[7:0] = csr_wdata[7:0];  // ignore writes to reserved space
            // this instruction has side-effects
            rf_flush_req = 1'b1;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_FTRAN: begin
          if (fp_live) begin
            rf_dirty_fp_state_csr = 1'b1;
            rf_fcsr_d.fprec = csr_wdata[6:0];  // ignore writes to reserved space
            // this instruction has side-effects
            rf_flush_req = 1'b1;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        // debug CSR
        riscv::CSR_DCSR: begin
          if (G6LCCfg.DebugEn) begin
            rf_dcsr_d           = csr_wdata[31:0];
            // debug is implemented
            rf_dcsr_d.xdebugver = 4'h4;
            // currently not supported
            rf_dcsr_d.nmip      = 1'b0;
            rf_dcsr_d.stopcount = 1'b0;
            rf_dcsr_d.stoptime  = 1'b0;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_DPC:
        if (G6LCCfg.DebugEn) rf_dpc_d = csr_wdata;
        else rf_update_access_exception = 1'b1;
        riscv::CSR_DSCRATCH0:
        if (G6LCCfg.DebugEn) rf_dscratch0_d = csr_wdata;
        else rf_update_access_exception = 1'b1;
        riscv::CSR_DSCRATCH1:
        if (G6LCCfg.DebugEn) rf_dscratch1_d = csr_wdata;
        else rf_update_access_exception = 1'b1;
        riscv::CSR_JVT: begin
          if (G6LCCfg.RVZCMT) begin
            rf_jvt_d.base = csr_wdata[G6LCCfg.XLEN-1:6];
            rf_jvt_d.mode = 6'b000000;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        // Trigger module CSRs
        riscv::CSR_TSELECT: begin
          if (G6LCCfg.SDTRIG) begin
            rf_tselect_to_tm = csr_wdata;
            rf_tselect_we    = csr_we;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_TDATA1: begin
          if (G6LCCfg.SDTRIG) begin
            rf_tdata1_to_tm = csr_wdata;
            rf_tdata1_we    = csr_we;
            rf_flush_req = flush_from_tm;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_TDATA2: begin
          if (G6LCCfg.SDTRIG) begin
            rf_tdata2_to_tm = csr_wdata;
            rf_tdata2_we    = csr_we;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_TDATA3: begin
          if (G6LCCfg.SDTRIG) begin
            rf_tdata3_to_tm = csr_wdata;
            rf_tdata3_we    = csr_we;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_SCONTEXT: begin
          if (G6LCCfg.SDTRIG) begin
            rf_scontext_d = {{G6LCCfg.XLEN - 32{1'b0}}, csr_wdata[31:0]};
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        // virtual supervisor registers
        riscv::CSR_VSSTATUS: begin
          if (G6LCCfg.RVH) begin
            rf_mask = g6lc_core_pkg::SMODE_STATUS_WRITE_MASK[G6LCCfg.XLEN-1:0];
            rf_vsstatus_d = (vsstatus_q & ~{{64-G6LCCfg.XLEN{1'b0}}, rf_mask}) | {{64-G6LCCfg.XLEN{1'b0}}, (csr_wdata & rf_mask)};
            // XS read-only summary (AI-E3); forced Off here, re-driven from ais below.
            rf_vsstatus_d.xs = riscv::Off;
            if (!G6LCCfg.FpPresent) begin
              rf_vsstatus_d.fs = riscv::Off;
            end
            // this instruction has side-effects
            rf_flush_req = 1'b1;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_VSIE:
        if (G6LCCfg.RVH) rf_mie_d = (mie_q & ~hideleg_q) | ((csr_wdata << 1) & hideleg_q);
        else rf_update_access_exception = 1'b1;
        riscv::CSR_VSIP: begin
          if (G6LCCfg.RVH) begin
            // only the virtual supervisor software interrupt is write-able, iff delegated
            rf_mask  = G6LCCfg.XLEN'(riscv::MIP_VSSIP) & hideleg_q;
            rf_mip_d = (mip_q & ~rf_mask) | ((csr_wdata << 1) & rf_mask);
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_VSTVEC: begin
          if (G6LCCfg.RVH) begin
            rf_vstvec_d = {csr_wdata[G6LCCfg.XLEN-1:2], 1'b0, csr_wdata[0]};
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_VSSCRATCH:
        if (G6LCCfg.RVH) rf_vsscratch_d = csr_wdata;
        else rf_update_access_exception = 1'b1;
        riscv::CSR_VSEPC:
        if (G6LCCfg.RVH) rf_vsepc_d = {csr_wdata[G6LCCfg.XLEN-1:1], 1'b0};
        else rf_update_access_exception = 1'b1;
        riscv::CSR_VSCAUSE:
        if (G6LCCfg.RVH) rf_vscause_d = csr_wdata;
        else rf_update_access_exception = 1'b1;
        riscv::CSR_VSTVAL:
        if (G6LCCfg.RVH) rf_vstval_d = csr_wdata;
        else rf_update_access_exception = 1'b1;
        // virtual supervisor address translation and protection
        riscv::CSR_VSATP: begin
          if (G6LCCfg.RVH) begin
            if (rf_priv_lvl_o == riscv::PRIV_LVL_S && hstatus_q.vtvm && v_q) begin
              rf_virtual_update_access_exception = 1'b1;
            end else begin
              vsatp = satp_t'(csr_wdata);
              // only make ASID_LEN - 1 bit stick, that way software can figure out how many ASID bits are supported
              vsatp.asid = vsatp.asid & {{(G6LCCfg.ASIDW - G6LCCfg.ASID_WIDTH) {1'b0}}, {G6LCCfg.ASID_WIDTH{1'b1}}};
              // only update if we actually support this mode
              if (config_pkg::vm_mode_t'(vsatp.mode) == config_pkg::ModeOff ||
                                config_pkg::vm_mode_t'(vsatp.mode) == G6LCCfg.MODE_SV)
                rf_vsatp_d = vsatp;
            end
            // changing the mode can have side-effects on address translation (e.g.: other instructions), re-fetch
            // the next instruction by executing a flush
            rf_flush_req = 1'b1;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        // sstatus is a subset of mstatus - rf_mask it accordingly
        riscv::CSR_SSTATUS: begin
          if (G6LCCfg.RVS) begin
            rf_mask = g6lc_core_pkg::SMODE_STATUS_WRITE_MASK[G6LCCfg.XLEN-1:0];
            rf_mstatus_d = (mstatus_q & ~{{64-G6LCCfg.XLEN{1'b0}}, rf_mask}) | {{64-G6LCCfg.XLEN{1'b0}}, (csr_wdata & rf_mask)};
            // hardwire to zero if floating point extension is not present
            if (!G6LCCfg.FpPresent) begin
              rf_mstatus_d.fs = riscv::Off;
            end
            // hardwire to zero if vector extension is not present
            if (!G6LCCfg.RVV) begin
              rf_mstatus_d.vs = riscv::Off;
            end
            // If h-extension is not enabled, priv level HS is reserved
            if (!G6LCCfg.RVH) begin
              if (rf_mstatus_d.mpp == riscv::PRIV_LVL_HS) begin
                rf_mstatus_d.mpp = mstatus_q.mpp;
              end
            end
            // this instruction has side-effects
            rf_flush_req = 1'b1;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        // even machine mode interrupts can be visible and set-able to supervisor
        // if the corresponding bit in mideleg is set
        riscv::CSR_SIE: begin
          if (G6LCCfg.RVS) begin
            rf_mask  = (G6LCCfg.RVH) ? mideleg_q & ~HS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0] : mideleg_q;
            // the mideleg makes sure only delegate-able register (and therefore also only implemented registers) are written
            rf_mie_d = (mie_q & ~rf_mask) | (csr_wdata & rf_mask);
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end

        riscv::CSR_SIP: begin
          if (G6LCCfg.RVS) begin
            // only the supervisor software interrupt is write-able, iff delegated
            rf_mask  = G6LCCfg.XLEN'(riscv::MIP_SSIP) & mideleg_q;
            rf_mip_d = (mip_q & ~rf_mask) | (csr_wdata & rf_mask);
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end

        riscv::CSR_STVEC:
        if (G6LCCfg.RVS) rf_stvec_d = {csr_wdata[G6LCCfg.XLEN-1:2], 1'b0, csr_wdata[0]};
        else rf_update_access_exception = 1'b1;
        riscv::CSR_SCOUNTEREN:
        if (G6LCCfg.RVS) rf_scounteren_d = {{G6LCCfg.XLEN - 32{1'b0}}, csr_wdata[31:0]};
        else rf_update_access_exception = 1'b1;
        riscv::CSR_SSCRATCH:
        if (G6LCCfg.RVS) rf_sscratch_d = csr_wdata;
        else rf_update_access_exception = 1'b1;
        riscv::CSR_SEPC:
        if (G6LCCfg.RVS) rf_sepc_d = {csr_wdata[G6LCCfg.XLEN-1:1], 1'b0};
        else rf_update_access_exception = 1'b1;
        riscv::CSR_SCAUSE:
        if (G6LCCfg.RVS) rf_scause_d = csr_wdata;
        else rf_update_access_exception = 1'b1;
        riscv::CSR_STVAL:
        if (G6LCCfg.RVS && G6LCCfg.TvalEn) rf_stval_d = csr_wdata;
        else rf_update_access_exception = 1'b1;
        // Sstc: writing stimecmp re-arms the supervisor timer. Writing it also
        // implicitly clears the pending STIP, because STIP is a pure function of
        // (time >= stimecmp) once STCE is set — no explicit clear is needed.
        // V=1: stimecmp is an alias of vstimecmp; STCE fail → virtual-instruction.
        riscv::CSR_STIMECMP: begin
          if (G6LCCfg.SstcEn && G6LCCfg.RVS) begin
            if (G6LCCfg.RVH && v_q) begin
              if (!mstce_q || !hstce_q) rf_virtual_update_access_exception = 1'b1;
              else rf_vstimecmp_d[G6LCCfg.XLEN-1:0] = csr_wdata;
            end else if (rf_priv_lvl_o != riscv::PRIV_LVL_M && !mstce_q) begin
              rf_update_access_exception = 1'b1;
            end else begin
              rf_stimecmp_d[G6LCCfg.XLEN-1:0] = csr_wdata;
            end
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_STIMECMPH: begin
          if (G6LCCfg.SstcEn && G6LCCfg.RVS && G6LCCfg.IS_XLEN32) begin
            if (G6LCCfg.RVH && v_q) begin
              if (!mstce_q || !hstce_q) rf_virtual_update_access_exception = 1'b1;
              else rf_vstimecmp_d[63:32] = csr_wdata[31:0];
            end else if (rf_priv_lvl_o != riscv::PRIV_LVL_M && !mstce_q) begin
              rf_update_access_exception = 1'b1;
            end else begin
              rf_stimecmp_d[63:32] = csr_wdata[31:0];
            end
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_VSTIMECMP: begin
          if (G6LCCfg.SstcEn && G6LCCfg.RVH) begin
            if (rf_priv_lvl_o == riscv::PRIV_LVL_U ||
                (rf_priv_lvl_o == riscv::PRIV_LVL_S && v_q) ||
                (rf_priv_lvl_o != riscv::PRIV_LVL_M && !(mstce_q && hstce_q)))
              rf_update_access_exception = 1'b1;
            else rf_vstimecmp_d[G6LCCfg.XLEN-1:0] = csr_wdata;
          end else rf_update_access_exception = 1'b1;
        end
        riscv::CSR_VSTIMECMPH: begin
          if (G6LCCfg.SstcEn && G6LCCfg.RVH && G6LCCfg.IS_XLEN32) begin
            if (rf_priv_lvl_o == riscv::PRIV_LVL_U ||
                (rf_priv_lvl_o == riscv::PRIV_LVL_S && v_q) ||
                (rf_priv_lvl_o != riscv::PRIV_LVL_M && !(mstce_q && hstce_q)))
              rf_update_access_exception = 1'b1;
            else rf_vstimecmp_d[63:32] = csr_wdata[31:0];
          end else rf_update_access_exception = 1'b1;
        end
        // supervisor address translation and protection
        riscv::CSR_SATP: begin
          if (G6LCCfg.RVS) begin
            // intercept SATP writes if in S-Mode and TVM is enabled
            if (rf_priv_lvl_o == riscv::PRIV_LVL_S && mstatus_q.tvm) rf_update_access_exception = 1'b1;
            else begin
              satp = satp_t'(csr_wdata);
              // only make ASID_LEN - 1 bit stick, that way software can figure out how many ASID bits are supported
              satp.asid = satp.asid & {{(G6LCCfg.ASIDW - G6LCCfg.ASID_WIDTH) {1'b0}}, {G6LCCfg.ASID_WIDTH{1'b1}}};
              // only update if we actually support this mode
              if (config_pkg::vm_mode_t'(satp.mode) == config_pkg::ModeOff ||
                                config_pkg::vm_mode_t'(satp.mode) == G6LCCfg.MODE_SV)
                rf_satp_d = satp;
            end
            // changing the mode can have side-effects on address translation (e.g.: other instructions), re-fetch
            // the next instruction by executing a flush
            rf_flush_req = 1'b1;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_SENVCFG: begin
          if (G6LCCfg.RVS) begin
            rf_fiom_d = csr_wdata[0];
            if (G6LCCfg.RVZiCbom) begin
              unique case (csr_wdata[5:4])
                2'b00:   rf_scbie_d = riscv::CBIE_ILLEGAL;
                2'b01:   rf_scbie_d = riscv::CBIE_FLUSH;
                2'b11:   rf_scbie_d = riscv::CBIE_INVAL;
                default: rf_scbie_d = riscv::CBIE_RSVD;
              endcase
              rf_scbcfe_d = csr_wdata[6];
            end
            if (G6LCCfg.RVZiCboz) rf_scbze_d = csr_wdata[7];
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        //hypervisor mode registers
        riscv::CSR_HSTATUS: begin
          if (G6LCCfg.RVH) begin
            rf_mask = g6lc_core_pkg::HSTATUS_WRITE_MASK[G6LCCfg.XLEN-1:0];
            rf_hstatus_d = (hstatus_q & ~{{64-G6LCCfg.XLEN{1'b0}}, rf_mask}) | {{64-G6LCCfg.XLEN{1'b0}}, (csr_wdata & rf_mask)};
            // this instruction has side-effects
            rf_flush_req = 1'b1;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_HEDELEG: begin
          if (G6LCCfg.RVH) begin
            rf_mask = (1 << riscv::INSTR_ADDR_MISALIGNED) |
               (1 << riscv::INSTR_ACCESS_FAULT) |
               (1 << riscv::ILLEGAL_INSTR) |
               (1 << riscv::BREAKPOINT) |
               (1 << riscv::LD_ADDR_MISALIGNED) |
               (1 << riscv::LD_ACCESS_FAULT) |
               (1 << riscv::ST_ADDR_MISALIGNED) |
               (1 << riscv::ST_ACCESS_FAULT) |
               (1 << riscv::ENV_CALL_UMODE) |
               (1 << riscv::INSTR_PAGE_FAULT) |
               (1 << riscv::LOAD_PAGE_FAULT) |
               (1 << riscv::STORE_PAGE_FAULT);
            rf_hedeleg_d = (hedeleg_q & ~rf_mask) | (csr_wdata & rf_mask);
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_HIDELEG: begin
          if (G6LCCfg.RVH) begin
            rf_hideleg_d = (hideleg_q & ~VS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0]) | (csr_wdata & VS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0]);
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_HIE: begin
          if (G6LCCfg.RVH) begin
            rf_mask  = HS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0];
            rf_mie_d = (mie_q & ~rf_mask) | (csr_wdata & rf_mask);
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_HIP: begin
          if (G6LCCfg.RVH) begin
            rf_mask  = G6LCCfg.XLEN'(riscv::MIP_VSSIP);
            rf_mip_d = (mip_q & ~rf_mask) | (csr_wdata & rf_mask);
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_HVIP: begin
          if (G6LCCfg.RVH) begin
            // Writable VS interrupt inject bits. When Sstc×H STCE pair is on,
            // VSTIP is hardwired from (guest_time >= vstimecmp) later — exclude it
            // from the writable rf_mask so software cannot race the hardwire.
            rf_mask = VS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0];
            if (G6LCCfg.SstcEn && mstce_q && hstce_q)
              rf_mask = rf_mask & ~G6LCCfg.XLEN'(riscv::MIP_VSTIP);
            rf_mip_d = (mip_q & ~rf_mask) | (csr_wdata & rf_mask);
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_HCOUNTEREN: begin
          if (G6LCCfg.RVH) begin
            rf_hcounteren_d = {{G6LCCfg.XLEN - 32{1'b0}}, csr_wdata[31:0]};
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_HTVAL: begin
          if (G6LCCfg.RVH) begin
            rf_htval_d = csr_wdata;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_HTINST: begin
          if (G6LCCfg.RVH) begin
            rf_htinst_d = {{G6LCCfg.XLEN - 32{1'b0}}, csr_wdata[31:0]};
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        //TODO Hyp: implement hgeie write
        riscv::CSR_HGEIE: begin
          if (!G6LCCfg.RVH) begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_HGATP: begin
          if (G6LCCfg.RVH) begin
            // intercept HGATP writes if in HS-Mode and TVM is enabled
            if (rf_priv_lvl_o == riscv::PRIV_LVL_S && !v_q && mstatus_q.tvm)
              rf_update_access_exception = 1'b1;
            else begin
              hgatp = hgatp_t'(csr_wdata);
              //hardwire PPN[1:0] to zero
              hgatp[1:0] = 2'b0;
              // only make VMID_LEN - 1 bit stick, that way software can figure out how many VMID bits are supported
              hgatp.vmid = hgatp.vmid & {{(G6LCCfg.VMIDW - G6LCCfg.VMID_WIDTH) {1'b0}}, {G6LCCfg.VMID_WIDTH{1'b1}}};
              // only update if we actually support this mode
              if (config_pkg::vm_mode_t'(hgatp.mode) == config_pkg::ModeOff ||
                            config_pkg::vm_mode_t'(hgatp.mode) == G6LCCfg.MODE_SV)
                rf_hgatp_d = hgatp;
            end
            // changing the mode can have side-effects on address translation (e.g.: other instructions), re-fetch
            // the next instruction by executing a flush
            rf_flush_req = 1'b1;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_HENVCFG: begin
          if (G6LCCfg.RVH) begin
            rf_fiom_d = csr_wdata[0];
            if (G6LCCfg.RVZiCbom) begin
              unique case (csr_wdata[5:4])
                2'b00:   rf_hcbie_d = riscv::CBIE_ILLEGAL;
                2'b01:   rf_hcbie_d = riscv::CBIE_FLUSH;
                2'b11:   rf_hcbie_d = riscv::CBIE_INVAL;
                default: rf_hcbie_d = riscv::CBIE_RSVD;
              endcase
              rf_hcbcfe_d = csr_wdata[6];
            end
            if (G6LCCfg.RVZiCboz) rf_hcbze_d = csr_wdata[7];
            // henvcfg.STCE — enable VS Sstc (requires menvcfg.STCE as well)
            if (G6LCCfg.SstcEn && G6LCCfg.IS_XLEN64) rf_hstce_d = csr_wdata[G6LCCfg.XLEN-1];
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        riscv::CSR_HENVCFGH: begin
          if (G6LCCfg.RVH && G6LCCfg.IS_XLEN32) begin
            if (G6LCCfg.SstcEn) rf_hstce_d = csr_wdata[31];
          end else rf_update_access_exception = 1'b1;
        end
        // U9.1: htimedelta write (HS/M). VS access is blocked by CSR privilege decode.
        riscv::CSR_HTIMEDELTA: begin
          if (G6LCCfg.RVH) rf_htimedelta_d[G6LCCfg.XLEN-1:0] = csr_wdata;
          else rf_update_access_exception = 1'b1;
        end
        riscv::CSR_HTIMEDELTAH: begin
          if (G6LCCfg.RVH && G6LCCfg.IS_XLEN32) rf_htimedelta_d[63:32] = csr_wdata[31:0];
          else rf_update_access_exception = 1'b1;
        end
        riscv::CSR_MSTATUS: begin
          rf_mstatus_d    = {{64 - G6LCCfg.XLEN{1'b0}}, csr_wdata};
          // XS is read-only (AI-E3 / isa-encoding.md §5). Forced Off unless the
          // AI plane is present; when present it is overwritten below from ais.
          rf_mstatus_d.xs = riscv::Off;
          if (!G6LCCfg.FpPresent) begin
            rf_mstatus_d.fs = riscv::Off;
          end
          if (!G6LCCfg.RVV) begin
            rf_mstatus_d.vs = riscv::Off;
          end
          if (!G6LCCfg.RVS) begin
            rf_mstatus_d.sie  = 1'b0;
            rf_mstatus_d.spie = 1'b0;
            rf_mstatus_d.spp  = 1'b0;
            rf_mstatus_d.sum  = 1'b0;
            rf_mstatus_d.mxr  = 1'b0;
            rf_mstatus_d.tvm  = 1'b0;
            rf_mstatus_d.tsr  = 1'b0;
          end
          if (!G6LCCfg.RVU) begin
            rf_mstatus_d.tw   = 1'b0;
            rf_mstatus_d.mprv = 1'b0;
          end
          if ((!G6LCCfg.RVH & rf_mstatus_d.mpp == riscv::PRIV_LVL_HS) |
              (!G6LCCfg.RVS & rf_mstatus_d.mpp == riscv::PRIV_LVL_S) |
              (!G6LCCfg.RVU & rf_mstatus_d.mpp == riscv::PRIV_LVL_U)) begin
            rf_mstatus_d.mpp = mstatus_q.mpp;
          end
          rf_mstatus_d.wpri3 = 9'b0;
          rf_mstatus_d.wpri1 = 1'b0;
          rf_mstatus_d.wpri2 = 1'b0;
          rf_mstatus_d.wpri0 = 1'b0;
          // Mirror MBE
          rf_mstatus_d.sbe   = rf_mstatus_d.mbe;
          rf_mstatus_d.ube   = rf_mstatus_d.mbe;
          // this register has side-effects on other registers, flush the pipeline
          rf_flush_req         = 1'b1;
        end
        riscv::CSR_MSTATUSH: begin
          if (G6LCCfg.IS_XLEN32) begin
            rf_mstatus_d.mbe = ((csr_wdata & riscv::MSTATUSH_MBE) != 0);
            // Mirror MBE
            rf_mstatus_d.sbe = rf_mstatus_d.mbe;
            rf_mstatus_d.ube = rf_mstatus_d.mbe;
            // this register has side-effects on other registers, flush the pipeline
            rf_flush_req       = 1'b1;
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        // MISA is WARL (Write Any Value, Reads Legal Value)
        riscv::CSR_MISA: ;
        // machine exception delegation register
        // 0 - 15 exceptions supported
        riscv::CSR_MEDELEG: begin
          if (G6LCCfg.RVS) begin
            rf_mask = (1 << riscv::INSTR_ADDR_MISALIGNED) |
                             (1 << riscv::INSTR_ACCESS_FAULT) |
                             (1 << riscv::ILLEGAL_INSTR) |
                             (1 << riscv::BREAKPOINT) |
                             (1 << riscv::LD_ADDR_MISALIGNED) |
                             (1 << riscv::LD_ACCESS_FAULT) |
                             (1 << riscv::ST_ADDR_MISALIGNED) |
                             (1 << riscv::ST_ACCESS_FAULT) |
                             (1 << riscv::ENV_CALL_UMODE) |
                             ((G6LCCfg.RVH ? 1 : 0) << riscv::ENV_CALL_VSMODE) |
                             (1 << riscv::INSTR_PAGE_FAULT) |
                             (1 << riscv::LOAD_PAGE_FAULT) |
                             (1 << riscv::STORE_PAGE_FAULT) |
                             ((G6LCCfg.RVH ? 1 : 0)  << riscv::INSTR_GUEST_PAGE_FAULT) |
                             ((G6LCCfg.RVH ? 1 : 0)  << riscv::LOAD_GUEST_PAGE_FAULT) |
                             ((G6LCCfg.RVH ? 1 : 0)  << riscv::VIRTUAL_INSTRUCTION) |
                             ((G6LCCfg.RVH ? 1 : 0)  << riscv::STORE_GUEST_PAGE_FAULT);
            rf_medeleg_d = (medeleg_q & ~rf_mask) | (csr_wdata & rf_mask);
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        // machine interrupt delegation register
        // we do not support user interrupt delegation
        riscv::CSR_MIDELEG: begin
          if (G6LCCfg.RVS) begin
            rf_mask = G6LCCfg.XLEN'(riscv::MIP_SSIP)
                    | G6LCCfg.XLEN'(riscv::MIP_STIP)
                    | G6LCCfg.XLEN'(riscv::MIP_SEIP);
            // Sscofpmf: LCOFI is delegable to S-mode.
            if (G6LCCfg.SscofpmfEn) rf_mask = rf_mask | G6LCCfg.XLEN'(riscv::MIP_LCOFIP);
            if (G6LCCfg.RVH) begin
              rf_mideleg_d = (mideleg_q & ~rf_mask) | (csr_wdata & rf_mask) | HS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0];
            end else begin
              rf_mideleg_d = (mideleg_q & ~rf_mask) | (csr_wdata & rf_mask);
            end
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        // rf_mask the register so that unsupported interrupts can never be set
        riscv::CSR_MIE: begin
          if (G6LCCfg.RVH) begin
            rf_mask = HS_DELEG_INTERRUPTS[G6LCCfg.XLEN-1:0]
                    | G6LCCfg.XLEN'(riscv::MIP_SSIP)
                    | G6LCCfg.XLEN'(riscv::MIP_STIP)
                    | G6LCCfg.XLEN'(riscv::MIP_SEIP)
                    | G6LCCfg.XLEN'(riscv::MIP_MSIP)
                    | G6LCCfg.XLEN'(riscv::MIP_MTIP)
                    | G6LCCfg.XLEN'(riscv::MIP_MEIP);
          end else begin
            if (G6LCCfg.RVS) begin
              rf_mask = G6LCCfg.XLEN'(riscv::MIP_SSIP)
                      | G6LCCfg.XLEN'(riscv::MIP_STIP)
                      | G6LCCfg.XLEN'(riscv::MIP_SEIP)
                      | G6LCCfg.XLEN'(riscv::MIP_MSIP)
                      | G6LCCfg.XLEN'(riscv::MIP_MTIP)
                      | G6LCCfg.XLEN'(riscv::MIP_MEIP);
            end else begin
              if (G6LCCfg.SoftwareInterruptEn) begin
                rf_mask = G6LCCfg.XLEN'(riscv::MIP_MSIP)  // same shift as MSIE
                | G6LCCfg.XLEN'(riscv::MIP_MTIP)  // same shift as MTIE
                | G6LCCfg.XLEN'(riscv::MIP_MEIP);  // same shift as MEIE
              end else begin
                rf_mask = G6LCCfg.XLEN'(riscv::MIP_MTIP)  // same shift as MTIE
                | G6LCCfg.XLEN'(riscv::MIP_MEIP);  // same shift as MEIE
              end
            end
          end
          // Sscofpmf: LCOFIE is always M-mode-writable when the extension is on.
          if (G6LCCfg.SscofpmfEn) rf_mask = rf_mask | G6LCCfg.XLEN'(riscv::MIP_LCOFIP);
          rf_mie_d = (mie_q & ~rf_mask) | (csr_wdata & rf_mask); // we only support supervisor and M-mode interrupts
        end

        riscv::CSR_MTVEC: begin
          logic DirVecOnly;
          DirVecOnly = G6LCCfg.DirectVecOnly ? 1'b0 : csr_wdata[0];
          rf_mtvec_d = {csr_wdata[G6LCCfg.XLEN-1:2], 1'b0, DirVecOnly};
          // we are in vector mode, this implementation requires the additional
          // alignment constraint of 64 * 4 bytes
          if (DirVecOnly) rf_mtvec_d = {csr_wdata[G6LCCfg.XLEN-1:8], 7'b0, DirVecOnly};
        end
        riscv::CSR_MCOUNTEREN: begin
          if (G6LCCfg.RVU) rf_mcounteren_d = {{G6LCCfg.XLEN - 32{1'b0}}, csr_wdata[31:0]};
          else rf_update_access_exception = 1'b1;
        end

        riscv::CSR_MSCRATCH: rf_mscratch_d = csr_wdata;
        riscv::CSR_MEPC: rf_mepc_d = {csr_wdata[G6LCCfg.XLEN-1:1], 1'b0};
        riscv::CSR_MCAUSE: rf_mcause_d = csr_wdata;
        riscv::CSR_MTVAL: begin
          if (G6LCCfg.TvalEn) rf_mtval_d = csr_wdata;
        end
        riscv::CSR_MTINST:
        if (G6LCCfg.RVH) rf_mtinst_d = {{G6LCCfg.XLEN - 32{1'b0}}, csr_wdata[31:0]};
        else rf_update_access_exception = 1'b1;
        riscv::CSR_MTVAL2:
        if (G6LCCfg.RVH) rf_mtval2_d = csr_wdata;
        else rf_update_access_exception = 1'b1;
        riscv::CSR_MIP: begin
          if (G6LCCfg.RVH) begin
            rf_mask = G6LCCfg.XLEN'(riscv::MIP_SSIP)
                    | G6LCCfg.XLEN'(riscv::MIP_STIP)
                    | G6LCCfg.XLEN'(riscv::MIP_SEIP)
                    | G6LCCfg.XLEN'(riscv::MIP_VSSIP);
          end else if (G6LCCfg.RVS) begin
            rf_mask = G6LCCfg.XLEN'(riscv::MIP_SSIP)
                    | G6LCCfg.XLEN'(riscv::MIP_STIP)
                    | G6LCCfg.XLEN'(riscv::MIP_SEIP);
          end else begin
            rf_mask = '0;
          end
          rf_mip_d = (mip_q & ~rf_mask) | (csr_wdata & rf_mask);
        end
        riscv::CSR_MENVCFG: begin
          if (G6LCCfg.RVU) begin
            rf_fiom_d = csr_wdata[0];
          end
          if (G6LCCfg.RVZiCbom) begin
            unique case (csr_wdata[5:4])
              2'b00:   rf_mcbie_d = riscv::CBIE_ILLEGAL;
              2'b01:   rf_mcbie_d = riscv::CBIE_FLUSH;
              2'b11:   rf_mcbie_d = riscv::CBIE_INVAL;
              default: rf_mcbie_d = riscv::CBIE_RSVD;
            endcase
            rf_mcbcfe_d = csr_wdata[6];
          end
          if (G6LCCfg.RVZiCboz) begin
            rf_mcbze_d = csr_wdata[7];
          end
          if (G6LCCfg.SvpbmtEn && G6LCCfg.IS_XLEN64) begin
            rf_mpbmte_d = csr_wdata[62];
          end
          // menvcfg.STCE (bit 63) is only present on RV64; RV32 uses menvcfgh.
          if (G6LCCfg.SstcEn && G6LCCfg.IS_XLEN64) begin
            rf_mstce_d = csr_wdata[G6LCCfg.XLEN-1];
          end
        end
        riscv::CSR_MENVCFGH: begin
          if (!G6LCCfg.RVU || !G6LCCfg.IS_XLEN32) rf_update_access_exception = 1'b1;
          // menvcfgh.STCE is menvcfg bit 63 on RV32.
          else if (G6LCCfg.SstcEn) rf_mstce_d = csr_wdata[31];
        end
        riscv::CSR_MCOUNTINHIBIT:
        if (G6LCCfg.PerfCounterEn)
          rf_mcountinhibit_d = {csr_wdata[MHPMCounterNum+2:2], 1'b0, csr_wdata[0]};
        else rf_mcountinhibit_d = '0;
        // performance counters
        riscv::CSR_MCYCLE: rf_cycle_d[G6LCCfg.XLEN-1:0] = csr_wdata;
        riscv::CSR_MCYCLEH:
        if (G6LCCfg.IS_XLEN32) rf_cycle_d[63:32] = csr_wdata[31:0];
        else rf_update_access_exception = 1'b1;
        riscv::CSR_MINSTRET: rf_instret_d[G6LCCfg.XLEN-1:0] = csr_wdata;
        riscv::CSR_MINSTRETH:
        if (G6LCCfg.IS_XLEN32) rf_instret_d[63:32] = csr_wdata[31:0];
        else rf_update_access_exception = 1'b1;
        //Event Selector
        riscv::CSR_MHPM_EVENT_3,
                riscv::CSR_MHPM_EVENT_4,
                riscv::CSR_MHPM_EVENT_5,
                riscv::CSR_MHPM_EVENT_6,
                riscv::CSR_MHPM_EVENT_7,
                riscv::CSR_MHPM_EVENT_8,
                riscv::CSR_MHPM_EVENT_9,
                riscv::CSR_MHPM_EVENT_10,
                riscv::CSR_MHPM_EVENT_11,
                riscv::CSR_MHPM_EVENT_12,
                riscv::CSR_MHPM_EVENT_13,
                riscv::CSR_MHPM_EVENT_14,
                riscv::CSR_MHPM_EVENT_15,
                riscv::CSR_MHPM_EVENT_16,
                riscv::CSR_MHPM_EVENT_17,
                riscv::CSR_MHPM_EVENT_18,
                riscv::CSR_MHPM_EVENT_19,
                riscv::CSR_MHPM_EVENT_20,
                riscv::CSR_MHPM_EVENT_21,
                riscv::CSR_MHPM_EVENT_22,
                riscv::CSR_MHPM_EVENT_23,
                riscv::CSR_MHPM_EVENT_24,
                riscv::CSR_MHPM_EVENT_25,
                riscv::CSR_MHPM_EVENT_26,
                riscv::CSR_MHPM_EVENT_27,
                riscv::CSR_MHPM_EVENT_28,
                riscv::CSR_MHPM_EVENT_29,
                riscv::CSR_MHPM_EVENT_30,
                riscv::CSR_MHPM_EVENT_31 :     begin
          rf_perf_we_o   = 1'b1;
          rf_perf_data_o = csr_wdata;
        end

        riscv::CSR_MHPM_COUNTER_3,
                riscv::CSR_MHPM_COUNTER_4,
                riscv::CSR_MHPM_COUNTER_5,
                riscv::CSR_MHPM_COUNTER_6,
                riscv::CSR_MHPM_COUNTER_7,
                riscv::CSR_MHPM_COUNTER_8,
                riscv::CSR_MHPM_COUNTER_9,
                riscv::CSR_MHPM_COUNTER_10,
                riscv::CSR_MHPM_COUNTER_11,
                riscv::CSR_MHPM_COUNTER_12,
                riscv::CSR_MHPM_COUNTER_13,
                riscv::CSR_MHPM_COUNTER_14,
                riscv::CSR_MHPM_COUNTER_15,
                riscv::CSR_MHPM_COUNTER_16,
                riscv::CSR_MHPM_COUNTER_17,
                riscv::CSR_MHPM_COUNTER_18,
                riscv::CSR_MHPM_COUNTER_19,
                riscv::CSR_MHPM_COUNTER_20,
                riscv::CSR_MHPM_COUNTER_21,
                riscv::CSR_MHPM_COUNTER_22,
                riscv::CSR_MHPM_COUNTER_23,
                riscv::CSR_MHPM_COUNTER_24,
                riscv::CSR_MHPM_COUNTER_25,
                riscv::CSR_MHPM_COUNTER_26,
                riscv::CSR_MHPM_COUNTER_27,
                riscv::CSR_MHPM_COUNTER_28,
                riscv::CSR_MHPM_COUNTER_29,
                riscv::CSR_MHPM_COUNTER_30,
                riscv::CSR_MHPM_COUNTER_31 :  begin
          rf_perf_we_o   = 1'b1;
          rf_perf_data_o = csr_wdata;
        end

        riscv::CSR_MHPM_COUNTER_3H,
                riscv::CSR_MHPM_COUNTER_4H,
                riscv::CSR_MHPM_COUNTER_5H,
                riscv::CSR_MHPM_COUNTER_6H,
                riscv::CSR_MHPM_COUNTER_7H,
                riscv::CSR_MHPM_COUNTER_8H,
                riscv::CSR_MHPM_COUNTER_9H,
                riscv::CSR_MHPM_COUNTER_10H,
                riscv::CSR_MHPM_COUNTER_11H,
                riscv::CSR_MHPM_COUNTER_12H,
                riscv::CSR_MHPM_COUNTER_13H,
                riscv::CSR_MHPM_COUNTER_14H,
                riscv::CSR_MHPM_COUNTER_15H,
                riscv::CSR_MHPM_COUNTER_16H,
                riscv::CSR_MHPM_COUNTER_17H,
                riscv::CSR_MHPM_COUNTER_18H,
                riscv::CSR_MHPM_COUNTER_19H,
                riscv::CSR_MHPM_COUNTER_20H,
                riscv::CSR_MHPM_COUNTER_21H,
                riscv::CSR_MHPM_COUNTER_22H,
                riscv::CSR_MHPM_COUNTER_23H,
                riscv::CSR_MHPM_COUNTER_24H,
                riscv::CSR_MHPM_COUNTER_25H,
                riscv::CSR_MHPM_COUNTER_26H,
                riscv::CSR_MHPM_COUNTER_27H,
                riscv::CSR_MHPM_COUNTER_28H,
                riscv::CSR_MHPM_COUNTER_29H,
                riscv::CSR_MHPM_COUNTER_30H,
                riscv::CSR_MHPM_COUNTER_31H :  begin
          rf_perf_we_o = 1'b1;
          if (G6LCCfg.IS_XLEN32) rf_perf_data_o = csr_wdata;
          else rf_update_access_exception = 1'b1;
        end

        riscv::CSR_DCACHE: rf_dcache_d = {{G6LCCfg.XLEN - 1{1'b0}}, csr_wdata[0]};  // enable bit
        riscv::CSR_ICACHE: rf_icache_d = {{G6LCCfg.XLEN - 1{1'b0}}, csr_wdata[0]};  // enable bit
        riscv::CSR_ACC_CONS: begin
          if (G6LCCfg.EnableAccelerator) begin
            rf_acc_cons_d = {{G6LCCfg.XLEN - 1{1'b0}}, csr_wdata[0]};  // enable bit
          end else begin
            rf_update_access_exception = 1'b1;
          end
        end
        // Xg6lcai AI matrix CSRs
        12'h801: begin  // aicfg
          if (G6LCCfg.AiCfg.MatrixEn) begin
            rf_aicfg_d = csr_wdata;
            // version field is read-only on grant path; keep contract version
            rf_aicfg_d[19:16] = 4'd1;
            // Downgrade unsupported ew/sp24 (isa-encoding.md §3.1)
            if (!G6LCCfg.AiCfg.Int4En) rf_aicfg_d[21:20] = 2'b00;
            if (!G6LCCfg.AiCfg.Sparse24En) rf_aicfg_d[22] = 1'b0;
          end else rf_update_access_exception = 1'b1;
        end
        12'h802: begin  // aistatus — software may write ais[7:6] for lazy enable
          if (G6LCCfg.AiCfg.MatrixEn) begin
            // Preserve hardware-owned busy/error unless software clears ais to Off
            rf_aistatus_d = aistatus_q;
            rf_aistatus_d[7:6] = csr_wdata[7:6];  // ais
            rf_aistatus_d[15:8] = csr_wdata[15:8];  // last error (SW clear)
            // If ais forced Off, drop dirty
            if (csr_wdata[7:6] == 2'b00) begin
              rf_aistatus_d[1] = 1'b0;
            end
          end else rf_update_access_exception = 1'b1;
        end
        12'h803: begin  // aiscale
          if (G6LCCfg.AiCfg.MatrixEn) rf_aiscale_d = csr_wdata;
          else rf_update_access_exception = 1'b1;
        end
        12'h804: begin  // aizp
          if (G6LCCfg.AiCfg.MatrixEn) rf_aizp_d = csr_wdata;
          else rf_update_access_exception = 1'b1;
        end
        12'h5C0: begin  // aiqbase
          if (G6LCCfg.AiCfg.MatrixEn && G6LCCfg.AiCfg.Queues != 0) rf_aiqbase_d = csr_wdata;
          else rf_update_access_exception = 1'b1;
        end
        12'h5C1: begin  // aiqctl
          if (G6LCCfg.AiCfg.MatrixEn && G6LCCfg.AiCfg.Queues != 0) rf_aiqctl_d = csr_wdata;
          else rf_update_access_exception = 1'b1;
        end
        12'h5C2: begin  // aiqhead
          if (G6LCCfg.AiCfg.MatrixEn && G6LCCfg.AiCfg.Queues != 0) rf_aiqhead_d = csr_wdata;
          else rf_update_access_exception = 1'b1;
        end
        12'h7C8: begin  // aiperm
          if (G6LCCfg.AiCfg.MatrixEn) begin
            if (!aiperm_q[3]) begin  // lock bit sticky once set
              rf_aiperm_d = {{G6LCCfg.XLEN - 4{1'b0}}, csr_wdata[3:0]};
            end
          end else rf_update_access_exception = 1'b1;
        end
        // PMP locked logic
        // 1. refuse to update any locked entry
        // 2. also refuse to update the entry below a locked TOR entry
        // Note that writes to pmpcfg below a locked TOR entry are valid
        riscv::CSR_PMPCFG0,
                riscv::CSR_PMPCFG1,
                riscv::CSR_PMPCFG2,
                riscv::CSR_PMPCFG3,
                riscv::CSR_PMPCFG4,
                riscv::CSR_PMPCFG5,
                riscv::CSR_PMPCFG6,
                riscv::CSR_PMPCFG7,
                riscv::CSR_PMPCFG8,
                riscv::CSR_PMPCFG9,
                riscv::CSR_PMPCFG10,
                riscv::CSR_PMPCFG11,
                riscv::CSR_PMPCFG12,
                riscv::CSR_PMPCFG13,
                riscv::CSR_PMPCFG14,
                riscv::CSR_PMPCFG15: begin
          // index is calculated using PMPCFG0 as the offset
          automatic logic [11:0] index = csr_addr.address[11:0] - riscv::CSR_PMPCFG0;

          // if index is not even and XLEN==64, raise exception
          if (G6LCCfg.IS_XLEN64 && index[0] == 1'b1) rf_update_access_exception = 1'b1;
          else begin
            for (int i = 0; i < G6LCCfg.XLEN / 8; i++) begin
              if (!pmpcfg_q[index*4+i].locked) rf_pmpcfg_d[index*4+i] = csr_wdata[i*8+:8];
            end
          end
        end
        riscv::CSR_PMPADDR0,
                riscv::CSR_PMPADDR1,
                riscv::CSR_PMPADDR2,
                riscv::CSR_PMPADDR3,
                riscv::CSR_PMPADDR4,
                riscv::CSR_PMPADDR5,
                riscv::CSR_PMPADDR6,
                riscv::CSR_PMPADDR7,
                riscv::CSR_PMPADDR8,
                riscv::CSR_PMPADDR9,
                riscv::CSR_PMPADDR10,
                riscv::CSR_PMPADDR11,
                riscv::CSR_PMPADDR12,
                riscv::CSR_PMPADDR13,
                riscv::CSR_PMPADDR14,
                riscv::CSR_PMPADDR15,
                riscv::CSR_PMPADDR16,
                riscv::CSR_PMPADDR17,
                riscv::CSR_PMPADDR18,
                riscv::CSR_PMPADDR19,
                riscv::CSR_PMPADDR20,
                riscv::CSR_PMPADDR21,
                riscv::CSR_PMPADDR22,
                riscv::CSR_PMPADDR23,
                riscv::CSR_PMPADDR24,
                riscv::CSR_PMPADDR25,
                riscv::CSR_PMPADDR26,
                riscv::CSR_PMPADDR27,
                riscv::CSR_PMPADDR28,
                riscv::CSR_PMPADDR29,
                riscv::CSR_PMPADDR30,
                riscv::CSR_PMPADDR31,
                riscv::CSR_PMPADDR32,
                riscv::CSR_PMPADDR33,
                riscv::CSR_PMPADDR34,
                riscv::CSR_PMPADDR35,
                riscv::CSR_PMPADDR36,
                riscv::CSR_PMPADDR37,
                riscv::CSR_PMPADDR38,
                riscv::CSR_PMPADDR39,
                riscv::CSR_PMPADDR40,
                riscv::CSR_PMPADDR41,
                riscv::CSR_PMPADDR42,
                riscv::CSR_PMPADDR43,
                riscv::CSR_PMPADDR44,
                riscv::CSR_PMPADDR45,
                riscv::CSR_PMPADDR46,
                riscv::CSR_PMPADDR47,
                riscv::CSR_PMPADDR48,
                riscv::CSR_PMPADDR49,
                riscv::CSR_PMPADDR50,
                riscv::CSR_PMPADDR51,
                riscv::CSR_PMPADDR52,
                riscv::CSR_PMPADDR53,
                riscv::CSR_PMPADDR54,
                riscv::CSR_PMPADDR55,
                riscv::CSR_PMPADDR56,
                riscv::CSR_PMPADDR57,
                riscv::CSR_PMPADDR58,
                riscv::CSR_PMPADDR59,
                riscv::CSR_PMPADDR60,
                riscv::CSR_PMPADDR61,
                riscv::CSR_PMPADDR62,
                riscv::CSR_PMPADDR63: begin
          // index is calculated using PMPADDR0 as the offset
          automatic logic [11:0] index = csr_addr.address[11:0] - riscv::CSR_PMPADDR0;
          // check if the entry or the entry above is locked
          if (!pmpcfg_q[index].locked && !(pmpcfg_q[index+1].locked && pmpcfg_q[index+1].addr_mode == riscv::TOR)) begin
            rf_pmpaddr_d[index] = csr_wdata[G6LCCfg.PLEN-3:0];
          end
        end
        default: rf_update_access_exception = 1'b1;
      endcase
    end
    if (G6LCCfg.IS_XLEN64) begin
      if (G6LCCfg.RVS) rf_mstatus_d.sxl = riscv::XLEN_64;
      else rf_mstatus_d.sxl = riscv::XLEN_NA;
      if (G6LCCfg.RVU) rf_mstatus_d.uxl = riscv::XLEN_64;
      else rf_mstatus_d.uxl = riscv::XLEN_NA;
    end
    if (!G6LCCfg.RVU) begin
      rf_mstatus_d.mpp = riscv::PRIV_LVL_M;
    end

    if (G6LCCfg.RVH) begin
      rf_hstatus_d.vsxl = riscv::XLEN_64;
      rf_vsstatus_d.uxl = riscv::XLEN_64;
    end
    // mark the floating point extension register as dirty
    if (G6LCCfg.FpPresent && (rf_dirty_fp_state_csr || dirty_fp_state_i)) begin
      rf_mstatus_d.fs = riscv::Dirty;
      if (G6LCCfg.RVH && v_q) begin
        rf_vsstatus_d.fs = riscv::Dirty;
      end
    end
    // mark the vector extension register as dirty
    if (G6LCCfg.RVV && dirty_v_state_i) begin
      rf_mstatus_d.vs = riscv::Dirty;
    end
    // AI coprocessor → CSR writeback (setcfg grant + dirty)
    if (G6LCCfg.AiCfg.MatrixEn) begin
      if (ai_setcfg_we_i) begin
        rf_aicfg_d = ai_setcfg_wdata_i;
        rf_aicfg_d[19:16] = 4'd1;  // version RO
        if (!G6LCCfg.AiCfg.Int4En) rf_aicfg_d[21:20] = 2'b00;
        if (!G6LCCfg.AiCfg.Sparse24En) rf_aicfg_d[22] = 1'b0;
        rf_aistatus_d[7:6] = 2'b11;  // Dirty
      end
      if (dirty_ai_state_i) begin
        rf_aistatus_d[7:6] = 2'b11;  // Dirty
        rf_aistatus_d[1]   = 1'b1;   // acc dirty sticky
      end
    end
    // AI-X: mstatus.xs is a read-only summary of aistatus.ais when the AI plane
    // is present; otherwise forced Off (spec-required hardwire). Writes to xs
    // are ignored (see mstatus/vsstatus write arms above).
    if (G6LCCfg.AiCfg.MatrixEn) begin
      rf_mstatus_d.xs = riscv::xs_t'(rf_aistatus_d[7:6]);
      if (G6LCCfg.RVH) begin
        rf_vsstatus_d.xs = riscv::xs_t'(rf_aistatus_d[7:6]);
      end
    end else begin
      rf_mstatus_d.xs = riscv::Off;
      if (G6LCCfg.RVH) begin
        rf_vsstatus_d.xs = riscv::Off;
      end
    end

    // hardwired extension registers
    if (G6LCCfg.RVS || G6LCCfg.RVF || G6LCCfg.AiCfg.MatrixEn) begin
      rf_mstatus_d.sd = (rf_mstatus_d.xs == riscv::Dirty) | (rf_mstatus_d.fs == riscv::Dirty);
    end else begin
      rf_mstatus_d.sd = 1'b0;
    end
    if (G6LCCfg.RVH) begin
      rf_vsstatus_d.sd = (rf_vsstatus_d.xs == riscv::Dirty) | (rf_vsstatus_d.fs == riscv::Dirty);
    end

    // reserve PMPCFG bits 5 and 6 (hardwire to 0)
    for (int i = 0; i < G6LCCfg.NrPMPEntries; i++) rf_pmpcfg_d[i].reserved = 2'b0;

    // write the floating point status register
    if (G6LCCfg.FpPresent && csr_write_fflags_i) begin
      rf_fcsr_d.fflags = csr_wdata_i[4:0] | fcsr_q.fflags;
    end

    // ----------------------------
    // Accelerator FP imprecise exceptions
    // ----------------------------

    // Update fflags as soon as a FP exception occurs in the accelerator
    // The exception is imprecise, and the fcsr.fflags update always happens immediately
    if (G6LCCfg.EnableAccelerator) begin
      rf_fcsr_d.fflags |= acc_fflags_ex_valid_i ? acc_fflags_ex_i : 5'b0;
    end

    // ---------------------
    // External Interrupts
    // ---------------------
    // Machine Mode External Interrupt Pending
    rf_mip_d[riscv::IRQ_M_EXT] = irq_i[0];
    // Machine software interrupt
    rf_mip_d[riscv::IRQ_M_SOFT] = G6LCCfg.SoftwareInterruptEn && ipi_i;
    // Timer interrupt pending, coming from platform timer
    rf_mip_d[riscv::IRQ_M_TIMER] = time_irq_i;
    // Sstc: with menvcfg.STCE set, STIP is no longer software-writable — it is a
    // pure function of (time >= stimecmp). This assignment sits after the CSR
    // write logic on purpose, so it overrides any write through mip/sip and
    // makes the bit effectively read-only, as the extension requires.
    if (G6LCCfg.SstcEn && mstce_q) begin
      rf_mip_d[riscv::IRQ_S_TIMER] = stimecmp_hit_q;
    end
    // U9.0 Sstc + H: VSTIP is hardwired from (time >= vstimecmp) when both
    // menvcfg.STCE and henvcfg.STCE are set (Sstc for VS-mode).
    if (G6LCCfg.SstcEn && G6LCCfg.RVH && mstce_q && hstce_q) begin
      rf_mip_d[riscv::IRQ_VS_TIMER] = vstimecmp_hit_q;
    end
    // Sscofpmf: LCOFIP tracks the OR of mhpmeventN.OF bits (cleared by writing OF=0).
    if (G6LCCfg.SscofpmfEn) begin
      rf_mip_d[riscv::IRQ_LCOF] = lcofi_i;
    end

    // -----------------------
    // Manage Exception Stack
    // -----------------------
    // update exception CSRs
    // we got an exception update cause, pc and stval register
    rf_trap_to_priv_lvl = riscv::PRIV_LVL_M;
    rf_trap_to_v = 1'b0;
    // Exception is taken and we are not in debug mode
    // exceptions in debug mode don't update any fields
    if ((G6LCCfg.DebugEn && !debug_mode_q && ex_i.cause != riscv::DEBUG_REQUEST && ex_i.valid) || (!G6LCCfg.DebugEn && ex_i.valid) || (!G6LCCfg.DebugEn && G6LCCfg.SDTRIG && break_from_trigger)) begin
      // do not flush, flush is reserved for CSR writes with side effects
      rf_flush_req = 1'b0;
      // figure out where to trap to
      // a m-mode trap might be delegated if we are taking it in S mode
      // first figure out if this was an exception or an interrupt e.g.: look at bit (XLEN-1)
      // the cause register can only be $clog2(G6LCCfg.XLEN) bits long (as we only support XLEN exceptions)
      if (G6LCCfg.RVS) begin
        if ((ex_i.cause[G6LCCfg.XLEN-1] && mideleg_q[ex_i.cause[$clog2(
                G6LCCfg.XLEN
            )-1:0]]) || (~ex_i.cause[G6LCCfg.XLEN-1] && medeleg_q[ex_i.cause[$clog2(
                G6LCCfg.XLEN
            )-1:0]])) begin
          // traps never transition from a more-privileged mode to a less privileged mode
          // so if we are already in M mode, stay there
          rf_trap_to_priv_lvl = (rf_priv_lvl_o == riscv::PRIV_LVL_M) ? riscv::PRIV_LVL_M : riscv::PRIV_LVL_S;
          if (G6LCCfg.RVH) begin
            if ((ex_i.cause[G6LCCfg.XLEN-1] && hideleg_q[ex_i.cause[$clog2(
                    G6LCCfg.XLEN
                )-1:0]]) || (~ex_i.cause[G6LCCfg.XLEN-1] && hedeleg_q[ex_i.cause[$clog2(
                    G6LCCfg.XLEN
                )-1:0]])) begin
              // trap to VS only if it is  the currently active mode
              rf_trap_to_v = v_q;
            end
          end
        end
      end

      // trap to supervisor mode
      if (G6LCCfg.RVS && rf_trap_to_priv_lvl == riscv::PRIV_LVL_S) begin
        if (G6LCCfg.RVH && rf_trap_to_v) begin
          // update sstatus
          rf_vsstatus_d.sie = 1'b0;
          rf_vsstatus_d.spie = (G6LCCfg.RVH) ? vsstatus_q.sie : '0;
          // this can either be user or supervisor mode
          rf_vsstatus_d.spp = priv_lvl_q[0];
          // set cause
          rf_vscause_d = ex_i.cause[G6LCCfg.XLEN-1] ? {ex_i.cause[G6LCCfg.XLEN-1:2], 2'b01} : ex_i.cause;
          // set epc
          rf_vsepc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{pc_i[G6LCCfg.VLEN-1]}}, pc_i};
          // set vstval
          rf_vstval_d        = (g6lc_core_pkg::ZERO_TVAL
                             && (ex_i.cause inside {
                             riscv::ILLEGAL_INSTR,
                             riscv::BREAKPOINT,
                             riscv::ENV_CALL_UMODE
                             } || ex_i.cause[G6LCCfg.XLEN-1])) ? '0 : ex_i.tval;
        end else begin
          // update sstatus
          rf_mstatus_d.sie = 1'b0;
          rf_mstatus_d.spie = mstatus_q.sie;
          // this can either be user or supervisor mode
          rf_mstatus_d.spp = priv_lvl_q[0];
          // set cause
          rf_scause_d = ex_i.cause;
          // set epc
          rf_sepc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{pc_i[G6LCCfg.VLEN-1]}}, pc_i};
          // set mtval or stval
          rf_stval_d        = (g6lc_core_pkg::ZERO_TVAL
                                  && (ex_i.cause inside {
                                    riscv::ILLEGAL_INSTR,
                                    riscv::BREAKPOINT,
                                    riscv::ENV_CALL_UMODE,
                                    riscv::ENV_CALL_SMODE,
                                    riscv::ENV_CALL_MMODE
                                  } || ex_i.cause[G6LCCfg.XLEN-1])) ? '0 : ex_i.tval;
          if (G6LCCfg.RVH) begin
            rf_htinst_d       = (g6lc_core_pkg::ZERO_TVAL
                              && (ex_i.cause inside {
                                riscv::INSTR_ACCESS_FAULT,
                                riscv::ILLEGAL_INSTR,
                                riscv::BREAKPOINT,
                                riscv::ENV_CALL_UMODE,
                                riscv::ENV_CALL_SMODE,
                                riscv::ENV_CALL_MMODE,
                                riscv::INSTR_PAGE_FAULT,
                                riscv::INSTR_GUEST_PAGE_FAULT,
                                riscv::VIRTUAL_INSTRUCTION
                              } || ex_i.cause[G6LCCfg.XLEN-1])) ? '0 : {{G6LCCfg.XLEN - 32 {1'b0}}, ex_i.tinst};
            rf_hstatus_d.spvp = v_q ? priv_lvl_q[0] : rf_hstatus_d.spvp;
            rf_htval_d = {{G6LCCfg.XLEN - G6LCCfg.GPLEN + 2{1'b0}}, ex_i.tval2[G6LCCfg.GPLEN-1:2]};
            rf_hstatus_d.gva = ex_i.gva;
            rf_hstatus_d.spv = v_q;
          end
        end
        // trap to machine mode
      end else begin
        // update mstatus
        rf_mstatus_d.mie = 1'b0;
        rf_mstatus_d.mpie = mstatus_q.mie;
        // save the previous privilege mode
        rf_mstatus_d.mpp = priv_lvl_q;
        rf_mcause_d = (break_from_trigger) ? G6LCCfg.XLEN'(32'h00000003) : ex_i.cause;
        // set epc
        rf_mepc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{pc_i[G6LCCfg.VLEN-1]}}, pc_i};
        // set mtval or stval
        if (G6LCCfg.TvalEn) begin
          rf_mtval_d        = (g6lc_core_pkg::ZERO_TVAL
                                    && (ex_i.cause inside {
                                      riscv::ILLEGAL_INSTR,
                                      riscv::BREAKPOINT,
                                      riscv::ENV_CALL_UMODE,
                                      riscv::ENV_CALL_SMODE,
                                      riscv::ENV_CALL_MMODE
                                    } || ex_i.cause[G6LCCfg.GPLEN-1])) ? '0 : ex_i.tval;
        end else begin
          rf_mtval_d = '0;
        end

        if (G6LCCfg.RVH) begin
          // save previous virtualization mode
          rf_mstatus_d.mpv = v_q;
          rf_mtinst_d       = (g6lc_core_pkg::ZERO_TVAL
                            && (ex_i.cause inside {
                              riscv::INSTR_ADDR_MISALIGNED,
                              riscv::INSTR_ACCESS_FAULT,
                              riscv::ILLEGAL_INSTR,
                              riscv::BREAKPOINT,
                              riscv::ENV_CALL_UMODE,
                              riscv::ENV_CALL_SMODE,
                              riscv::ENV_CALL_MMODE,
                              riscv::INSTR_PAGE_FAULT,
                              riscv::INSTR_GUEST_PAGE_FAULT,
                              riscv::VIRTUAL_INSTRUCTION
                            } || ex_i.cause[G6LCCfg.XLEN-1])) ? '0 : {{G6LCCfg.XLEN - 32 {1'b0}}, ex_i.tinst};
          rf_mtval2_d = {{G6LCCfg.XLEN - G6LCCfg.GPLEN + 2{1'b0}}, ex_i.tval2[G6LCCfg.GPLEN-1:2]};
          rf_mstatus_d.gva = ex_i.gva;
        end
      end

      rf_priv_lvl_d = rf_trap_to_priv_lvl;
      if (G6LCCfg.RVH) begin
        rf_v_d = rf_trap_to_v;
      end
    end

    // ------------------------------
    // Debug
    // ------------------------------
    // Explains why Debug Mode was entered.
    // When there are multiple reasons to enter Debug Mode in a single cycle, hardware should set cause to the cause with the highest priority.
    // 1: An ebreak instruction was executed. (priority 3)
    // 2: The Trigger Module caused a breakpoint exception. (priority 4)
    // 3: The debugger requested entry to Debug Mode. (priority 2)
    // 4: The hart single stepped because step was set. (priority 1)
    // we are currently not in debug mode and could potentially enter
    if (G6LCCfg.DebugEn && !debug_mode_q) begin
      rf_dcsr_d.prv = rf_priv_lvl_o;
      // save virtualization mode bit
      rf_dcsr_d.v   = (!G6LCCfg.RVH) ? 1'b0 : v_q;

      // trigger module fired
      if (G6LCCfg.SDTRIG && debug_from_trigger) begin
        rf_dcsr_d.prv = rf_priv_lvl_o;
        rf_dcsr_d.v = (!G6LCCfg.RVH) ? 1'b0 : v_q;
        rf_dpc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{pc_i[G6LCCfg.VLEN-1]}}, pc_i};
        rf_debug_mode_d = 1'b1;
        rf_set_debug_pc_o = 1'b1;
        rf_dcsr_d.cause = g6lc_core_pkg::CauseTrigger;
      end

      // caused by a breakpoint
      if (ex_i.valid && ex_i.cause == riscv::BREAKPOINT) begin
        rf_dcsr_d.prv = rf_priv_lvl_o;
        // save virtualization mode bit
        rf_dcsr_d.v   = (!G6LCCfg.RVH) ? 1'b0 : v_q;
        // check that we actually want to enter debug depending on the privilege level we are currently in
        unique case (rf_priv_lvl_o)
          riscv::PRIV_LVL_M: begin
            rf_debug_mode_d   = dcsr_q.ebreakm;
            rf_set_debug_pc_o = dcsr_q.ebreakm;
          end
          riscv::PRIV_LVL_S: begin
            if (G6LCCfg.RVS) begin
              rf_debug_mode_d   = (G6LCCfg.RVH && v_q) ? dcsr_q.ebreakvs : dcsr_q.ebreaks;
              rf_set_debug_pc_o = (G6LCCfg.RVH && v_q) ? dcsr_q.ebreakvs : dcsr_q.ebreaks;
            end
          end
          riscv::PRIV_LVL_U: begin
            if (G6LCCfg.RVU) begin
              rf_debug_mode_d   = (G6LCCfg.RVH && v_q) ? dcsr_q.ebreakvu : dcsr_q.ebreaku;
              rf_set_debug_pc_o = (G6LCCfg.RVH && v_q) ? dcsr_q.ebreakvu : dcsr_q.ebreaku;
            end
          end
          default: ;
        endcase
        // save PC of next this instruction e.g.: the next one to be executed
        rf_dpc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{pc_i[G6LCCfg.VLEN-1]}}, pc_i};
        rf_dcsr_d.cause = g6lc_core_pkg::CauseBreakpoint;
      end

      // we've got a debug request
      if (ex_i.valid && ex_i.cause == riscv::DEBUG_REQUEST) begin
        rf_dcsr_d.prv = rf_priv_lvl_o;
        rf_dcsr_d.v = (!G6LCCfg.RVH) ? 1'b0 : v_q;
        // save the PC
        rf_dpc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{pc_i[G6LCCfg.VLEN-1]}}, pc_i};
        // enter debug mode
        rf_debug_mode_d = 1'b1;
        // jump to the base address
        rf_set_debug_pc_o = 1'b1;
        // save the cause as external debug request
        rf_dcsr_d.cause = g6lc_core_pkg::CauseRequest;
      end

      // single step enable and we just retired an instruction
      if (dcsr_q.step && commit_ack_i[0]) begin
        rf_dcsr_d.prv = rf_priv_lvl_o;
        rf_dcsr_d.v   = (!G6LCCfg.RVH) ? 1'b0 : v_q;
        // valid CTRL flow change
        if (commit_instr_i.fu == CTRL_FLOW) begin
          // we saved the correct target address during execute
          rf_dpc_d = {
            {G6LCCfg.XLEN - G6LCCfg.VLEN{commit_instr_i.bp.predict_address[G6LCCfg.VLEN-1]}},
            commit_instr_i.bp.predict_address
          };
          // exception valid
        end else if (ex_i.valid) begin
          rf_dpc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{1'b0}}, trap_vector_base_o};
          // return from environment
        end else if (rf_eret_o) begin
          rf_dpc_d = {{G6LCCfg.XLEN - G6LCCfg.VLEN{1'b0}}, epc_o};
          // consecutive PC
        end else begin
          rf_dpc_d = {
            {G6LCCfg.XLEN - G6LCCfg.VLEN{commit_instr_i.pc[G6LCCfg.VLEN-1]}},
            commit_instr_i.pc + (commit_instr_i.is_compressed ? 'h2 : 'h4)
          };
        end
        rf_debug_mode_d   = 1'b1;
        rf_set_debug_pc_o = 1'b1;
        rf_dcsr_d.cause   = g6lc_core_pkg::CauseSingleStep;
      end
    end
    // go in halt-state again when we encounter an exception
    if (G6LCCfg.DebugEn && debug_mode_q && ex_i.valid && ex_i.cause == riscv::BREAKPOINT) begin
      rf_set_debug_pc_o = 1'b1;
    end

    // ------------------------------
    // MPRV - Modify Privilege Level
    // ------------------------------
    // Set the address translation at which the load and stores should occur
    // we can use the previous values since changing the address translation will always involve a pipeline flush
    if (G6LCCfg.RVH) begin
      if (mprv && (mstatus_q.mpv == 1'b0) && (config_pkg::vm_mode_t'(satp_q.mode) == G6LCCfg.MODE_SV) && (mstatus_q.mpp != riscv::PRIV_LVL_M)) begin
        rf_en_ld_st_translation_d = 1'b1;
      end else if (mprv && (mstatus_q.mpv == 1'b1)) begin
        if (config_pkg::vm_mode_t'(vsatp_q.mode) == G6LCCfg.MODE_SV) begin
          rf_en_ld_st_translation_d = 1'b1;
        end else begin
          rf_en_ld_st_translation_d = 1'b0;
        end
      end else begin  // otherwise we go with the regular settings
        rf_en_ld_st_translation_d = en_translation_o;
      end

      if (mprv && (mstatus_q.mpv == 1'b1)) begin
        if (config_pkg::vm_mode_t'(hgatp_q.mode) == G6LCCfg.MODE_SV) begin
          rf_en_ld_st_g_translation_d = 1'b1;
        end else begin
          rf_en_ld_st_g_translation_d = 1'b0;
        end
      end else begin
        rf_en_ld_st_g_translation_d = en_g_translation_o;
      end

      if (csr_hs_ld_st_inst_i) rf_ld_st_priv_lvl_o = riscv::priv_lvl_t'(hstatus_q.spvp);
      else rf_ld_st_priv_lvl_o = (mprv) ? mstatus_q.mpp : rf_priv_lvl_o;

      rf_ld_st_v_o = ((mprv ? mstatus_q.mpv : v_q) || (csr_hs_ld_st_inst_i));

      rf_en_ld_st_translation_o = (en_ld_st_translation_q && !csr_hs_ld_st_inst_i) || (config_pkg::vm_mode_t'(vsatp_q.mode) == G6LCCfg.MODE_SV && csr_hs_ld_st_inst_i);

      rf_en_ld_st_g_translation_o = (en_ld_st_g_translation_q && !csr_hs_ld_st_inst_i) || (csr_hs_ld_st_inst_i && config_pkg::vm_mode_t'(hgatp_q.mode) == G6LCCfg.MODE_SV && csr_hs_ld_st_inst_i);
    end else begin
      if (G6LCCfg.MmuPresent && mprv && G6LCCfg.RVS && config_pkg::vm_mode_t'(satp_q.mode) == G6LCCfg.MODE_SV && (mstatus_q.mpp != riscv::PRIV_LVL_M))
        rf_en_ld_st_translation_d = 1'b1;
      else  // otherwise we go with the regular settings
        rf_en_ld_st_translation_d = en_translation_o;

      if (G6LCCfg.RVU) begin
        rf_ld_st_priv_lvl_o = (mprv) ? mstatus_q.mpp : rf_priv_lvl_o;
      end else begin
        rf_ld_st_priv_lvl_o = rf_priv_lvl_o;
      end
      rf_en_ld_st_translation_o = en_ld_st_translation_q;
      rf_ld_st_v_o = 1'b0;
      rf_en_ld_st_g_translation_o = 1'b0;
    end
    // ------------------------------
    // Return from Environment
    // ------------------------------
    // When executing an xRET instruction, supposing xPP holds the value y, xIE is set to xPIE; the privilege
    // mode is changed to y; xPIE is set to 1; and xPP is set to U
    if (mret) begin
      // return from exception, IF doesn't care from where we are returning
      rf_eret_o        = 1'b1;
      // return to the previous privilege level and restore all enable flags
      // get the previous machine interrupt enable flag
      rf_mstatus_d.mie = mstatus_q.mpie;
      // restore the previous privilege level
      rf_priv_lvl_d    = mstatus_q.mpp;
      rf_mstatus_d.mpp = riscv::PRIV_LVL_M;
      if (G6LCCfg.RVU) begin
        // set mpp to user mode
        rf_mstatus_d.mpp = riscv::PRIV_LVL_U;
      end
      // set mpie to 1
      rf_mstatus_d.mpie = 1'b1;
      if (G6LCCfg.RVH) begin
        // set virtualization mode
        rf_v_d           = mstatus_q.mpv;
        //set mstatus mpv to false
        rf_mstatus_d.mpv = 1'b0;
        if (mstatus_q.mpp != riscv::PRIV_LVL_M) rf_mstatus_d.mprv = 1'b0;
      end
    end

    if (G6LCCfg.RVS && sret && ((G6LCCfg.RVH && !v_q) || !G6LCCfg.RVH)) begin
      // return from exception, IF doesn't care from where we are returning
      rf_eret_o         = 1'b1;
      // return the previous supervisor interrupt enable flag
      rf_mstatus_d.sie  = mstatus_q.spie;
      // restore the previous privilege level
      rf_priv_lvl_d     = riscv::priv_lvl_t'({1'b0, mstatus_q.spp});
      // set spp to user mode
      rf_mstatus_d.spp  = 1'b0;
      // set spie to 1
      rf_mstatus_d.spie = 1'b1;
      if (G6LCCfg.RVH) begin
        // set virtualization mode
        rf_v_d            = hstatus_q.spv;
        //set hstatus spv to false
        rf_hstatus_d.spv  = 1'b0;
        rf_mstatus_d.mprv = 1'b0;
      end
    end

    if (G6LCCfg.RVH) begin
      if (sret && v_q) begin
        // return from exception, IF doesn't care from where we are returning
        rf_eret_o          = 1'b1;
        // return the previous supervisor interrupt enable flag
        rf_vsstatus_d.sie  = vsstatus_q.spie;
        // restore the previous privilege level
        rf_priv_lvl_d      = riscv::priv_lvl_t'({1'b0, vsstatus_q.spp});
        // set spp to user mode
        rf_vsstatus_d.spp  = 1'b0;
        // set spie to 1
        rf_vsstatus_d.spie = 1'b1;
      end
    end

    // return from debug mode
    if (G6LCCfg.DebugEn) begin
      if (dret) begin
        // return from exception, IF doesn't care from where we are returning
        rf_eret_o     = 1'b1;
        // restore the previous privilege level
        rf_priv_lvl_d = riscv::priv_lvl_t'(dcsr_q.prv);
        if (G6LCCfg.RVH) begin
          // restore the previous virtualization mode
          rf_v_d = dcsr_q.v;
        end
        // actually return from debug mode
        rf_debug_mode_d = 1'b0;
      end
    end
  end

  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_acc_cons_d == acc_cons_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: acc_cons_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_aicfg_d == aicfg_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: aicfg_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_aiperm_d == aiperm_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: aiperm_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_aiqbase_d == aiqbase_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: aiqbase_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_aiqctl_d == aiqctl_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: aiqctl_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_aiqhead_d == aiqhead_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: aiqhead_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_aiscale_d == aiscale_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: aiscale_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_aistatus_d == aistatus_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: aistatus_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_aizp_d == aizp_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: aizp_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_cycle_d == cycle_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: cycle_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_dcache_d == dcache_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: dcache_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_dcsr_d == dcsr_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: dcsr_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_debug_mode_d == debug_mode_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: debug_mode_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_dirty_fp_state_csr == dirty_fp_state_csr)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: dirty_fp_state_csr");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_dpc_d == dpc_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: dpc_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_dscratch0_d == dscratch0_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: dscratch0_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_dscratch1_d == dscratch1_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: dscratch1_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_en_ld_st_g_translation_d == en_ld_st_g_translation_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: en_ld_st_g_translation_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_en_ld_st_g_translation_o == en_ld_st_g_translation_o)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: en_ld_st_g_translation_o");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_en_ld_st_translation_d == en_ld_st_translation_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: en_ld_st_translation_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_en_ld_st_translation_o == en_ld_st_translation_o)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: en_ld_st_translation_o");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_eret_o == eret_o)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: eret_o");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_fcsr_d == fcsr_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: fcsr_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_fiom_d == fiom_d)
