  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_flush_req == flush_req)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: flush_req");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_hcbcfe_d == hcbcfe_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: hcbcfe_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_hcbie_d == hcbie_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: hcbie_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_hcbze_d == hcbze_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: hcbze_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_hcounteren_d == hcounteren_d)
