  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_hgatp_d == hgatp_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: hgatp_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_hgeie_d == hgeie_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: hgeie_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_hideleg_d == hideleg_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: hideleg_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_hstatus_d == hstatus_d)
