  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_mcbcfe_d == mcbcfe_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: mcbcfe_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_mcbie_d == mcbie_d)
