  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_mcountinhibit_d == mcountinhibit_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: mcountinhibit_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_medeleg_d == medeleg_d)
