  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_mip_d == mip_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: mip_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_mpbmte_d == mpbmte_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: mpbmte_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_mscratch_d == mscratch_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: mscratch_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_mstatus_d == mstatus_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: mstatus_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_mstce_d == mstce_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: mstce_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_mtinst_d == mtinst_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: mtinst_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_mtval2_d == mtval2_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: mtval2_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_mtval_d == mtval_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: mtval_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_mtvec_d == mtvec_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: mtvec_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_perf_data_o == perf_data_o)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: perf_data_o");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_perf_we_o == perf_we_o)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: perf_we_o");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_pmpaddr_d == pmpaddr_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: pmpaddr_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_pmpcfg_d == pmpcfg_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: pmpcfg_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_priv_lvl_d == priv_lvl_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: priv_lvl_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_priv_lvl_o == priv_lvl_o)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: priv_lvl_o");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_satp_d == satp_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: satp_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_scause_d == scause_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: scause_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_scbcfe_d == scbcfe_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: scbcfe_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_scbie_d == scbie_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: scbie_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_scbze_d == scbze_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: scbze_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_scontext_d == scontext_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: scontext_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_scounteren_d == scounteren_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: scounteren_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_sepc_d == sepc_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: sepc_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_set_debug_pc_o == set_debug_pc_o)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: set_debug_pc_o");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_sscratch_d == sscratch_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: sscratch_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_stimecmp_d == stimecmp_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: stimecmp_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_stval_d == stval_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: stval_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_stvec_d == stvec_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: stvec_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_tdata1_to_tm == tdata1_to_tm)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: tdata1_to_tm");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_tdata1_we == tdata1_we)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: tdata1_we");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_tdata2_to_tm == tdata2_to_tm)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: tdata2_to_tm");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_tdata2_we == tdata2_we)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: tdata2_we");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_tdata3_to_tm == tdata3_to_tm)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: tdata3_to_tm");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_tdata3_we == tdata3_we)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: tdata3_we");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_trap_to_priv_lvl == trap_to_priv_lvl)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: trap_to_priv_lvl");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_trap_to_v == trap_to_v)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: trap_to_v");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_tselect_to_tm == tselect_to_tm)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: tselect_to_tm");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_tselect_we == tselect_we)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: tselect_we");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_update_access_exception == update_access_exception)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: update_access_exception");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_v_d == v_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: v_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_virtual_update_access_exception == virtual_update_access_exception)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: virtual_update_access_exception");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_vsatp_d == vsatp_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: vsatp_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_vscause_d == vscause_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: vscause_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_vsepc_d == vsepc_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: vsepc_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_vsscratch_d == vsscratch_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: vsscratch_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_vsstatus_d == vsstatus_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: vsstatus_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_vstimecmp_d == vstimecmp_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: vstimecmp_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_vstval_d == vstval_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: vstval_d");
  assert property (@(posedge clk_i) disable iff (!rst_ni) rf_vstvec_d == vstvec_d)
    else $fatal(1, "csr_regfile hyp8 two-phase split mismatch: vstvec_d");
  logic fp_live_ref;
  assign fp_live_ref = G6LCCfg.FpPresent && !(mstatus_q.fs == riscv::Off
      || (G6LCCfg.RVH && v_q && vsstatus_q.fs == riscv::Off));
  assert property (@(posedge clk_i) disable iff (!rst_ni) fp_live == fp_live_ref)
    else $fatal(1, "csr_regfile fp_live mismatch");
  assert property (@(posedge clk_i) disable iff (!rst_ni) conv_csr_addr ==
      ((G6LCCfg.RVH) ? riscv::convert_vs_access_csr(riscv::csr_t'(csr_addr12), v_q)
                     : riscv::csr_t'(csr_addr12)))
    else $fatal(1, "csr_regfile conv_csr_addr mismatch");
  //pragma translate_on

  always_comb begin : privilege_check
    if (G6LCCfg.RVH) begin
      automatic riscv::priv_lvl_t access_priv;
      automatic riscv::priv_lvl_t curr_priv;
      automatic logic [SELECT_COUNTER_WIDTH-1:0] sel_cnt_en;
      // transforms S mode accesses into HS mode
      access_priv = (priv_lvl_o == riscv::PRIV_LVL_S && !v_q) ? riscv::PRIV_LVL_HS : priv_lvl_o;
      curr_priv = priv_lvl_o;
      sel_cnt_en = {{SELECT_COUNTER_WIDTH - 5{1'b0}}, req_addr[4:0]};
      // -----------------
      // Privilege Check
      // -----------------
      privilege_violation = 1'b0;
      virtual_privilege_violation = 1'b0;
      // if we are reading or writing, check for the correct privilege level this has
      // precedence over interrupts
      if (req_op inside {CSR_WRITE, CSR_SET, CSR_CLEAR, CSR_READ}) begin
        if (access_priv < csr_addr.csr_decode.priv_lvl) begin
          if (v_q && csr_addr.csr_decode.priv_lvl <= riscv::PRIV_LVL_HS)
            virtual_privilege_violation = 1'b1;
          else privilege_violation = 1'b1;
        end
        // check access to debug mode only CSRs
        if ((!G6LCCfg.DebugEn && req_addr[11:4] == 8'h7b) || (G6LCCfg.DebugEn && req_addr[11:4] == 8'h7b && !debug_mode_q)) begin
          privilege_violation = 1'b1;
        end
        // check counter-enabled counter CSR accesses
        // counter address range is C00 to C1F
        if (G6LCCfg.RVZihpm) begin
          if (req_addr inside {[riscv::CSR_HPM_COUNTER_3 : riscv::CSR_HPM_COUNTER_31]} |
              req_addr inside {[riscv::CSR_HPM_COUNTER_3H : riscv::CSR_HPM_COUNTER_31H]}) begin
            if (curr_priv == riscv::PRIV_LVL_S && G6LCCfg.RVS) begin
              virtual_privilege_violation = v_q & mcounteren_q[sel_cnt_en] & ~hcounteren_q[sel_cnt_en];
              privilege_violation = ~mcounteren_q[sel_cnt_en];
            end else if (priv_lvl_o == riscv::PRIV_LVL_U && G6LCCfg.RVU) begin
              virtual_privilege_violation = v_q & mcounteren_q[sel_cnt_en] & ~hcounteren_q[sel_cnt_en];
              if (v_q) begin
                privilege_violation = ~mcounteren_q[sel_cnt_en] & ~scounteren_q[sel_cnt_en] & hcounteren_q[sel_cnt_en];
              end else begin
                privilege_violation = ~mcounteren_q[sel_cnt_en] & ~scounteren_q[sel_cnt_en];
              end
            end else if (priv_lvl_o == riscv::PRIV_LVL_M) begin
              privilege_violation = 1'b0;
            end
          end
        end
        if (G6LCCfg.RVZicntr) begin
          if (req_addr inside {[riscv::CSR_CYCLE : riscv::CSR_INSTRET]} |
              req_addr inside {[riscv::CSR_CYCLEH : riscv::CSR_INSTRETH]}) begin
            if (curr_priv == riscv::PRIV_LVL_S && G6LCCfg.RVS) begin
              virtual_privilege_violation = v_q & mcounteren_q[sel_cnt_en] & ~hcounteren_q[sel_cnt_en];
              privilege_violation = ~mcounteren_q[sel_cnt_en];
            end else if (priv_lvl_o == riscv::PRIV_LVL_U && G6LCCfg.RVU) begin
              virtual_privilege_violation = v_q & mcounteren_q[sel_cnt_en] & ~hcounteren_q[sel_cnt_en];
              if (v_q) begin
                privilege_violation = ~mcounteren_q[sel_cnt_en] & ~scounteren_q[sel_cnt_en] & hcounteren_q[sel_cnt_en];
              end else begin
                privilege_violation = ~mcounteren_q[sel_cnt_en] & ~scounteren_q[sel_cnt_en];
              end
            end else if (priv_lvl_o == riscv::PRIV_LVL_M) begin
              privilege_violation = 1'b0;
            end
          end
        end
      end
    end else begin
      // -----------------
      // Privilege Check
      // -----------------
      privilege_violation = 1'b0;
      // if we are reading or writing, check for the correct privilege level this has
      // precedence over interrupts
      if (req_op inside {CSR_WRITE, CSR_SET, CSR_CLEAR, CSR_READ}) begin
        if (G6LCCfg.RVU && (riscv::priv_lvl_t'(priv_lvl_o & csr_addr.csr_decode.priv_lvl) != csr_addr.csr_decode.priv_lvl)) begin
          privilege_violation = 1'b1;
        end
        // check access to debug mode only CSRs
        if ((!G6LCCfg.DebugEn && req_addr[11:4] == 8'h7b) || (G6LCCfg.DebugEn && req_addr[11:4] == 8'h7b && !debug_mode_q)) begin
          privilege_violation = 1'b1;
        end
        // check counter-enabled counter CSR accesses
        // counter address range is C00 to C1F
        if (G6LCCfg.RVZihpm) begin
          if (req_addr inside {[riscv::CSR_HPM_COUNTER_3 : riscv::CSR_HPM_COUNTER_31]} |
              req_addr inside {[riscv::CSR_HPM_COUNTER_3H : riscv::CSR_HPM_COUNTER_31H]}) begin
            if (priv_lvl_o == riscv::PRIV_LVL_S && G6LCCfg.RVS) begin
              privilege_violation = ~mcounteren_q[{1'b0, req_addr[4:0]}];
            end else if (priv_lvl_o == riscv::PRIV_LVL_U && G6LCCfg.RVU) begin
              privilege_violation = ~mcounteren_q[{1'b0, req_addr[4:0]}] | ~scounteren_q[{1'b0, req_addr[4:0]}];
            end else if (priv_lvl_o == riscv::PRIV_LVL_M) begin
              privilege_violation = 1'b0;
            end
          end
        end
        if (G6LCCfg.RVZicntr) begin
          if (req_addr inside {[riscv::CSR_CYCLE : riscv::CSR_INSTRET]} |
              req_addr inside {[riscv::CSR_CYCLEH : riscv::CSR_INSTRETH]}) begin
            if (priv_lvl_o == riscv::PRIV_LVL_S && G6LCCfg.RVS) begin
              privilege_violation = ~mcounteren_q[{1'b0, req_addr[4:0]}];
            end else if (priv_lvl_o == riscv::PRIV_LVL_U && G6LCCfg.RVU) begin
              privilege_violation = ~mcounteren_q[{1'b0, req_addr[4:0]}] | ~scounteren_q[{1'b0, req_addr[4:0]}];
            end else if (priv_lvl_o == riscv::PRIV_LVL_M) begin
              privilege_violation = 1'b0;
            end
          end
        end
      end
    end
  end
  // -------------------
  // Wait for Interrupt
  // -------------------
  always_comb begin : wfi_ctrl
    // wait for interrupt register
    wfi_d = wfi_q;
    // if there is any (enabled) interrupt pending un-stall the core
    // also un-stall if we want to enter debug mode
    if (|(mip_q & mie_q) || (G6LCCfg.DebugEn && debug_req_i) || irq_i[1]) begin
      wfi_d = 1'b0;
      // or alternatively if there is no exception pending and we are not in debug mode wait here
      // for the interrupt
    end else if (((G6LCCfg.DebugEn && !debug_mode_q) && req_op == WFI && !ex_i.valid) || (!G6LCCfg.DebugEn && req_op == WFI && !ex_i.valid)) begin
      wfi_d = 1'b1;
    end
  end

  // -------------------
  // Output Assignments
  // -------------------
  always_comb begin
    // When the SEIP bit is read with a CSRRW, CSRRS, or CSRRC instruction, the value
    // returned in the rd destination register contains the logical-OR of the software-writable
    // bit and the interrupt signal from the interrupt controller.
    csr_rdata_o = csr_rdata;

    unique case (conv_csr_addr.address)
      riscv::CSR_MIP:
      csr_rdata_o = csr_rdata | ({{G6LCCfg.XLEN - 1{1'b0}}, G6LCCfg.RVS && irq_i[1]} << riscv::IRQ_S_EXT);
      // in supervisor mode we also need to check whether we delegated this bit
      riscv::CSR_SIP: begin
        if (G6LCCfg.RVS) begin
          csr_rdata_o = csr_rdata
                              | ({{G6LCCfg.XLEN-1{1'b0}}, (irq_i[1] & mideleg_q[riscv::IRQ_S_EXT])} << riscv::IRQ_S_EXT);
        end
      end
      default: ;
    endcase
  end

  // in debug mode we execute with privilege level M
  assign priv_lvl_o = (G6LCCfg.DebugEn && debug_mode_q) ? riscv::PRIV_LVL_M : priv_lvl_q;
  assign v_o = G6LCCfg.RVH ? v_q : 1'b0;
  // FPU outputs
  assign fflags_o = fcsr_q.fflags;
  assign frm_o = fcsr_q.frm;
  assign fprec_o = fcsr_q.fprec;
  //JVT outputs
  if (G6LCCfg.RVZCMT) begin
    assign jvt_o.base = jvt_q.base;
    assign jvt_o.mode = jvt_q.mode;
  end else begin
    assign jvt_o.base = '0;
    assign jvt_o.mode = '0;
  end
  // MMU outputs
  assign satp_ppn_o  = G6LCCfg.RVS ? satp_q.ppn : '0;
  assign vsatp_ppn_o = G6LCCfg.RVH ? vsatp_q.ppn : '0;
  assign hgatp_ppn_o = G6LCCfg.RVH ? hgatp_q.ppn : '0;
  if (G6LCCfg.RVS) begin
    assign asid_o = satp_q.asid[G6LCCfg.ASID_WIDTH-1:0];
  end else begin
    assign asid_o = '0;
  end
  assign vs_asid_o = G6LCCfg.RVH ? vsatp_q.asid[G6LCCfg.ASID_WIDTH-1:0] : '0;
  assign vmid_o = G6LCCfg.RVH ? hgatp_q.vmid[G6LCCfg.VMID_WIDTH-1:0] : '0;
  assign sum_o = mstatus_q.sum;
  assign vs_sum_o = G6LCCfg.RVH ? vsstatus_q.sum : '0;
  assign hu_o = G6LCCfg.RVH ? hstatus_q.hu : '0;

  assign mcbie_o = G6LCCfg.RVZiCbom ? mcbie_q : riscv::CBIE_ILLEGAL;
  assign scbie_o = G6LCCfg.RVZiCbom ? scbie_q : riscv::CBIE_ILLEGAL;
  assign hcbie_o = G6LCCfg.RVZiCbom ? hcbie_q : riscv::CBIE_ILLEGAL;

  assign mcbcfe_o = G6LCCfg.RVZiCbom ? mcbcfe_q : 1'b0;
  assign scbcfe_o = G6LCCfg.RVZiCbom ? scbcfe_q : 1'b0;
  assign hcbcfe_o = G6LCCfg.RVZiCbom ? hcbcfe_q : 1'b0;

  assign mcbze_o = G6LCCfg.RVZiCboz ? mcbze_q : 1'b0;
  assign scbze_o = G6LCCfg.RVZiCboz ? scbze_q : 1'b0;
  assign hcbze_o = G6LCCfg.RVZiCboz ? hcbze_q : 1'b0;
  assign pbmte_o = G6LCCfg.SvpbmtEn ? mpbmte_q : 1'b0;
  // we support bare memory addressing and SV39
  if (G6LCCfg.RVH) begin
    assign en_translation_o = (((config_pkg::vm_mode_t'(satp_q.mode) == G6LCCfg.MODE_SV && !v_q) || (config_pkg::vm_mode_t'(vsatp_q.mode) == G6LCCfg.MODE_SV && v_q)) &&
                               priv_lvl_o != riscv::PRIV_LVL_M)
                              ? 1'b1
                              : 1'b0;
    assign en_g_translation_o = (config_pkg::vm_mode_t'(hgatp_q.mode) == G6LCCfg.MODE_SV &&
                               priv_lvl_o != riscv::PRIV_LVL_M && v_q)
                              ? 1'b1
                              : 1'b0;
  end else begin
    assign en_translation_o = (G6LCCfg.RVS && config_pkg::vm_mode_t'(satp_q.mode) == G6LCCfg.MODE_SV &&
                              priv_lvl_o != riscv::PRIV_LVL_M)
                             ? 1'b1
                             : 1'b0;
    assign en_g_translation_o = 1'b0;
  end
  assign mxr_o  = mstatus_q.mxr;
  assign vmxr_o = G6LCCfg.RVH ? vsstatus_q.mxr : '0;
  if (G6LCCfg.RVH) begin
    assign tvm_o = (v_q) ? hstatus_q.vtvm : mstatus_q.tvm;
  end else begin
    assign tvm_o = mstatus_q.tvm;
  end
  assign tw_o  = mstatus_q.tw;
  assign vtw_o = G6LCCfg.RVH ? hstatus_q.vtw : '0;
  if (G6LCCfg.RVH) begin
    assign tsr_o = (v_q) ? hstatus_q.vtsr : mstatus_q.tsr;
  end else begin
    assign tsr_o = mstatus_q.tsr;
  end
  assign halt_csr_o = wfi_q;
  // Everything that clears wfi_q in wfi_ctrl, one edge earlier: the enabled external
  // lines as they enter mip_d, the registered-but-stable software pending bits, the
  // Sstc comparators (combinational from the ungated rtc_time_i), SEIP and debug.
  always_comb begin : wfi_wake
    wfi_wake_o = (|(mip_q & mie_q)) || (G6LCCfg.DebugEn && debug_req_i) || irq_i[1];
    if (irq_i[0] && mie_q[riscv::IRQ_M_EXT]) wfi_wake_o = 1'b1;
    if (G6LCCfg.SoftwareInterruptEn && ipi_i && mie_q[riscv::IRQ_M_SOFT]) wfi_wake_o = 1'b1;
    if (time_irq_i && mie_q[riscv::IRQ_M_TIMER]) wfi_wake_o = 1'b1;
    if (G6LCCfg.SstcEn && mstce_q && stimecmp_hit_d && mie_q[riscv::IRQ_S_TIMER])
      wfi_wake_o = 1'b1;
    if (G6LCCfg.SstcEn && G6LCCfg.RVH && mstce_q && hstce_q && vstimecmp_hit_d &&
        mie_q[riscv::IRQ_VS_TIMER])
      wfi_wake_o = 1'b1;
  end
`ifdef PITON_G6LC
  assign icache_en_o = icache_q[0];
`else
  assign icache_en_o = icache_q[0] & ~(G6LCCfg.DebugEn && debug_mode_q);
`endif
  assign dcache_en_o = dcache_q[0];
  assign acc_cons_en_o = G6LCCfg.EnableAccelerator ? acc_cons_q[0] : 1'b0;
  // Xg6lcai sideband to CVXIF coprocessor
  assign ai_aicfg_o = G6LCCfg.AiCfg.MatrixEn ? aicfg_q : '0;
  assign ai_ais_o   = G6LCCfg.AiCfg.MatrixEn ? aistatus_q[7:6] : 2'b00;
  assign ai_q_en_o  = G6LCCfg.AiCfg.MatrixEn && (G6LCCfg.AiCfg.Queues != 0) && aiqctl_q[0];
  assign ai_qid_o   = G6LCCfg.AiCfg.MatrixEn ? aiqctl_q[15:8] : 8'h0;

  // aiperm privilege gate (isa-encoding.md §4/§6). Machine always issues.
  always_comb begin
    ai_issue_ok_o = 1'b0;
    if (G6LCCfg.AiCfg.MatrixEn) begin
      unique case (priv_lvl_q)
        riscv::PRIV_LVL_M: ai_issue_ok_o = 1'b1;
        riscv::PRIV_LVL_S: ai_issue_ok_o = v_q ? aiperm_q[2] : aiperm_q[1];
        riscv::PRIV_LVL_U: ai_issue_ok_o = aiperm_q[0];
        default:           ai_issue_ok_o = 1'b0;
      endcase
    end
  end

  // determine if mprv needs to be considered if in debug mode
  assign mprv = (G6LCCfg.DebugEn && debug_mode_q && !dcsr_q.mprven) ? 1'b0 : mstatus_q.mprv;
  assign debug_mode_o = G6LCCfg.DebugEn ? debug_mode_q : 1'b0;
  assign single_step_o = G6LCCfg.DebugEn ? dcsr_q.step : 1'b0;
  assign mcountinhibit_o = {{29 - MHPMCounterNum{1'b0}}, mcountinhibit_q};

  assign mbe_o = mstatus_q.mbe;

  // sequential process
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (~rst_ni) begin
      priv_lvl_q <= riscv::PRIV_LVL_M;
      // floating-point registers
      fcsr_q     <= '0;
      if (G6LCCfg.RVZCMT) begin
        jvt_q <= '0;
      end
      // debug signals
      if (G6LCCfg.DebugEn) begin
        debug_mode_q <= 1'b0;
        dcsr_q       <= '{xdebugver: 4'h4, prv: riscv::PRIV_LVL_M, default: '0};
        dpc_q        <= '0;
        dscratch0_q  <= {G6LCCfg.XLEN{1'b0}};
        dscratch1_q  <= {G6LCCfg.XLEN{1'b0}};
      end
      // machine mode registers
      mstatus_q        <= 64'b0;
      // set to boot address + direct mode + 4 byte offset which is the initial trap
      mtvec_rst_load_q <= 1'b1;
      mtvec_q          <= '0;
      mip_q            <= {G6LCCfg.XLEN{1'b0}};
      mie_q            <= {G6LCCfg.XLEN{1'b0}};
      mepc_q           <= {G6LCCfg.XLEN{1'b0}};
      mcause_q         <= {G6LCCfg.XLEN{1'b0}};
      mcounteren_q     <= {G6LCCfg.XLEN{1'b0}};
      mscratch_q       <= {G6LCCfg.XLEN{1'b0}};
      if (G6LCCfg.TvalEn) mtval_q <= {G6LCCfg.XLEN{1'b0}};
      fiom_q          <= '0;
      stimecmp_q      <= '0;
      mstce_q         <= 1'b0;
      stimecmp_hit_q  <= 1'b0;
      vstimecmp_q     <= '0;
      hstce_q         <= 1'b0;
      vstimecmp_hit_q <= 1'b0;
      guest_time_q    <= '0;
      htimedelta_q    <= '0;
      dcache_q        <= {{G6LCCfg.XLEN - 1{1'b0}}, 1'b1};
      icache_q        <= {{G6LCCfg.XLEN - 1{1'b0}}, 1'b1};
      mcountinhibit_q <= '0;
      acc_cons_q      <= {{G6LCCfg.XLEN - 1{1'b0}}, G6LCCfg.EnableAccelerator};
      // Xg6lcai defaults: ais=Initial when plane present; aicfg geometry from package
      if (G6LCCfg.AiCfg.MatrixEn) begin
        aicfg_q <= '0;
        aicfg_q[3:0]   <= 4'($clog2(G6LCCfg.AiCfg.TileM == 0 ? 1 : G6LCCfg.AiCfg.TileM));
        aicfg_q[7:4]   <= 4'($clog2(G6LCCfg.AiCfg.TileN == 0 ? 1 : G6LCCfg.AiCfg.TileN));
        aicfg_q[11:8]  <= 4'($clog2(G6LCCfg.AiCfg.TileK == 0 ? 1 : G6LCCfg.AiCfg.TileK));
        aicfg_q[15:14] <= 2'b01;  // accumulate
        aicfg_q[19:16] <= 4'd1;   // contract version
        aistatus_q     <= '0;
        aistatus_q[7:6] <= 2'b01;  // Initial (Table 101)
        aiscale_q      <= '0;
        aizp_q         <= '0;
        aiqbase_q      <= '0;
        aiqctl_q       <= '0;
        aiqhead_q      <= '0;
        aiperm_q       <= '0;
        aiperm_q[0]    <= G6LCCfg.AiCfg.UmodeEn;
        aiperm_q[1]    <= 1'b1;  // S-mode issue allowed by default
      end else begin
        aicfg_q    <= '0;
        aistatus_q <= '0;
        aiscale_q  <= '0;
        aizp_q     <= '0;
        aiqbase_q  <= '0;
        aiqctl_q   <= '0;
        aiqhead_q  <= '0;
        aiperm_q   <= '0;
      end
      if (G6LCCfg.RVZiCbom) begin
        mcbie_q  <= riscv::CBIE_INVAL;
        mcbcfe_q <= 1'b1;
      end
      if (G6LCCfg.RVZiCboz) begin
        mcbze_q <= 1'b1;  // CBZE defaults enabled like CBCFE
      end
      if (G6LCCfg.SvpbmtEn) begin
        mpbmte_q <= 1'b0;  // software must opt in via menvcfg.PBMTE
      end
      // supervisor mode registers
      if (G6LCCfg.RVS) begin
        medeleg_q    <= {G6LCCfg.XLEN{1'b0}};
        mideleg_q    <= {G6LCCfg.XLEN{1'b0}};
        sepc_q       <= {G6LCCfg.XLEN{1'b0}};
        scause_q     <= {G6LCCfg.XLEN{1'b0}};
        stvec_q      <= {G6LCCfg.XLEN{1'b0}};
        scounteren_q <= {G6LCCfg.XLEN{1'b0}};
        sscratch_q   <= {G6LCCfg.XLEN{1'b0}};
        stval_q      <= {G6LCCfg.XLEN{1'b0}};
        satp_q       <= {G6LCCfg.XLEN{1'b0}};
        if (G6LCCfg.RVZiCbom) begin
          scbie_q  <= riscv::CBIE_INVAL;
          scbcfe_q <= 1'b1;
        end
        if (G6LCCfg.RVZiCboz) scbze_q <= 1'b1;
      end

      if (G6LCCfg.RVH) begin
        v_q                      <= '0;
        mtval2_q                 <= {G6LCCfg.XLEN{1'b0}};
        mtinst_q                 <= {G6LCCfg.XLEN{1'b0}};
        hstatus_q                <= 64'b0;
        hedeleg_q                <= {G6LCCfg.XLEN{1'b0}};
        hideleg_q                <= {G6LCCfg.XLEN{1'b0}};
        hgeie_q                  <= {G6LCCfg.XLEN{1'b0}};
        hgatp_q                  <= {G6LCCfg.XLEN{1'b0}};
        hcounteren_q             <= {G6LCCfg.XLEN{1'b0}};
        htval_q                  <= {G6LCCfg.XLEN{1'b0}};
        htinst_q                 <= {G6LCCfg.XLEN{1'b0}};
        // virtual supervisor mode registers
        vsstatus_q               <= 64'b0;
        vsepc_q                  <= {G6LCCfg.XLEN{1'b0}};
        vscause_q                <= {G6LCCfg.XLEN{1'b0}};
        vstvec_q                 <= {G6LCCfg.XLEN{1'b0}};
        vsscratch_q              <= {G6LCCfg.XLEN{1'b0}};
        vstval_q                 <= {G6LCCfg.XLEN{1'b0}};
        vsatp_q                  <= {G6LCCfg.XLEN{1'b0}};
        en_ld_st_g_translation_q <= 1'b0;
        if (G6LCCfg.RVZiCbom) begin
          hcbie_q  <= riscv::CBIE_INVAL;
          hcbcfe_q <= 1'b1;
        end
        if (G6LCCfg.RVZiCboz) hcbze_q <= 1'b1;
      end
      if (G6LCCfg.SDTRIG) begin
        scontext_q <= '0;
      end
      // timer and counters
      cycle_q                <= 64'b0;
      instret_q              <= 64'b0;
      // aux registers
      en_ld_st_translation_q <= 1'b0;
      // wait for interrupt
      wfi_q                  <= 1'b0;
      // pmp
      for (int i = 0; i < 64; i++) begin
        if (i < G6LCCfg.NrPMPEntries) begin
          pmpcfg_q[i]  <= riscv::pmpcfg_t'(G6LCCfg.PMPCfgRstVal[i]);
          pmpaddr_q[i] <= G6LCCfg.PMPAddrRstVal[i][G6LCCfg.PLEN-3:0];
        end else begin
          pmpcfg_q[i]  <= '0;
          pmpaddr_q[i] <= '0;
        end
      end
    end else begin
      priv_lvl_q <= priv_lvl_d;
      // floating-point registers
      fcsr_q     <= fcsr_d;
      if (G6LCCfg.RVZCMT) begin
        jvt_q <= jvt_d;
      end
      // debug signals
      if (G6LCCfg.DebugEn) begin
        debug_mode_q <= debug_mode_d;
        dcsr_q       <= dcsr_d;
        dpc_q        <= dpc_d;
        dscratch0_q  <= dscratch0_d;
        dscratch1_q  <= dscratch1_d;
      end
      // machine mode registers
      mstatus_q        <= mstatus_d;
      mtvec_rst_load_q <= 1'b0;
      mtvec_q          <= mtvec_d;
      mip_q            <= mip_d;
      mie_q            <= mie_d;
      mepc_q           <= mepc_d;
      mcause_q         <= mcause_d;
      mcounteren_q     <= mcounteren_d;
      mscratch_q       <= mscratch_d;
      if (G6LCCfg.TvalEn) mtval_q <= mtval_d;
      fiom_q          <= fiom_d;
      stimecmp_q      <= stimecmp_d;
      mstce_q         <= mstce_d;
      stimecmp_hit_q  <= stimecmp_hit_d;
      vstimecmp_q     <= vstimecmp_d;
      hstce_q         <= hstce_d;
      vstimecmp_hit_q <= vstimecmp_hit_d;
      guest_time_q    <= guest_time;
      htimedelta_q    <= htimedelta_d;
      dcache_q        <= dcache_d;
      icache_q        <= icache_d;
      mcountinhibit_q <= mcountinhibit_d;
      acc_cons_q      <= acc_cons_d;
      if (G6LCCfg.AiCfg.MatrixEn) begin
        aicfg_q    <= aicfg_d;
        aistatus_q <= aistatus_d;
        aiscale_q  <= aiscale_d;
        aizp_q     <= aizp_d;
        aiqbase_q  <= aiqbase_d;
        aiqctl_q   <= aiqctl_d;
        aiqhead_q  <= aiqhead_d;
        aiperm_q   <= aiperm_d;
      end
      if (G6LCCfg.RVZiCbom) begin
        mcbie_q  <= mcbie_d;
        mcbcfe_q <= mcbcfe_d;
      end
      if (G6LCCfg.RVZiCboz) mcbze_q <= mcbze_d;
      if (G6LCCfg.SvpbmtEn) mpbmte_q <= mpbmte_d;
      // supervisor mode registers
      if (G6LCCfg.RVS) begin
        medeleg_q    <= medeleg_d;
        mideleg_q    <= mideleg_d;
        sepc_q       <= sepc_d;
        scause_q     <= scause_d;
        stvec_q      <= stvec_d;
        scounteren_q <= scounteren_d;
        sscratch_q   <= sscratch_d;
        if (G6LCCfg.TvalEn) stval_q <= stval_d;
        satp_q <= satp_d;
        if (G6LCCfg.RVZiCbom) begin
          scbie_q  <= scbie_d;
          scbcfe_q <= scbcfe_d;
        end
        if (G6LCCfg.RVZiCboz) scbze_q <= scbze_d;
      end
      if (G6LCCfg.RVH) begin
        v_q                      <= v_d;
        mtval2_q                 <= mtval2_d;
        mtinst_q                 <= mtinst_d;
        // hypervisor mode registers
        hstatus_q                <= hstatus_d;
        hedeleg_q                <= hedeleg_d;
        hideleg_q                <= hideleg_d;
        hgeie_q                  <= hgeie_d;
        hgatp_q                  <= hgatp_d;
        hcounteren_q             <= hcounteren_d;
        htval_q                  <= htval_d;
        htinst_q                 <= htinst_d;
        // virtual supervisor mode registers
        vsstatus_q               <= vsstatus_d;
        vsepc_q                  <= vsepc_d;
        vscause_q                <= vscause_d;
        vstvec_q                 <= vstvec_d;
        vsscratch_q              <= vsscratch_d;
        vstval_q                 <= vstval_d;
        vsatp_q                  <= vsatp_d;
        en_ld_st_g_translation_q <= en_ld_st_g_translation_d;
        if (G6LCCfg.RVZiCbom) begin
          hcbie_q  <= hcbie_d;
          hcbcfe_q <= hcbcfe_d;
        end
        if (G6LCCfg.RVZiCboz) hcbze_q <= hcbze_d;
      end
      if (G6LCCfg.SDTRIG) begin
        scontext_q <= scontext_d;
      end
      // timer and counters
      cycle_q                <= cycle_d;
      instret_q              <= instret_d;
      // aux registers
      en_ld_st_translation_q <= en_ld_st_translation_d;
      // wait for interrupt
      wfi_q                  <= wfi_d;
      // pmp
      pmpcfg_q               <= pmpcfg_next;
      pmpaddr_q              <= pmpaddr_next;
    end
  end

  assign debug_from_trigger_o = debug_from_mcontrol;  // from trigger module to id stage
  assign break_from_trigger_o = break_from_trigger;  // from trigger module to commit stage

  // write logic pmp
  always_comb begin : write
    for (int i = 0; i < 64; i++) begin
      if (i < G6LCCfg.NrPMPEntries) begin
        if (!G6LCCfg.PMPEntryReadOnly[i]) begin
          // PMP locked logic is handled in the CSR write process above
          pmpcfg_next[i] = pmpcfg_d[i];
          // We only support >=8-byte granularity, NA4 is not supported
          if ((!G6LCCfg.PMPNapotEn && pmpcfg_d[i].addr_mode == riscv::NAPOT) ||pmpcfg_d[i].addr_mode == riscv::NA4) begin
            pmpcfg_next[i].addr_mode = pmpcfg_q[i].addr_mode;
          end
          // Follow collective WARL spec for RWX fields
          if (pmpcfg_d[i].access_type.r == '0 && pmpcfg_d[i].access_type.w == '1) begin
            pmpcfg_next[i].access_type = pmpcfg_q[i].access_type;
          end
        end else begin
          pmpcfg_next[i] = pmpcfg_q[i];
        end
        if (!G6LCCfg.PMPEntryReadOnly[i]) begin
          pmpaddr_next[i] = pmpaddr_d[i];
        end else begin
          pmpaddr_next[i] = pmpaddr_q[i];
        end
      end else begin
        pmpcfg_next[i]  = '0;
        pmpaddr_next[i] = '0;
      end
    end
  end

  //-------------
  // Trigger Module
  //-------------
  generate
    if (G6LCCfg.SDTRIG) begin : tm_gen
      trigger_module #(
          .G6LCCfg           (G6LCCfg),
          .exception_t       (exception_t),
          .scoreboard_entry_t(scoreboard_entry_t),
          .N_Triggers        (N_Triggers)
      ) trigger_module_i (
          .clk_i,
          .rst_ni,
          .commit_instr_i       (commit_instr_i),
          .commit_ack_i         (commit_ack_i),
          .ex_i                 (ex_i),
          .vaddr_from_lsu_i     (vaddr_from_lsu_i),
          .orig_instr_i         (orig_instr_i),
          .store_result_i       (store_result_i),
          .priv_lvl_i           (priv_lvl_o),
          .debug_mode_i         (debug_mode_q),
          .mret_i               (mret),
          .sret_i               (sret),
          .scontext_i           (scontext_q),
          .tselect_i            (tselect_to_tm),
          .tdata1_i             (tdata1_to_tm),
          .tdata2_i             (tdata2_to_tm),
          .tdata3_i             (tdata3_to_tm),
          .tselect_we           (tselect_we),
          .tdata1_we            (tdata1_we),
          .tdata2_we            (tdata2_we),
          .tdata3_we            (tdata3_we),
          .tselect_o            (tselect_from_tm),
          .tdata1_o             (tdata1_from_tm),
          .tdata2_o             (tdata2_from_tm),
          .tdata3_o             (tdata3_from_tm),
          .flush_o              (flush_from_tm),
          // debug/break request from TM
          .debug_from_trigger_o (debug_from_trigger),
          .break_from_trigger_o (break_from_trigger),
          .debug_from_mcontrol_o(debug_from_mcontrol)
      );
    end else begin
      assign tdata1_from_tm = '0;
      assign tdata2_from_tm = '0;
      assign tdata3_from_tm = '0;
      assign tselect_from_tm = '0;
      assign flush_from_tm = 0;
      assign debug_from_trigger = 0;
      assign break_from_trigger = 0;
      assign debug_from_mcontrol = 0;
    end
  endgenerate

  //-------------
  // Assertions
  //-------------
  //pragma translate_off
  // check that eret and ex are never valid together
  assert property (@(posedge clk_i) disable iff (!rst_ni !== '0) !(eret_o && ex_i.valid))
  else begin
    $error("eret and exception should never be valid at the same time");
    $stop();
  end
  // Core sleep gate contract: wfi_wake_o must cover every reason wfi_q can clear, or a
  // gated core would miss the edge it needed. The only wake source outside it is a
  // counter-overflow interrupt (lcofi_i), which cannot arise while the clock is gated.
  assert property (@(posedge clk_i) disable iff (!rst_ni !== '0)
                   (wfi_q && !wfi_wake_o && !lcofi_i) |=> wfi_q)
  else begin
    $error("wfi_q cleared without wfi_wake_o: the core sleep gate would have missed this wake-up");
    $stop();
  end
  //pragma translate_on


  //RVFI CSR

  //-------------
  // RVFI
  //-------------
  assign rvfi_csr_o.fcsr_q = G6LCCfg.FpPresent ? fcsr_q : '0;
  assign rvfi_csr_o.jvt_q = G6LCCfg.RVZCMT ? jvt_q : '0;
  assign rvfi_csr_o.dcsr_q = G6LCCfg.DebugEn ? dcsr_q : '0;
  assign rvfi_csr_o.dpc_q = G6LCCfg.DebugEn ? dpc_q : '0;
  assign rvfi_csr_o.dscratch0_q = G6LCCfg.DebugEn ? dscratch0_q : '0;
  assign rvfi_csr_o.dscratch1_q = G6LCCfg.DebugEn ? dscratch1_q : '0;
  assign rvfi_csr_o.mie_q = mie_q;
  assign rvfi_csr_o.mip_q = mip_q;
  assign rvfi_csr_o.stvec_q = G6LCCfg.RVS ? stvec_q : '0;
  assign rvfi_csr_o.scounteren_q = G6LCCfg.RVS ? scounteren_q : '0;
  assign rvfi_csr_o.sscratch_q = G6LCCfg.RVS ? sscratch_q : '0;
  assign rvfi_csr_o.sepc_q = G6LCCfg.RVS ? sepc_q : '0;
  assign rvfi_csr_o.scause_q = G6LCCfg.RVS ? scause_q : '0;
  assign rvfi_csr_o.stval_q = G6LCCfg.RVS ? stval_q : '0;
  assign rvfi_csr_o.satp_q = G6LCCfg.RVS ? satp_q : '0;
  assign rvfi_csr_o.mstatus_extended = mstatus_extended;
  assign rvfi_csr_o.medeleg_q = G6LCCfg.RVS ? medeleg_q : '0;
  assign rvfi_csr_o.mideleg_q = G6LCCfg.RVS ? mideleg_q : '0;
  assign rvfi_csr_o.mtvec_q = mtvec_q;
  assign rvfi_csr_o.mcounteren_q = mcounteren_q;
  assign rvfi_csr_o.mscratch_q = mscratch_q;
  assign rvfi_csr_o.mepc_q = mepc_q;
  assign rvfi_csr_o.mcause_q = mcause_q;
  assign rvfi_csr_o.mtval_q = G6LCCfg.TvalEn ? mtval_q : '0;
  assign rvfi_csr_o.fiom_q = fiom_q;
  assign rvfi_csr_o.mcountinhibit_q = mcountinhibit_q;
  assign rvfi_csr_o.cycle_q = cycle_q;
  assign rvfi_csr_o.instret_q = instret_q;
  assign rvfi_csr_o.dcache_q = dcache_q;
  assign rvfi_csr_o.icache_q = icache_q;
  assign rvfi_csr_o.acc_cons_q = G6LCCfg.EnableAccelerator ? acc_cons_q : '0;
  assign rvfi_csr_o.aicfg_q = G6LCCfg.AiCfg.MatrixEn ? aicfg_q : '0;
  assign rvfi_csr_o.aistatus_q = G6LCCfg.AiCfg.MatrixEn ? aistatus_q : '0;
  assign rvfi_csr_o.pmpcfg_q = pmpcfg_q;
  assign rvfi_csr_o.pmpaddr_q = pmpaddr_q;


endmodule

